/* ÇEVİRİ ja · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ja","olay",{
"OLAYLAR_EK14:1846-11-29:0":{"b": ["デデ・エフェンディ、巡礼の際にミナーで死去", "c3e613a2"], "d": ["ハッジの義務を果たすために赴いたミナーでコレラに罹ったハンマーミーザーデ・イスマイル・デデ・エフェンディは、1846年11月29日に没した。1824-1839年のあいだに7つの別々のメヴレヴィー儀礼曲を作曲した芸術家の死により、古典オスマン音楽の一時代が閉じた。", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["1850年商法典の採択", "8ac085fd"], "d": ["タンジマート期の法改革の枠組みのなかで、西洋諸国から翻訳と借用により新しい法が取り入れられた。刑法は1840年に、商法は1850年に、土地法は1857年に施行された。商法典(Ticaret Kanunnâmesi)は、オスマン商法の最初の近代的な法典化であった。", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["クリミア・タタール人とカフカスの諸民族のオスマン領への大規模な移住の波の開始", "8832c06d"], "d": ["シャミールが1859年にロシアの捕虜となった後、クリミア・タタール人とともに、カフカスから多数のチェルケス人とノガイ人の移民がオスマン領に移住し始めた。この移住の波は、1877-78年の露土戦争の後まで、様々な強さで続いた。", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["移民委員会(Muhâcirîn Komisyonu)の設置", "9717e77e"], "d": ["カフカスからの増大する移住の波を管理するため、オスマン政府は1860年1月16日に移民委員会を設けた。委員会は、アナトリア、バルカン、シリアにおける定住の作業を調整し、1875年まで活動した。", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Bank-ı Osmanîの Bank-ı Osmanî-i Şâhâne(オスマン銀行)としての再編", "c3530456"], "d": ["1856年にクリミア戦争の後、対外債務の支払いを管理するために、ロンドンを本拠とするイギリス資本のBank-ı Osmanîが設立されていた。1863年にフランス・イギリス合同のグループに、Bank-ı Osmanî-i Şâhâne(オスマン銀行)の名で新しい銀行を設立する許可が与えられた。機関はのちに銀行券を発行する権限も得た。", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Cem'iyyet-i Tedrîsiyye-i İslâmiyyeの設立", "77ad553a"], "d": ["貧しいムスリムの徒弟の教育を担う目的で、1864年3月30日にCem'iyyet-i Tedrîsiyye-i İslâmiyyeが設立された。この民間団体の試みは、慈善機関の伝統が近代的な学校の企画に変わる先駆的な例である。団体は9年後にダルシュシャファカ(Darüşşafaka)を開くことになる。", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["1864年州規則によるムフタール職と長老会議制度の整備", "1a2e8cf2"], "d": ["1864年の州規則(Vilâyet Nizamnâmesi)により、村の統治が再編された。ムスリムと非ムスリムが共に住む村では、各共同体が自らのムフタールと長老会議(ihtiyar meclisi)を選ぶことが認められた。長老会議はこうして初めて、村・街区の統治に正式な位置を得た。", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["大チェルケス人追放のピーク", "b2ab1874"], "d": ["ロシアによる1858-1878年のカフカス占領、とりわけ最も激しかった1861-1864年に、120万から150万のチェルケス人がオスマン領に強制的に移住させられた。TDVによれば、多数の研究者がこの出来事を「近代史における最初の民族浄化の動き」と性格づけている。", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["1869年一般教育規則(Maârif-i Umûmiyye Nizamnâmesi)の公布", "787f6022"], "d": ["1869年9月1日に公布された一般教育規則は、地方と中央における一般教育を定めた最初の包括的な文書となった。規則により大教育評議会(Meclis-i Kebîr-i Maârif)が設けられた。小学校(sıbyan mektepleri)を単なる宗教教育の段階から外し、読み書きの教育に向けて再構成することが、この規定により始まった。", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["ダルシュシャファカ学校が教育を開始", "525c457c"], "d": ["Cem'iyyet-i Tedrîsiyye-i İslâmiyyeが設立したダルシュシャファカは、1873年6月28日に、孤児と貧しいムスリムの子どもを無償の寄宿で教育するため、実際に授業を始めた。入学年齢は最大10歳と定められた。", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["1894年のイスタンブル地震", "7ae7f648"], "d": ["1894年7月10日にイズミト湾沖で起きた地震は、イスタンブルを激しく襲った。イスタンブルの城壁を含む多くのモスクと歴史的建造物が被害を受けた。TDVのzelzele項は、この地震を1509年、1719年、1766年の地震とともに、マルマラ地方に多大な人的・物的損害をもたらした地震に数える。", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["ダールラージェゼ(Dârülaceze)の開設", "a30baf31"], "d": ["アブデュルハミト2世が1890年から出した命令に基づいて準備されたダールラージェゼは、1896年2月2日に大宰相Halil Rifat Paşaにより開かれた。身寄りのない子ども、高齢者、困窮者を収容した機関は、200床の病院、工房、モスク・教会・シナゴーグなど別々の礼拝所を備え、当時最大の社会福祉の複合体であった。", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["帝国大学(ダーリュルフュヌーン・シャーハーネ)が恒久的機関として再設立", "7d6d8fc4"], "d": ["ダーリュルフュヌーン(大学)は、それ以前の二つの失敗した試み(1863年と1870年)の後、1900年8月31日に帝国大学(ダーリュルフュヌーン・シャーハーネ)の名で恒久的な機関として再設立された。TDVはこの日付を、今日のトルコの大学制度の直接の基礎と位置づけている。", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["サルバダール朝がサブザヴァールを奪取——ホラーサーンにおけるイル・ハン国以後の最初の国家", "af997fec"], "d": ["アブー・サイードの死(1335年11月30日)によりイル・ハン国の中央の権威が崩れると、ホラーサーンで徴税官に対して蓄積した反発がバーシュティーンで爆発した。アブドゥッラッザークは1337年3月13日に蜂起し、1337年9月9日(ヒジュラ暦738年サファル月12日)にサブザヴァールを奪った。「サルバダール(Serbedâr)」——「首が絞首台にある者」——の名は、敗れれば絞首刑を覚悟するという彼ら自身の言葉である。", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["マルアシー家のサイイドがアーモルを奪取——マーザンダラーンにおけるサイイドの支配", "c0e03266"], "d": ["サイイド・キワームッディーン・マルアシーは、サルバダール朝がホラーサーンで開いた道を行き、ヒジュラ暦760年(1359年)にアーモルを奪って、カスピ海の南岸にサイイドの国家を築いた。王朝はサーリー、バールフルーシュと周辺に広がり、ティムールの遠征で揺らぎ、サファヴィー朝のシャー・アッバース1世の時代に解体された。", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["カールキヤー朝がギーラーンに成立——カスピ海沿岸の最後の独立の支配者", "6e5f9db7"], "d": ["アリー・キヤーは家族とともにギーラーンに戻り、ヒジュラ暦773年(1371-72年)にラーヒージャーンを中心とするカールキヤー朝の支配を築いた。王朝はカスピ海の南西岸を2世紀以上保持し、サファヴィー朝のシャー・アッバース1世が1592年に地方を併合するまで続いた。", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["ダルフールにおけるダージュー(Dâcû)の支配のトゥンジュール(Tuncûr)への移行", "6eb22a2a"], "d": ["TDV『イスラーム百科事典』のDârfûr項によれば、地域に最初に定住し、最初の国家を築いたのはダージュー部族である。13世紀と14世紀を通じてここを支配したダージュー人は、商業上の支配をトゥンジュール人に奪われ、15世紀には、とりわけ中部の状況が完全にトゥンジュール人に有利に転じた。", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["スペインによるバーディス(Peñón de Vélez)の岩礁の奪回", "0dc52728"], "d": ["TDVのSa'dîler項は、スペイン人がバーディスを奪ったことがマグリブの航海に重い打撃であったと記す(1564年)。北モロッコの沿岸にあるこの岩礁の拠点は、西地中海における海賊行為とオスマン・スペインの争いの拠り所となっていた。", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["アル=アラーイシュ(ララシュ)のスペインへの譲渡", "7b8f6e27"], "d": ["サアド朝が分裂した内戦の年に、大西洋岸のアル=アラーイシュ港はスペインに譲られた。TDVのSa'dîler項は、この時期に国がマラケシュ(南)とフェズ(北)の首長国に二分され、王位争いの当事者が外からの援助を求めたと記す。港は80年近くスペインの手にあり、1689年にムーレイ・イスマーイールが奪い返すことになる。", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["マモーラ(マフディーヤ)のスペイン人の手への移行", "c8fd494e"], "d": ["セブー川の河口のマモーラ(Ma'mûre / Mehdiye)港は、1614年にスペイン人に奪われ、サン・ミゲル・デ・ウルトラマールの名で要塞化された。TDVのMevlây İsmâil項は、港がヒジュラ暦1092年(1681年)に急襲でスペイン人の手から奪い返されたと記す——つまりスペインの支配は67年続いた。", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["サアド朝の終わり——モロッコにおけるアラウィー(フィラーリー)朝時代の始まり", "b1afa579"], "d": ["TDV『イスラーム百科事典』はSa’dîler項を「モロッコで統治したイスラーム王朝(1511-1659年)」と定義している。1549年にワッタース朝の支配を終わらせてモロッコ全体を統一し、1578年にワーディー・アル=マハーズィンでポルトガル軍を壊滅させ、いかなる時期もオスマンに従わなかった王朝は、長い王位争いの末に1659年に終わった。その座を、ターフィーラルトから来たアラウィー(フィラーリー)のシャリーフたちが占めた。ムーレイ・ラシードは1666年にフェズ市に入って新王朝を固め、弟のムーレイ・イスマーイールが大西洋岸のヨーロッパの拠点を一掃した。", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["スペインによるアル=フサイマ(アルウセマス)諸島の占領", "954ca998"], "d": ["地中海沿岸のアル=フサイマ諸島は、1673年にスペイン艦隊に占領された。バーディスとセウタとともに、スペインが北モロッコの沿岸に保持し、今日まで手にある拠点の一つである。同年にムーレイ・イスマーイールの兄ムーレイ・ラシードがマラケシュに入って住民から忠誠を受け、フィラーリー朝の支配が南で固まっていた——沿岸でのこの喪失は、内部の統合が対外戦線にはまだ対応していないことを示す。", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["ムーレイ・イスマーイール、アル=アラーイシュをスペインから奪回", "a54bc6ee"], "d": ["TDVのMevlây İsmâil項は明確である:「ヒジュラ暦1100年(1689年)にアラーイシュをスペイン人から取り返して200門の大砲を得、2年後にはアスィーラも取り戻した。」これは、フィラーリー朝のスルタンの沿岸掃討の環の一つである——タンジールは1678年にイギリスから、マモーラは1681年に、アル=アラーイシュは1689年に、アスィーラは1691年に取り戻された。80年前にサアド朝内戦で放棄された港は、こうしてモロッコに戻った。", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["ダルフール・スルタン国の成立——ケイラ朝とSüleyman Solonc", "0fc1c112"], "d": ["TDVによれば、ダルフール・スルタン国の成立は、17世紀末にBumû el-Kasîrが地域に侵入した後に続いた混乱の後にあたる。フール人は、Süleyman Solonc率いるキーラー(ケイラ)家の指導のもと、支配をダージュー人とトゥンジュール人の手から奪い、堅固な統治を築いた。Süleyman Soloncは1695-1715年に統治した。ダルフールのスルタンたちはその後の世紀に、Bâbıâliと文通した。アブデュルメジトとアブデュルアズィズは彼らの統治を承認した。", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["フランスで第一共和政が宣言される——王政の終わり", "d53d49b0"], "d": ["国民公会の最初の会期で王政が廃止され、翌日に第一共和政が宣言された。新しい暦の第1年はこの日から始められた。オスマンにとって相手は変わらなかったが、相手の性格が変わった。セリム3世のニザーム・ジェディードの年に、フランスはもはや王朝ではなく体制であり、1798年にエジプトに上陸することになるのもその体制の軍であった。", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["大カビリアの陥落——ラッラ・ファトマ・ンスメルの捕縛", "0f61ff08"], "d": ["TDVのCezayir項は、山岳のカビリア(Bilâdü'l-kabâil)地方が1853年、1854年、1857年の遠征の末に占領されたことで、フランスのアルジェリア占領の動きが大部分完成したと記す。1857年の遠征はティズィ・ウゾウとアクブーの線を破り、抵抗の象徴ラッラ・ファトマ・ンスメルが捕虜となった。アミール・アブドゥルカーディルが1847年に降伏した後も残っていた最後の大きな抵抗の拠点は、こうして消えた。", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["アイン・サーリフ(ティディケルト)のフランスによる占領", "1e28d1d0"], "d": ["サハラの中央のティディケルトのオアシス群の中心アイン・サーリフは、1899年12月29日にフランス軍に奪われた。これは、アルジェリアの沿岸から南に下るフランスの拡大が砂漠に及んだ最初の大きな一歩である。2年のうちにトゥワートとグーララも同じ道をたどることになる。", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["トゥワート・グーララ・ティディケルトのオアシスのフランスへの併合", "d412838b"], "d": ["アルジェリアの南西にあるトゥワート、グーララ、ティディケルトのオアシス帯は、1901年2月21日に正式にフランスに結ばれた。モロッコのスルタンが名目上の権利を主張したこの隊商路の結節点——アドラール、ティミムーン、レッガーン、ベニ・アッバースを含む——は、こうしてアルジェリアに編入された。モロッコとフランス領アルジェリアの間の国境紛争の始まりはこれである。", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["ベシャール(コロンブ=ベシャール)にフランスの哨所の設置", "4d44d252"], "d": ["モロッコ国境のベシャールのオアシスは、1903年11月11日にフランス軍に奪われ、コロンブ=ベシャールの名で前進哨所とされた。トゥワート帯の併合の2年後にあたるこの一歩は、フランスのアルジェリアからモロッコへの進出の最後の環の一つであり、モロッコが1912年に保護下に置かれる道を開く。", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["モスクワ公国の成立 — ダニール1世", "49549309"], "d": ["アレクサンドル・ネフスキーの末子ダニールは、モスクワを独立した公国として統治し始めた。当時のモスクワは、ウラジーミル・スーズダリの地の小さく取るに足りない中心地にすぎなかった。ロシアの歴史叙述は、この年をのちの台頭の出発点とみなす。", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["カレスィ侯国とハミド侯国の成立", "3905da93"], "d": ["TDVのKaresioğulları項によれば、カレスィ・ベイは、父カレム・ベイの死で解体したセルジューク朝の辺境組織のなかで独立を宣言し、696年(1296-97年)からバルケシルを中心とし、短期間でエルデク、ビガ、エドレミト、ベルガマを含むミシアの全体をビザンツから奪った。同年(1297年)にハミド・ベイは、ウルボルルを政庁の所在地としてハミド侯国を築いた。イスパルタ、ブルドゥル、エイルディル、ヤルヴァチは、解体したセルジュークの辺境地域から侯国の最初の国境に加わった。二つの侯国とも、西アナトリアにおける同じ崩壊——セルジューク朝の中央権力の解体——の産物である。", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["モスクワ公ダニールがコロムナとセルプホフをモスクワに併合", "6d82dccd"], "d": ["ダニールは、リャザン公国からコロムナ(捕虜となったリャザン公が解放されるために城を譲渡した)とセルプホフを奪取した。モスクワはオカ川に達し、モスクワ公国の最初の領土拡大となった。", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["モジャイスクがスモレンスク公国から奪われモスクワに併合", "462055a0"], "d": ["モスクワ公国は、モスクワ川上流域のモジャイスクをスモレンスクから奪い、西の国境をリトアニアに近づけた。", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["ポロツク公国がリトアニア大公国に移る", "04a26a6f"], "d": ["ポロツク、ヴィテプスクとその周辺は1307年までルーシ諸公の家系にとどまった。ゲディミナス以前のリトアニアの東方への拡大は、この移行によって顕著になった(atlasの台帳上の日付は1307年。ヴィテプスクの事実上の移行は1320年ごろとされ、議論がある)。", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["アイドゥン侯国の成立——イズミル、アヤスルク、ティレの奪取", "69a021ae"], "d": ["TDVのAydınoğulları項によれば、ムバーリズッディーン・ガーズィー・メフメト・ベイは、ゲルミヤン朝の辺境ベイSâsâ Beyからこの地方を奪い、1308年にアイドゥン地方で支配権を握った。イズミルのムスリムの区域を、アヤスルク(セルチュク)、ティレ、ボデミヤとともに征服した。アヤスルクを海軍基地とし、奪った土地を5人の息子で分けた——侯国はその後の数十年に、とりわけ息子ウムル・ベイの時代に、エーゲ海の航海における決定的な勢力となることになる。", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["ルーム・セルジューク朝の事実上の終焉——イル・ハン国の直接統治", "00f85ecb"], "d": ["TDVのMesud II項によれば、長い病気の末に708年(1308年)にカイセリで死んだギヤースッディーン・マスウード2世は、通説ではルーム・セルジューク朝の最後の君主である——彼の死の後に即位した候補者は、国内の官職からもイル・ハン国からも承認を得られなかった。地方は、マスウードの治世を通じて既に事実上イル・ハン国の官吏により統治されていた。彼の死により、この直接統治は、コンヤ、ニーデ、アクサライなどの中心地で形式上の覆いをも失った。", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["チャンダル侯国のカスタモヌ-チャンクル-バルトゥン-サフランボルへの拡大", "64e39ad0"], "d": ["TDVのCandaroğulları項によれば、侯国は、イル・ハン国の君主ガイハトゥがエフラニとその周辺をイクターとして与えたシェムセッディーン・ヤマン・チャンダルにより、14世紀の初めにカスタモヌ-シノプの周辺に築かれた。史料の不足のため、創設の正確な日付は知られていない。チャンダルの後継Süleyman Beyは、チョバン朝侯国に取って代わった君主として語られる——つまりカスタモヌとチャンクル周辺はチョバン朝から、バルトゥン-サフランボル-エフラニ線はイル・ハン国の直接統治からチャンダル侯国に移ったのである。", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["ロドスとドデカネス諸島の聖ヨハネ(ホスピタル)騎士団による征服", "67885b4b"], "d": ["TDVのRodos項は、島が1309年に聖ヨハネ騎士団(Hospitalier/İsbitâriyye)の手に渡ったと記す。標準的なホスピタル騎士団史(J. Riley-Smith, The Knights Hospitaller参照)は、包囲が1306年の夏に始まり、ビザンツの増援で長く抵抗したロドス市が、総長フルク・ド・ヴィラレの部隊により1310年8月15日にようやく陥落したと詳述する。島はこの日付から1522年のオスマンの征服まで騎士団の中心となり、周辺のドデカネス諸島も同じ過程でビザンツからホスピタル騎士団の支配に移った。", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["リヴォニア騎士団がリトアニアからドゥーナブルク城を奪回", "92119516"], "d": ["リトアニア人は1281年ごろにイェルシカを奪い、騎士団のドゥーナブルク城と交換していた。城は1313年に再びリヴォニア騎士団の手に渡り、騎士団の騎士団長管区の中心として存続した。", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["コス島(İstanköy)の聖ヨハネ騎士団による奪取", "445666f7"], "d": ["TDVのİstanköy項によれば、聖ヨハネ騎士団はロドスに居を定めた後、コス島も奪って(1315年)新たな要塞を築いた。島はこうして1523年まで続く騎士団の支配に入った。1310年のロドス市の陥落の後、コスがどの統治下にあったかは、TDVでは詳しく述べられていない。", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["府主教座のモスクワへの移転", "d20099f8"], "d": ["ロシア正教会の首長である府主教ピョートルは、宗教上の中心をモスクワに移した。これはモスクワが政治的のみならず宗教的な中心としても台頭する始まりであり、公国の正統性を強めた。", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["リヴォニア騎士団がリガ市の宗主となる", "21453047"], "d": ["リトアニア大公ヴィテニスとゲディミナスの支援を受けて騎士団と戦ったリガ大司教区と市は1330年に敗れ、リヴォニア騎士団が市の宗主となった。1452年のサラスピルス条約により、リガは騎士団と大司教の共同宗主権の下に入った。", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["エレトナ侯国の成立——イル・ハン国以後の中央アナトリア", "a67bacd9"], "d": ["TDVのEretnaoğulları項によれば、ウイグル出身のイル・ハン国の官吏アラーウッディーン・エレトナは、イル・ハン国の君主アブー・サイード・バハードゥル・ハンの1335年の死の後、アナトリアにおけるイル・ハン国の代官職を事実上独立した統治に変えた。まずマムルーク朝スルタンの代理として現れ、1340年にフトバからマムルークの名を外し、1341年ごろ完全な独立を宣言した。中心がまずスィヴァス、次いでカイセリであった侯国は、彼の死(1352年)まで、アマスヤ、トカット、チョルム、ニーデ、アクサライ、エルズィンジャンを含む広い中央アナトリアの支配を築き、1381年にカーディー・ブルハーンッディーンにより終わらされた。", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["ハプスブルク家によるカルニオラとケルンテン(リュブリャナ)の取得", "039918d3"], "d": ["ケルンテン公でありチロル伯であったハインリヒ6世が1335年4月2日にチロル城で嗣子なく没すると、1330年11月23日にバイエルン公ルートヴィヒと秘密裏に結ばれた協定に基づき、ハプスブルク家の兄弟アルブレヒト2世とオットー4世が、ケルンテン公領とそれに属するカルニオラ(現在のリュブリャナを含む地域)を皇帝の封土授与によって得た。一方チロルはハインリヒの娘を通じて別に残った。これはハプスブルク家のアルプス地域における拡大の最初の大きな一歩であり、カルニオラは(中断をはさみつつ)1918年までハプスブルク家/オーストリアの手にとどまることになる。", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["ジャライル朝の成立——イル・ハン国以後のアゼルバイジャン", "a13ada90"], "d": ["TDVのCelâyirliler項によれば、イル・ハン国のアミール・ノヤンの孫ハサン・ブズルグは、イル・ハン国の君主アブー・サイード・バハードゥル・ハンの死とともに勃発した王位争いを利用して、1340年にタブリーズを中心とする独立国家を築いた。ジャライル朝はこうして、アゼルバイジャンとその周辺でイル・ハン国以後の空白を埋めた最初の大きな王朝となった。後継者ウワイス(Üveys)の時代(1356-1374年)に領土はモスルとディヤルバクルまで拡大することになる。", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["ニジニ・ノヴゴロド=スーズダリ大公国の成立 — ハンがコンスタンチン・ヴァシリエヴィチにヤルリクを授与", "c69f5198"], "d": ["ジョチ・ウルスのハン、ウズベク(台帳上の表記はÖzbek/Canibek)は、スーズダリ公コンスタンチン・ヴァシリエヴィチにニジニ・ノヴゴロド=ゴロデツ公国を与えた。公国はモスクワの競争相手となり、1392年にヴァシーリー1世によってモスクワに編入された。", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["デンマークが北エストニア(レヴァルとナルヴァ)をリヴォニア騎士団に売却", "6861ba55"], "d": ["デンマーク王国は北エストニアの領地をレヴァルとナルヴァとともにリヴォニア騎士団に売却した。この地域はリヴォニア戦争まで騎士団の手にとどまった。", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["ボロトヴォ条約 — ノヴゴロドがプスコフの独立を承認", "08eca44d"], "d": ["ノヴゴロドはプスコフを「弟」として承認した。プスコフは独自のヴェーチェとポサードニクを持つ独立した都市共和国として、1510年にモスクワに編入されるまで存続した。", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["ヴァシーリー1世がニジニ・ノヴゴロド=スーズダリ公国をモスクワに併合", "5ecf441b"], "d": ["ヴァシーリー1世は、ハンのトクタミシュから得たヤルリクによって、ニジニ・ノヴゴロド、ゴロデツ、スーズダリをモスクワに結びつけた。モスクワのヴォルガ・オカ流域への進出が始まった。", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["ヴィータウタスがスモレンスクを奪取 — スモレンスク公国がリトアニアに編入", "1a68300c"], "d": ["ヴィータウタスはスモレンスクを奪取した。都市は1514年にモスクワに移るまでリトアニア大公国にとどまった。", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["バグダードのカラ・コユンルの手への移行——ジャライル朝スルタン・アフマドの敗北", "a42ebe92"], "d": ["TDVのKarakoyunlular項によれば、カラ・ユースフは、ヒジュラ暦813年ラビーウ・アーヒル月28日(1410年8月30日)にタブリーズ近郊でジャライル朝のスルタン・アフマドに大敗を与えた。スルタン・アフマドの死の後の814年(1411年)に息子ピール・ブダクをタブリーズでスルタンと宣言し、同年に長男シャー・メフメトがバグダードを征服した。こうして1世紀近くジャライル朝の首都であったバグダードは、周辺のバスラ-モスル-キルクーク線とともにカラ・コユンルの支配に入った。", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["エルズィンジャンとケマがアク・コユンルに移る——カラユリュク・オスマン・ベイ", "122460d4"], "d": ["カラ・ユースフの死の後、エルズィンジャンの住民の求めで、Mutahhartenの孫Yâr Aliが市の総督となっていた。その時代にアク・コユンルのベイ、カラユリュク・オスマンがエルズィンジャンを奪ってアク・コユンルの領土に加えた。この日付以後、エルズィンジャンは、あるときはアク・コユンルとカラ・コユンルの間で、またあるときはアク・コユンルの王子たちの間で手を移る場所となった。", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["カザン・ハン国の成立——ウルグ・ムハンマド・ハンのジョチ・ウルスからの離脱", "335a7408"], "d": ["TDVのKazan Hanlığı項によれば、ジョチ・ウルスの首都サライで王座を失ったウルグ・ムハンマド・ハンは、家族と約3000人の兵とともにまずベレフに退き、1437-1438年にロシアの公ヴァシーリー2世と争い、その後カザン市に居を定めた。地元住民の支持を得てここに新しいハン国の礎を築いた。TDVは、成立の過程が1437-1445年のあいだに完成し、ハン国が1445年から完全に独立の地位を得たと述べている——地図はこの過程の始まりを、ウルグ・ムハンマドがカザンに居を定めた1438年に基準を置いている。", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["クリム・ハン国の成立——ハーッジー・ギレイのジョチ・ウルスからの独立", "5728223e"], "d": ["TDVのKırım項によれば、クリム・ハン国は、14世紀後半のジョチ・ウルスが王位争いで分裂した産物として現れた。ハン国の真の創設者ハーッジー・ギレイが鋳造した最古の貨幣はヒジュラ暦845年(1441-42年)の日付を持ち、これがハン国の公式の成立の日付とされる。同年ハーッジー・ギレイは、モスクワと友好を結ぶことでクリミアでの地位を固め、シリン部族をはじめとする現地のベイの家々が彼の側についた。", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["ジャハーン・シャー、エルズィンジャンを奪取——カラ・コユンルの支配", "0c928cc4"], "d": ["カラ・コユンルの君主ジャハーン・シャーは、854年(1450年)にエルズィンジャンに軍を送り、市をアク・コユンルから奪った。この喪失は、アク・コユンルのベイ、ジャハーンギール・ミールザーと弟ハサン・ベイ(ウズン・ハサン)の仲が裂ける原因となった。", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["カラ・コユンルのジャハーン・シャー、ティムール朝イラン(レイ、イスファハーン、ファールス、ケルマーン)を奪取", "c6fbb3f5"], "d": ["TDVのKarakoyunlular項によれば、カラ・コユンルの君主ジャハーン・シャーは、ティムール朝の王子たちの間の王位争いを利用して、856-857年(1452-1453年)にレイ、イスファハーン、ファールス、ケルマーンの諸州を統治下に置いた。これは、シャールフ・ミールザーの1447年の死の後に始まり、スルターニーヤ-カズヴィーンの併合で開いた拡大の過程の頂点である。ティムール朝の南・中部イランの領土はこうしてカラ・コユンルに移った。ジャハーン・シャーの支配は1466年に、アゼルバイジャン、アッラーン、イラク・アジャミー、イラク・アラビー、ファールス、ケルマーン、東アナトリアを含む広さに達することになる。", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["ボルドーのイギリスによる奪回——ジョン・タルボットの最後のギュイエンヌ遠征", "01b2b7be"], "d": ["1451年にフランス人に失われたボルドーは、住民がフランスの守備隊に対して蜂起して門を開いたことで、年老いた司令官ジョン・タルボット率いるイギリス軍に、1452年10月22日から23日の夜に降伏した。これは、百年戦争においてイギリスがギュイエンヌで得た最後の、そして短命の勝利であった。ボルドーは1年後、カスティヨンの戦いの後に恒久的にフランスに戻ることになる。", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["ボルドーのフランスへの恒久的復帰 — 百年戦争の事実上の終結", "b0a86f6c"], "d": ["1453年7月17日、カスティヨンの戦いでジョン・タルボットが戦死して軍が壊滅すると、ガスコーニュにおけるイングランドの抵抗は崩壊した。包囲されたボルドーは1453年10月19日にフランス軍に降伏した。この降伏は、116年続いた百年戦争が事実上終結した時点とされ(正式な和平条約は一度も結ばれなかった)、イングランドの大陸ヨーロッパにおける支配はカレーまでに縮小した。", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["ウズン・ハサン、エルズィンジャンを奪回——再びアク・コユンルに", "550d010a"], "d": ["ウズン・ハサンはカラ・コユンルを破って、エルズィンジャンを再びアク・コユンルの支配下に置いた。市は1473年のオトゥルクベリの戦いの後もアク・コユンルの国境内に残った。", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["第二次トルン条約——ダンツィヒ(グダンスク)と西プロイセンがポーランドに結ばれる", "e2152dae"], "d": ["プロイセン同盟が1454年にドイツ騎士団(Teutonic Order)の統治に対して蜂起したことで始まった十三年戦争を終わらせた第二次トルン(Toruń)条約は、1466年10月19日に調印された。騎士団は、ダンツィヒ(グダンスク)を含む東ポモージェ、エルビング(エルブロンク)を含むヴィスワ川の河口、およびクルム地方をポーランド王国に譲った——これらの土地は「王領プロイセン」の名を得た。東プロイセンは1525年まで騎士団に残ることになる。", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["イヴァン3世がロストフ公国の残りの半分を買収", "5203244f"], "d": ["ロストフ諸公の手にあった半分がモスクワに譲渡され、1332年にモスクワに移っていたもう半分と合わせて、ロストフの地は完全にモスクワに併合された。", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["トヴェリ大公国がモスクワに併合 — イヴァン3世が都市を奪取", "fa3f924e"], "d": ["モスクワ軍の包囲を受けて、最後のトヴェリ大公ミハイル・ボリソヴィチはリトアニアに逃れ、トヴェリはイヴァン3世に降伏した。こうしてモスクワの最強の競争相手は消滅した。", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["カテリーナ・コルナーロ女王がキプロスをヴェネツィアに譲渡——十字軍国家の終わり", "e24d3f3a"], "d": ["夫のジャック2世王の1473年の死の後、女王摂政としてキプロスを治めていたヴェネツィア出身のカテリーナ・コルナーロは、継承者がいなかったため、ヴェネツィア政府の圧力で1489年2月26日に退位し、島における君主の権利を総督(ドージェ)とヴェネツィア共和国に譲渡した。見返りに女王の称号を保ち、テッラフェルマのアゾロ伯領を得た。この譲渡により、1192年から続いたリュジニャン家の支配と最後の十字軍国家は終わり、島は1570-71年のオスマンの征服までヴェネツィアの統治下に残った。", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["グラナダの陥落——イベリア半島における最後のムスリム国家の終わり", "46e5201b"], "d": ["10年続いた段階的な包囲と内部の分裂で弱体化したグラナダのナスル朝首長国の最後の君主アブー・アブドゥッラー(ボアブディル)は、1491年11月に調印された寛大な降伏条件(グラナダ降伏協定)に従い、1492年1月2日に市の鍵をカトリック両王フェルナンドとイサベルに引き渡した。アルハンブラを去ったボアブディルの後、イベリア半島における最後のムスリム国家は終わり、レコンキスタは完成した。同じ年のうちに、ユダヤ人の追放(3月)とクリストファー・コロンブスの航海(8月)が続くことになる。", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["ヴェドロシャの戦い — モスクワがリトアニア軍を破る、ブリャンスクとセヴェルスクの地はモスクワにとどまる", "d3f61400"], "d": ["1500〜1503年のモスクワ・リトアニア戦争で、ダニール・シチェニャの率いるモスクワ軍は、ドロゴブジュ近郊のヴェドロシャ川でヘトマンのコンスタンティ・オストロスキの軍を破り、ヘトマンを捕虜にした。同年春に奪取されたブリャンスクとセヴェルスクの都市はモスクワの手にとどまり、戦争の終結までにリトアニア領のおよそ3分の1がモスクワに移った。", "e5879803"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["シャイバーニー・ハン、ヘラートとホラーサーンをティムール朝から奪取", "a81d8575"], "d": ["TDVのŞeybânî Han項によれば、ウズベクの君主シャイバーニー・ハンは、1503-1505年にアンディジャン、フェルガナ、ヒサール、クンドゥズ、バルフを奪った後、913年(1507年)にティムール朝の首都ヘラートをも攻略した。『イラン百科事典(Encyclopaedia Iranica)』のホラーサーン項はこの征服の正確な日付を与えている——市はヒジュラ暦913年ムハッラム月8日(1507年5月20日)に陥落し、1週間後のムハッラム月15日(5月27日)にフトバがシャイバーニー・ハンの名で読まれて征服が正式化した。マシュハドを含むホラーサーンの全体が同年のうちにティムール朝からシャイバーニー朝に移った。これは、ティムール朝がマーワラーアンナフルの後にイランにおける最後の大きな拠点をも失ったことを意味した。", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["オランのスペインへの陥落——枢機卿シスネロスの北アフリカ遠征", "86ed8ac1"], "d": ["西地中海の海路を管理し、トレムセンの港であったワフラーン(オラン)は、1492年にグラナダから逃れたアンダルスのムスリムとユダヤ人が避難したことで成長していた。16世紀の初めにマグリブ沿岸の港町を一つずつ奪っていたカスティーリャ王国は、1509年5月17日にワフラーンを占領した。住民の大半が殺され、残りは捕虜となり、市にはムスリムとユダヤ人の住民は残らなかった。スペイン人は城壁と要塞を拡張した。ワフラーンは1708年までスペインの手に残った。", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["スモレンスクがモスクワに降伏 — ヴァシーリー3世が入城", "46c61446"], "d": ["1512〜1522年のモスクワ・リトアニア戦争における3度目の包囲で、リトアニア守備隊は7月31日に降伏した。モスクワ軍は8月1日に儀式をもって入城し、住民はヴァシーリー3世への忠誠を誓った。スモレンスクはヴァシーリーの西方における最大の獲得物である。数週間後にオルシャで喫した敗北も、都市を取り戻させなかった。", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["低地諸国のスペイン王冠への結びつけ——フェルナンドの死、カール5世の即位", "fbe0dbd2"], "d": ["アラゴン王フェルナンド2世が1516年1月23日に死ぬと、1506年からブルゴーニュ公の資格で既に低地諸国(今日のベルギー・オランダ・ルクセンブルクと北フランスの一部)を統治していた孫のカール5世(カルロス)は、カスティーリャとアラゴンの王位の相続人ともなり、1516年3月14日にブリュッセルでスペイン王と宣言された。こうしてこれらの土地は、人的連合を通じて、ハプスブルク家のドイツ/オーストリアの系統ではなく直接スペインの王冠に属するとみなされ始めた——1519年にカール5世が神聖ローマ皇帝に選ばれることで、この二つの身分(スペイン王とドイツ・ローマ皇帝)は同一人物に結合し、地域のスペインへの帰属は、1556年にカール5世が退位して遺産を息子フェリペ2世に残すまで続くことになる。", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["ドゥマク・スルタン国がマジャパヒトを倒し、ジャワ沿岸を支配", "7da602b5"], "d": ["TDVのDemak項によれば、ジャワ最初の独立ムスリム国家であるドゥマク・スルタン国は、15世紀の最後の四半世紀にラデン・パタにより築かれた。ジャワの史料によれば、衰退していたヒンドゥー・仏教のマジャパヒト王国は、ドゥマクの攻撃により消滅した。1527年にドゥマクは、中国の史料が11世紀からマジャパヒトの君主にとって重要な港として挙げるトゥバンを征服した——これは、マジャパヒトの最後の残党もドゥマクに結ばれた年であり、ジャワの大部分のイスラーム化の過程の転換点である。", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["ノルウェーのデンマーク王冠に属する州への格下げ", "8e2f274e"], "d": ["デンマーク王クリスチャン3世は、1536年の戴冠憲章(håndfæstning)で、ノルウェーがもはや別個の王国とはみなされず、デンマークの州として統治されること、ノルウェーの国務会議(riksråd)が廃止されることを宣言した。この決定は、1537年にデンマーク教会規則がノルウェーにも適用されて実効的となり、スコットランド・ノルウェー出身の司教オーラヴ・エンゲルブレクトソンの抵抗が砕かれた。ノルウェーは実際にはなお一時期、自らの法と制度を保ったが、政治的な地位はもはや独立した王国ではなくデンマークの王冠に属する州であった——この状態は1814年まで続くことになる。", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["ナルヴァがロシアに奪取される — リヴォニア戦争で最初の大都市", "c21130d7"], "d": ["イヴァン4世の軍がナルヴァを奪取し、ロシアはバルト海沿岸に達した。ナルヴァは1581年にスウェーデンに移るまでロシアの手にあった。", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["ドルパト(タルトゥ)がロシアに奪取される", "f941a504"], "d": ["ロシア軍は1558年夏の遠征でドルパト(タルトゥ)と周辺の城塞を奪取した。都市は1582年のヤム・ザポルスキ休戦までロシアの統治下にあった。", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["レヴァル(タリン)がスウェーデンの保護下に入る — 北エストニアがスウェーデンに移る", "3c183267"], "d": ["リヴォニア連合が解体するなか、レヴァル市議会は1561年にスウェーデン王エリク14世に忠誠を誓った。北エストニアは大北方戦争(1721年)までスウェーデン領にとどまった。", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["ヴィリニュス条約——リヴォニア連合の解体、クールラントとリヴォニアがポーランド・リトアニアに結ばれる(リガ市を除く)", "d1ceaad5"], "d": ["リヴォニア戦争の間にロシアの圧力のもとで解体したリヴォニア連合の最後の大総長ゴットハルト・ケトラーは、1561年11月28日にヴィリニュスで調印された条約(Pacta Subiectionis)により、リトアニア大公兼ポーランド王ジグムント2世アウグストの庇護下に入った。リガ市を除くリヴォニアの大部分がポーランド・リトアニアに結ばれ、ケトラーはクールラント公国の最初の公となった。これは、リヴォニア騎士団の中世から近世への移行における最後の幕であった。", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["スウェーデンがロシアからナルヴァを奪取", "5a7f7a6a"], "d": ["リヴォニア戦争の最終年にスウェーデン軍は、1558年以来ロシアの手にあったナルヴァを奪取した。都市は1704年までスウェーデン領にとどまった。", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["自由都市リガがポーランド・リトアニアに編入", "77dba329"], "d": ["リヴォニア戦争の間、自由都市であり続けたリガは1581年にポーランド・リトアニア共和国に編入され、1621年にスウェーデンに移るまで共和国にとどまった。", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["廃位布告(Plakkaat van Verlatinghe)——オランダがスペインからの独立を宣言", "a632aaee"], "d": ["八十年戦争が続くなか、ユトレヒト同盟に属するオランダの諸州の全国議会(Staten-Generaal)は、1581年7月26日に採択した廃位布告で、スペイン王フェリペ2世を「暴君」と宣言して彼への忠誠を拒んだ。この文書は、実際に独立した連合州(オランダ共和国)の設立宣言とされる。スペインの最終的な承認は1648年のヴェストファーレンを待つが、実質的な断絶はこの日である。", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["スモレンスクのポーランド・リトアニアへの陥落——20か月の包囲の終わり", "4e9678e3"], "d": ["動乱時代(スムータ)に、ポーランド王ジグムント3世の軍は、1609年9月から包囲していたスモレンスクの城壁に、1611年6月13日に坑道を爆破して突破口を開き、市を奪った。20か月の抵抗は終わった。スモレンスクは1654年までポーランド・リトアニアに残り、この陥落は、7年後に調印されるデウリノ休戦(1618年)の素地を整えた。", "25d6488d"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["ノヴゴロドがスウェーデン軍に占領される — 動乱時代に北西ロシアがスウェーデンの支配下に入る", "a8ab28bb"], "d": ["ヤコブ・デ・ラ・ガルディのスウェーデン軍がノヴゴロドを奪取した。都市は1617年まで、スウェーデンの保護下にある「ノヴゴロド国家」の首都となり、カール・フィリップが皇帝候補とされた。", "281592c2"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["ストルボヴァ条約——ロシアがバルト海沿岸(イングリア)をスウェーデンに失う", "175dc175"], "d": ["イングリア戦争を終結させたストルボヴァ条約は、1617年2月27日にラドガ湖の南のストルボヴァ村で調印された。ロシアはノヴゴロドと北のその他の土地を取り戻す一方、スウェーデンはカレリアとイングリア(エストニア-フィンランド間、イヴァンゴロド-ヤム-コポリエ-オレシェクの要塞を含む)を保持し、ロシアのバルト海への直接の沿岸が断たれた。この断絶は、1703年にピョートル大帝が同じ地方にサンクトペテルブルクを築くまで続くことになる。", "7e70e3e6"]},
"OLAYLAR_EK16:1617-03-09:1":{"b": ["ストルボヴォ条約 — ロシアがイングリアをスウェーデンに割譲、ノヴゴロドは返還", "e0bcbc7a"], "d": ["ロシアはネヴァ川沿岸とカレリアの一部(ヤム、コポリエ、イヴァンゴロド、オレシェク)をスウェーデンに割譲し、バルト海沿岸から切り離された。スウェーデンはノヴゴロドを返還した。この状態はピョートル1世の大北方戦争まで続いた。", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["デウリノ休戦——スモレンスク、チェルニゴフ、ノヴゴロド・セヴェルスキーがポーランドに譲られる", "6880d2c1"], "d": ["1609-1618年のポーランド・ロシア戦争を終わらせたデウリノ休戦は、1618年12月11日に調印され、14年半の停戦をもたらした。ロシアは、スモレンスク(ヴャジマを除く)と、チェルニゴフおよびノヴゴロド・セヴェルスキーの地方の29の都市を、ポーランド・リトアニア連合に譲らざるを得なかった——これは、動乱時代(スムータ)で最も重い領土の喪失であった。地方は1667年のアンドルソヴォ休戦までポーランドに残ることになる。", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["スウェーデンがタルトゥ(ドルパト)をポーランドから奪取 — リヴォニア遠征の第2段階", "46b7c86a"], "d": ["グスタフ2世アドルフは1625年の遠征で南エストニアと北リヴォニアを征服した。タルトゥは、1632年にグスタフ・アドルフ学院が創設されるスウェーデンの都市となった。", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["ペレヤスラフ・ラーダ——ザポロージャ・コサックがロシアのツァーリに忠誠を誓う", "bcd8f8ef"], "d": ["1648年からポーランド・リトアニアに対して蜂起していたザポロージャ・コサックのヘトマン、ボフダン・フメリニツキーは、モスクワからヴァシーリー・ブトゥルリンを長として来た使節団が加わる、1654年1月18日(ユリウス暦1月8日)のペレヤスラフ・ラーダで、ツァーリ・アレクセイ・ミハイロヴィチへの忠誠を誓った。これは、ウクライナ・コサックのヘトマン国のロシアの庇護下への入りの始まりとされ、チェルニゴフ・セヴェルスク地方の実質的な管理をポーランドからロシアへ移した——正式な国境は1667年のアンドルソヴォ休戦で引かれることになる。", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["スモレンスクのロシアによる奪回", "bf0eca92"], "d": ["1654年に始まったポーランド・ロシア戦争の間、ロシア軍は7月から包囲していたスモレンスクを、1654年10月3日にポーランドの守備隊が降伏して奪回した。1611年にポーランドに失われた市は、43年後にロシアに戻った。これは、ロシアが動乱時代の喪失を覆す過程の最も重要な歩みの一つであり、1667年のアンドルソヴォ休戦で恒久的となった。", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["アンドルソヴォ休戦——キエフと左岸ウクライナがロシアに移る", "799be067"], "d": ["1654-1667年のポーランド・ロシア戦争を終結させたアンドルソヴォ休戦は、13年半の停戦をもたらした。ロシアは、スモレンスク、チェルニゴフ・セヴェルスク地方、ドニエプル川左岸のウクライナと、——当初は2年間、実際には恒久的に——キエフ市を得た。この条約は、ウクライナの領土がドニエプル川に沿ってポーランドとロシアの間で分割されること(そしてキエフがロシアに残ること)の法的な基礎を築いた。", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["ロシアがノーテボルク(オレシェク)をスウェーデンから奪取 — 大北方戦争で最初のネヴァ川の要塞", "28d180eb"], "d": ["ピョートル1世の軍はラドガ湖の出口にあるノーテボルク(ロシア語でオレシェク)を包囲して奪取し、名をシュリッセリブルク(「鍵の城」)と改めた。これはネヴァ川へ、そして1703年のサンクトペテルブルク建設へ至る道を開いた。", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["サンクトペテルブルクの創設——ロシアの西に開く窓", "ba196be0"], "d": ["大北方戦争の間にスウェーデンから取り戻したばかりのネヴァ川のデルタにあるウサギ島で、ピョートル大帝は1703年5月16日(グレゴリオ暦27日)にペトロパヴロフスク要塞(ペトロパヴロフスカヤ要塞)の礎を置いた。この日がサンクトペテルブルク市の創設の日とされる。ピョートルは、湿地のデルタを西に開く「窓」として構想し、市は1712年にロシアの新しい首都となった——地方が正式にロシアに結ばれるのは、1721年のニスタット条約によってである。", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["メノルカ島のイングランド・オランダ軍による占領", "3ca66a83"], "d": ["スペイン継承戦争中、オーストリア大公カール6世の同盟者として行動したイングランド・オランダ軍は、ジェームズ・スタンホープ将軍の指揮下で1708年9月14日に島に上陸し、9月28〜29日にスペイン軍の防衛を打ち破ってメノルカ島を掌握した(主要要塞フォート・セント・フィリップの正式な引き渡しは11月24日までかかった)。メノルカの戦略的な港マオンは、その後1世紀にわたりイングランド・フランス・スペインの争奪の焦点となった。", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["ラシュタット条約——スペイン継承戦争が終わり、スペイン領ネーデルラントとミラノがオーストリアに移る", "3c0e086f"], "d": ["スペイン継承戦争をフランスとオーストリアの間で終わらせたラシュタット条約は、1714年3月7日に調印された(ユトレヒト条約は1713年にイギリス・フランス間を整えていた)。条約により、オーストリアのハプスブルク家は、スペイン領ネーデルラント(今日のベルギー)と、イタリアのナポリ、ミラノ、サルデーニャを引き継いだ。これはオーストリアの歴史上最も大きな領土拡大であり、ハプスブルク家の中欧における比重に、西・南ヨーロッパの新たな戦線を加えた。", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["ニスタット条約——大北方戦争が終結し、バルト海沿岸がロシアに移る", "068ffd06"], "d": ["21年続いた大北方戦争を終わらせたニスタット条約は、1721年9月10日(ユリウス暦8月30日)にフィンランドで調印された。スウェーデンはロシアに、エストニア、リヴォニア(リガを含む)、イングリア、南東フィンランド(カレリア)の一部を譲り、その代わりにフィンランドの残りを取り戻し、賠償金が支払われた。条約は、スウェーデンの大国としての地位の終わりと、ヨーロッパの帝国としてのロシアの台頭の正式な確認とされる——ピョートル1世はこの勝利の後「皇帝」の称号を得た。", "f0c4fc4a"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["ポーランド第二次分割——ロシアとプロイセンへの領土喪失", "31750484"], "d": ["1791年の憲法改革がロシアとプロイセンを不安にさせたため、二国は1793年1月23日にサンクトペテルブルクで調印した条約により、ポーランドを再び分割した。ロシアはリトアニア-ベラルーシの大部分と西ウクライナ(カミャネツ、バール、ミンスクを含む)を取り、プロイセンはグダンスクとポズナンを含む大ポーランドを併合した——合計30万7000平方キロ。圧力のもとにあるポーランドのセイムは、同年に条約を承認せざるを得なかった。これは、ポーランドの完全な併合を2年遅らせた短命の分割であった。この日(1793年1月23日)のポーランド第二次分割で、ベルディチェフ、ファストフ、ジトーミル、カニウ、コスチャンティニウ、ウマニ、チェルカースィを含む右岸ウクライナがロシアに移った。", "656e71c2"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["クールラント・ゼムガレン公国がロシアに編入 — 最後の公ペーター・フォン・ビロンが退位", "8d0e410f"], "d": ["第3次ポーランド分割の過程で、クールラントの貴族たちはエカチェリーナに忠誠を誓い、公ペーター・フォン・ビロンは退位した。クールラントはロシアのグベルニヤとなった(史料には1795年10月24日とするものもある)。", "4682774b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["ジェノヴァ共和国の終わり——ナポレオンがリグーリア共和国を樹立", "3d3e59ee"], "d": ["イタリア遠征中のナポレオンの圧力により、1797年6月初めに暫定政府に委ねられたジェノヴァ共和国に代わって、1797年6月14日にフランス型の憲法のもとで「リグーリア共和国」が宣言された。数世紀にわたるジェノヴァ共和国は事実上、フランスの衛星国の一つに変わった。共和国は1805年に直接フランスに併合され、1815年のウィーン会議でサルデーニャ-ピエモンテ王国に譲られることになる。", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["カンポ・フォルミオ条約——ヴェネツィアのオーストリアとフランスのあいだの分割", "9f29678c"], "d": ["ナポレオン・ボナパルトとオーストリア代表コベンツル伯の間で1797年10月17日に調印されたカンポ・フォルミオ条約は、1000年の歴史をもつヴェネツィア共和国を正式に消滅させ、その領土を分割した。アディジェ川の東、イストリアとダルマチアの沿岸(スプリト、ザダル、シベニク、コトルを含む)はオーストリアに譲られ、イオニア諸島(コルフ、ケファロニア、ザキントス、レフカダ、プレヴェザとパルガを含むヴェネツィアのアルバニア-モレア沿岸の基地)はフランスに移った。オーストリアはさらに、低地諸国(今日のベルギー)の領土をフランスに譲った。", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["マルタのイギリスへの降伏——2年に及ぶフランスの包囲の終わり", "fedc2867"], "d": ["1798年のエジプト遠征の途上でナポレオンが奪ったマルタは、まもなく島民の蜂起によりイギリス艦隊の海上封鎖下に入った。2年続いた包囲と飢餓の末、フランスの司令官ヴォボワ将軍は、1800年9月5日にイギリスのピゴット将軍に降伏した。マルタはこうしてフランス共和国からイギリスの庇護下に移り、1814年のパリ条約で正式にイギリス王冠に結ばれることになる——地中海で最も重要なイギリスの海軍基地となった。", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["アミアン条約——メノルカがスペインに返還される", "f341e4b8"], "d": ["フランス、スペイン、オランダ、イギリスの間で調印されたアミアン条約(1802年3月25日)は、第二次対仏大同盟戦争を一時的に終わらせた。イギリスは、戦争中に奪ったほとんどすべての土地(セイロンとトリニダードを除く)を返還した——その一つが1798年にスペインから奪ったメノルカであった。平和は1年しか続かず、1803年5月に戦争が再び勃発したが、メノルカはこの条約の後、二度とイギリスの手に渡らなかった。", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["フレデリクスハムン(ハミナ)条約——スウェーデンのフィンランドのロシアへの割譲", "c0d407bc"], "d": ["1808-1809年の露・スウェーデン戦争を終結させたフレデリクスハムン(今日のハミナ)条約は1809年9月17日に調印され、スウェーデンはオーランド諸島を含むフィンランド全体をロシアに譲った。フィンランドは、ロシア帝国に属する広範な自治を持つ大公国の地位を得て、ルター派の信仰とスウェーデンの法を保った。これは、スウェーデンのバルト海における大国としての地位が事実上終わったことを意味した。この条約により、フィンランドの6つの州とトルネ川までのヴェステルボッテン(コッコラ、ヨエンスー、サヴォンリンナ、トルニオ、ロヴァニエミ、イナリなど)が、ロシアに属するフィンランド大公国に移った。", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["イメレティ王国の併合——ソロモン2世王が廃位", "5ad36bff"], "d": ["1804年にエラズナウリ協定でロシアの臣従を受け入れざるを得なかった西ジョージアのイメレティ王国の最後の王ソロモン2世が、強まるロシアの圧力に抵抗し続けたため、ロシア軍は1810年2月20日に首都クタイシを奪い、ソロモンを廃位し、地元の貴族にツァーリ・アレクサンドル1世への忠誠を誓うよう強いた。イメレティ王国はこうして事実上終わり、直接のロシアの統治に結ばれた。ソロモンはオスマン領に逃れて亡命先で没した(1815年)。", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["キール条約——デンマークのノルウェーのスウェーデンへの割譲", "59ab1601"], "d": ["ナポレオンのライプツィヒでの敗北の後、デンマークに南から攻め込んだスウェーデンは、1814年1月14日に調印されたキール条約によってノルウェー(アイスランド、フェロー諸島、グリーンランドを除く)を譲り受けた——1380年から続いたデンマーク・ノルウェー連合はこうして正式に終わった。見返りにスウェーデンは、ポンメルンの領土をデンマークに譲り、デンマークはさらにヘルゴラント島をイギリスに譲った。ノルウェーは条約に武力で抵抗して独自の憲法を宣言し、スウェーデンはこれを認めざるを得なかった——結果は、1905年まで続く人的連合(real union)となった。スウェーデンはノルウェーを実際に引き継げなかった。条約はノルウェーで受け入れられず、統治はクリスチャン・フレデリクの手にあり、スウェーデン軍がノルウェーに入ったのは1814年7月26日であった。", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["ウィーン会議最終議定書——ナポレオン後のヨーロッパ地図の再編", "fca1c676"], "d": ["ナポレオン戦争を終わらせた大国(オーストリア、ロシア、プロイセン、イギリス、フランス)の間で調印されたウィーン会議最終議定書は、1815年6月9日(ワーテルローの9日前)に採択され、大陸の地図を一括して引き直した。旧スペイン/オーストリア領ネーデルラントと連合州は「ネーデルラント連合王国」のもとに統合され、ジェノヴァ共和国はサルデーニャ-ピエモンテ王国に加えられ、ワルシャワ公国の大部分は「会議ポーランド」の名でロシアに結ばれ、スウェーデン領ポンメルン(シュトラールズント)はプロイセンに移った。この1日は、戦後のヨーロッパの均衡(ヨーロッパ協調)の正式な始まりとされる。この議定書により、ウッチ、チェンストホヴァ、キェルツェ、ラドム、ルブリン、ヘウム、ザモシチ(ワルシャワ公国)はロシアに属するポーランド王国に、ポズナン(ポーゼン大公国)はプロイセンに、マーストリヒトとルールモントはオランダ王国に移った。", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["一般海洋条約——カワーシムとその他の湾岸の首長国がイギリスとの条約に結ばれる", "fc499e19"], "d": ["イギリスは、1819年にラス・アル=ハイマを砲撃して「海賊」のカワーシム艦隊を壊滅させた後、1820年1月8日に始まり、地域の首長国と一つずつ調印されて3月までに完了した一般海洋条約を押しつけた。条約は海賊行為と奴隷制を禁じ、船がイギリス旗に似た赤と白の旗を掲げることを義務づけた。この条約により「海賊海岸」は時を経て「休戦海岸(Trucial Coast)」に変わった。1853年の恒久的な海上休戦と1892年の排他条約で深まったイギリスの覇権は、1971年まで続く関係の始まりであった。", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["ガエータ包囲の終わり——両シチリア王国の崩壊", "121ae580"], "d": ["ガリバルディの1860年5月のシチリア上陸に始まった崩壊の後、ナポリから逃れたブルボン家の王フランチェスコ2世は、最後の要塞ガエータで1860年11月3日から包囲された。フランス艦隊が1861年1月に地域から撤退したことでイタリアの海上封鎖が強まり、1861年2月13日にガエータは降伏した。フランチェスコ2世は王位を放棄して亡命した。両シチリア王国の最後の抵抗地点チヴィテッラ・デル・トロントは、1861年3月20日にようやく陥落することになる。王国の崩壊により、シチリア(パレルモ、メッシーナ、シラクーザ、トラーパニ、ミズィルメーリ)とカンパーニア(ノーラを含む)の土地はもはやブルボン家の統治下になかった。", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["イタリア王国の宣言——サルデーニャ、トスカーナ、南イタリアの統合", "12e52f70"], "d": ["イタリア議会がトリノで開いた最初の会期で、1861年3月17日にイタリア王国が正式に宣言され、サルデーニャ-ピエモンテ王ヴィットーリオ・エマヌエーレ2世が統一イタリアの最初の王となった。新王国は、前年に住民投票で加わったトスカーナ、エミリア-ロマーニャ、ナポリとシチリア(両シチリア)の土地をサルデーニャ王国と統合した。ローマ(教皇領)とヴェネツィア(オーストリア)はまだ外に残っていた——それぞれ1870年と1866年に加わることになる。", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["ジザク(Jizzakh)のロシアへの陥落 — ブハラ・アミール国のシルダリヤ線における最後の要塞", "21205a6e"], "d": ["ロシアの中央アジア進出の過程で、チェルニャエフ将軍による1866年2月の失敗した試みの後、後任のドミトリー・ロマノフスキー将軍の指揮するロシア軍が、1866年10月に7日間の包囲と激しい攻撃によって、ブハラ・アミール国のシルダリヤ流域における最後の大要塞ジザクを奪取した。この陥落は同地域におけるブハラの抵抗を事実上終わらせ、ロシア軍にサマルカンドへの道を開いた。", "b95ba993"]},
"OLAYLAR_EK16:1868-05-14:0":{"b": ["ロシア軍がサマルカンドを占領 — 都市がブハラ・アミール国からトルキスタン総督領に移る", "321473be"], "d": ["ロシア軍はブハラ・アミール国の手にあったサマルカンドを占領し、都市をトルキスタン総督管区に編入した。サマルカンドはウズベクのハンの時代にはブハラの陰に隠れた都市であったが、ロシアの統治下で中央アジアにおけるロシアの進出の新たな拠点となった。", "3bc56bbe"]},
"OLAYLAR_EK16:1870-09-28:0":{"b": ["ストラスブールの降伏: ドイツ軍が都市を占領", "ef3281f3"], "d": ["6週間の包囲と砲撃の後、ユーリック将軍は夜にケーニヒスホーフェンで降伏文書に署名した。朝になって城門と城塞がプロイセン軍とバーデン軍に引き渡された。都市はフランクフルト条約(1871年5月10日)まで軍事占領下にあった。", "38c8361d"]},
"OLAYLAR_EK16:1870-10-29:0":{"b": ["メスの降伏: バゼーヌ軍が武器を置き、ドイツ軍が要塞を接収", "8dd66f58"], "d": ["包囲されたライン軍の降伏議定書は10月27日の夕方に署名された。10月29日の朝にプロイセンの旗が堡塁に掲げられ、フランス軍は要塞を去った。メスはフランクフルト条約(1871年5月10日)まで軍事占領下にあった。", "112e1a60"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["アッサブのイタリア国有化 — イタリア最初の植民地の礎", "15ab8732"], "d": ["紅海沿岸のアッサブ港は、1869年に民間のイタリア海運会社(ルバッティーノ)が現地のアファール人首長から購入していた。イギリスの同意を得て、イタリア政府は1882年3月10日に港を直接の国有とし、7月に制定した法律によってアッサブを正式にイタリア最初の植民地と宣言した。これは、のちにエリトリア植民地(1890年)へと発展するイタリアの紅海沿岸進出の出発点であった。", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["シンカト守備隊の壊滅 — シンカトがマフディー軍の手に落ちる", "e175a94e"], "d": ["数か月にわたりオスマン・ディグナの軍に包囲され、食糧が尽きたシンカト守備隊は、司令官タウフィーク・ベイとともに包囲を突破してスワーキンに達しようとしたが、1884年2月8日に城外で全滅し、シンカトはマフディー軍の手に落ちた。知らせは2月12日にスワーキンに届いた。", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["スワーキンでの戒厳令 — 都市がイギリスの指揮下に入る", "801f6a81"], "d": ["ベイカーのトカール救援部隊が2月4日にエル・テブで敗北した後、ヒューエット提督は2月6日にスワーキンに海兵隊を上陸させた。1884年2月9日に都市に戒厳令が布告され、イギリス人将校に都市に対する軍事・民政の全権が与えられた。翌日、都市の責任は正式にベイカーからヒューエットに移された。", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["トカールのマフディー軍への降伏", "0e21fd24"], "d": ["包囲されたトカール守備隊は1884年2月19日にマフディー軍と交渉に入り、翌日の2月20日に都市を明け渡した。知らせは2月24日にトリンキタトのイギリス軍に届いた。グレアムの救援作戦は間に合わなかった。", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["イギリスの北ソマリ沿岸での保護の確立——ソマリランドの始まり", "f301ea94"], "d": ["TDVのSomali項によれば、ゼイラ、ベルベラ、タージューラは1884年にイギリス人によってソマリランドの名で植民地化された。標準的な学術史料によれば、この過程はベルベラでヒジュラ暦1301年ラマダーン月21日(1884年7月14日)にあたる日にハバル・アワル部族と調印された条約で始まり、1884-1886年にガダブルシ、ハバル・トルジャアラ、ハバル・ゲルハジス、イーサ、ワルサンゲリの諸部族と同様の条約が結ばれて拡大した。イギリスは見返りに軍事的な保護を約束した。この一連の条約は、1887年に正式なイギリス領ソマリランド保護領が宣言される素地を整えた。", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["ムライダーの戦い——第二次サウード国の終わり、ナジュドがラシード家に移る", "1cd3b213"], "d": ["ザカートの紛争とラシード家の使者の逮捕により悪化した関係はついに、ジャバル・シャンマルのアミール、ムハンマド・ブン・ラシードの軍が、1891年1月21日にカスィーム地方のムライダーで、アブドゥッラフマーン・ブン・ファイサル率いるサウード軍とその同盟軍に大敗を与えるに至った。これは第二次サウード国の事実上の終わりとなり、アール・サウード家はクウェートに亡命し、ナジュドの全体がラシード家の支配に入った。南のディラム(ハルジュ)、ハウタ(ハウタト・バニー・タミーム)、ライラー(アフラージュ)の地域もその内にあった。支配は、1902年に若きアブドゥルアズィーズ・ブン・サウードがリヤドを取り戻すまで(リヤド急襲、1902年1月16日)続くことになる。", "b77d8161"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["英・エジプト軍によるトカールの奪回 — オスマン・ディグナの撤退", "80a2c26a"], "d": ["1884年以来マフディー運動の現地司令官オスマン・ディグナの手にあった紅海沿岸のトカールは、1891年2月に英・エジプト軍の作戦によって奪回され、オスマン・ディグナは山中への撤退を余儀なくされた。これはマフディー国家の紅海沿岸における存在にとって大きな打撃となり、地域は英・エジプト共同統治下に入った。", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["グレンフェル縦隊のシンカト通過 — シンカトがマフディー支配を脱して英・エジプト統治に復帰", "b7539a44"], "d": ["1891年2月のトカール奪回の後、グレンフェルが率いる英・エジプト縦隊は1891年3月3日にアファーフィートからシンカトを経由して出発し、3月7日にスワーキンに到達した。縦隊は、1884年以来一度も立ち入れなかった地域に敵がまったくいないことを確認した。3月8日にスワーキンに集まったシェイフたちに対し、副王の名で一般恩赦が布告され、シンカトは再び英・エジプト統治下に置かれた。", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["イタリア領ソマリランドの国家の直接統治への移行——ベナディール会社の清算", "8c7d085b"], "d": ["TDVのSomali項によれば、イタリアは、南ソマリの沿岸(ベナーディル)における支配を1889-1891年にザンジバル・スルタン国とイギリスとの協定で築き、統治を当初は特許を持つ貿易会社(ベナディール会社)に委ねていた。標準的な学術史料によれば、この会社の特許は1905年1月24日に終わり、イタリア国家はベナーディル沿岸(モガディシュ、メルカ、バラウェを含む)の直接の主権を買い取って正式な植民地統治を築いた。植民地の内陸(バルデーラ、バイドア)に向けた実際の拡大は、1908年の設置勅令とその後の年に完成することになる。", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["ノルウェー・スウェーデン連合の解消——ストーティングの一方的独立宣言", "aaba2935"], "d": ["ノルウェー政府の別個の領事館設置の要求を国王オスカル2世が拒否し、新しい政府を組織できないと表明したことを受け、ノルウェーのストーティング(議会)は1905年6月7日に満場一致で、国王がもはや実際にノルウェー王として職務を果たしていないこと、1814年のキール条約以来続いた連合が解消されたことを決めた。1905年8月13日の国民投票で、有権者のほぼ全員(37万1000票対184票)が解消を承認した。スウェーデンは、カールスタード交渉の後、1905年10月26日に独立を正式に承認した。", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["リバウ(リエパーヤ)がドイツ軍に占領される — クールラント占領の始まり", "fdb10548"], "d": ["ドイツ軍は1915年夏の攻勢でクールラントに入った。リバウはバルト海沿岸のロシア海軍基地であった。クールラントの大部分はオーバー・オスト司令部の下に入った(1918年末まで)。", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["ミタウ(イェルガヴァ)がドイツ軍に占領される", "eb491281"], "d": ["クールラントの旧公国の首都ミタウはドイツの支配下に入った。リガ前線はダウガヴァ線で凍結し、1917年まで動かなかった。", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["コヴノ(カウナス)要塞がドイツ軍に奪取される — リトアニアが占領下に入る", "9849405b"], "d": ["ドイツ第10軍は、ロシアのネマン川における最大の要塞を奪取した。リトアニア地方はオーバー・オスト統治下に入り、1918年にタリバはこの占領下で独立を宣言した。", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["ヴィルナ(ヴィリニュス)がドイツ軍に占領される", "2781858b"], "d": ["大撤退の際にヴィルナはドイツ軍の手に渡り、オーバー・オストのリトアニア地方に組み込まれた。都市は1919年までドイツ軍、ソ連軍、ポーランド軍の間で何度も支配者が替わった。", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["英・カタール条約 — カタールがイギリスの保護下に入る", "f61c4e49"], "d": ["第一次世界大戦のさなか、ペルシア湾のイギリス政治代理官パーシー・コックス少佐とカタールのシェイク、アブドゥッラー・ビン・カースィム・アール・サーニーとの間で1916年11月3日に調印された条約により、カタールは外交関係をイギリスの承認の下に置くことを受け入れ、その見返りに海上からの攻撃に対するイギリスの保護を保証された。この条約は1971年まで続くカタールとイギリスの保護関係の法的基礎となり、1918年に正式に批准された。", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["リガがドイツ第8軍に占領される", "df95df19"], "d": ["ドイツ軍はダウガヴァ川を渡ってリガを奪取した。都市は1918年11月までドイツの支配下にあり、ラトヴィアの独立はこの占領下で宣言された(1918年11月18日)。", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["ラトヴィア人民評議会が独立を宣言", "fc72a7f7"], "d": ["リガの国民劇場に集まったラトヴィア人民評議会は、ロシア帝国から独立したラトヴィア共和国を宣言し、カールリス・ウルマニスを首班とする臨時政府が樹立された。数週間後(1918年12月)にソヴィエト・ロシアが攻撃を開始し、独立戦争が始まった。この宣言により、リガ、イェルガヴァ、リエパーヤ、ヴェンツピルス、ツェーシス、ダウガフピルス、レーゼクネはラトヴィア共和国の領土とみなされた。", "615adeb0"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["赤軍がヴィリニュスに入る — リトアニア政府が都市を放棄", "889a97b3"], "d": ["リトアニア政府は赤軍が接近するなかでヴィリニュスを放棄した。ソヴィエト軍が都市に入り、1919年2月にここからリトアニア・ベラルーシ・ソヴィエト共和国(リトベル)が宣言された。都市は1919年4月にポーランド軍に奪取されることになる。", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["ポーランド軍がヴィリニュス(ヴィルノ)をソヴィエトから奪取", "32d36c4a"], "d": ["ユゼフ・ピウスツキの部隊が1919年4月にヴィルノを赤軍から奪取した。リトアニアは都市の領有を主張し続け、ヴィリニュス問題は戦間期のリトアニア・ポーランド関係を損なった。", "85e7c434"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["イギリスがエジプトに対する保護を解除しエジプトの独立を宣言", "f8faab66"], "d": ["イギリスは1922年2月28日の宣言により、1914年以来続いた保護を一方的に終わらせ、エジプトを独立国と宣言した。防衛、交通路、スーダンなどの問題はイギリスに留保された。宣言の2週間後(1922年3月15日)にスルタン・アフメド・フアードは国王の称号を得た。地図上では、エジプトの諸都市におけるイギリス占領の層はこの日に終わる。", "8cde4005"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["リトアニアがドイツの最後通牒を受諾 — メーメル地方がドイツに割譲", "149fb0b2"], "d": ["リッベントロップの最後通牒により、リトアニアはクライペダ(メーメル)地方をドイツに引き渡した。ヒトラーは3月23日にメーメルに入った。地方は1945年1月28日に赤軍によって奪取された。", "75afd979"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["ドイツがグロドノを占領", "b7ca9378"], "d": ["東部戦線: 1941年のバルバロッサ作戦と1944年のバグラチオン作戦。", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["ドイツがブレスト・リトフスクを占領", "25898c65"], "d": ["東部戦線: 1941年のバルバロッサ作戦と1944年のバグラチオン作戦。", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["プスコフがドイツ軍に占領される — ロシア領の占領が始まる", "d9822e30"], "d": ["バルバロッサ作戦の3週目に、ドイツ国防軍がプスコフに入った。都市は1944年7月23日までドイツ軍政下にあった。出典: プスコフ市年表、memorialmuseums.org「Memorials in Pskov」— 検索要約 [要約]。", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["ヴィテプスクがドイツ軍に占領される", "e1e4d7d0"], "d": ["中央軍集団は、バルバロッサ作戦の最初の数週間にヴィテプスクを占領した。都市は1944年6月までドイツ軍政下にあり、人口の大部分が失われた。", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["スモレンスクがドイツ軍に占領される", "5a7f4e2a"], "d": ["中央軍集団がスモレンスクを占領した。モスクワへの道上にあるこの都市は、1943年9月25日まで26か月間占領下にあり、大きな破壊を被った。", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["モギリョフがドイツ軍に占領される", "4362b7a1"], "d": ["モギリョフは23日間続いた防衛の後、ドイツ国防軍の手に落ちた。都市は1944年6月28日まで占領下にあった。", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["オストラント国家弁務官区の設置 — バルト諸国とベラルーシがドイツ民政下に入る", "052d4c08"], "d": ["1941年7月17日のヒトラーの決定により、東方の占領地は民政に移管された。ヒンリヒ・ローゼを長とするオストラントは、エストニア、ラトヴィア、リトアニア、ベラルーシを含んだ(中心地はリガ)。エストニアの民政は1941年12月5日に始まり、ベラルーシの東部は軍政下にとどまった。", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["ナルヴァがドイツ・エストニア軍に占領される", "60fc2b6a"], "d": ["夏戦争でエストニア人義勇兵とドイツ国防軍がナルヴァを占領した。都市はオストラントに編入され、1944年7月26日までドイツの統治下にあった。", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["ノヴゴロドがドイツ軍に占領される", "4f599b62"], "d": ["北方軍集団がノヴゴロドを占領した。ロシア最古の都市のひとつは1944年1月まで占領下にあり、大部分が破壊された。", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["ゴメリがドイツ軍に占領される", "9d78eb92"], "d": ["ドイツ国防軍のゴメリ攻撃から3日後、赤軍は都市から完全に撤退した。都市は1943年11月26日まで占領下にあった。", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["タリンがドイツ第18軍に占領される", "a855ad0d"], "d": ["ソ連バルト艦隊のクロンシュタットへの血みどろの撤退によってタリンは陥落した。エストニアはオストラントのなかでエストラント総区となった(1941年12月5日に民政)。", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["オリョールがドイツ軍に占領される", "3127f454"], "d": ["ブリャンスク・ヴャジマ作戦でドイツ第2装甲軍がオリョールを占領した。都市は1943年8月5日まで占領下にあった。", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["ブリャンスクがドイツ軍に占領される", "20fa93f8"], "d": ["ブリャンスクの戦いの終結時にドイツ軍が都市に入った。都市は1943年9月17日まで占領下にあった。", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["クルスクがドイツ軍に占領される", "a723a00a"], "d": ["ソ連の指揮部の命令でクルスクは放棄され、ドイツ第2軍が都市に入った。都市は1943年2月8日まで占領下にあった。", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["クルスクが赤軍により解放される", "1ac03fba"], "d": ["ソ連の冬季攻勢(ヴォロネジ・カストルノエ作戦に続くクルスク・ハリコフ方面)の末にクルスクは奪回された。同年7月に、都市の名はクルスクの戦いに冠されることになる。", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["オリョールが赤軍により奪回される — クルスク後の最初のソ連の礼砲", "80bfc68d"], "d": ["オリョール突出部の奪取と、ベルゴロドとともにモスクワで最初の礼砲が撃たれたこと。", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["ブリャンスクが赤軍により奪回される", "d0f2a35f"], "d": ["ブリャンスク攻勢により、都市は1943年9月17日に奪回された。", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["スモレンスクが赤軍により解放される", "6516d85a"], "d": ["1943年8月7日〜10月2日のスモレンスク攻勢の頂点で都市は奪回された。スモレンスクは1985年に「英雄都市」の称号を得た。", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["ゴメリが赤軍により解放される", "280268c2"], "d": ["ベロルシア方面軍はゴメリ・レチツァ攻勢で都市を奪回した。ベラルーシで最初の大都市解放のひとつである。", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["ノヴゴロドが赤軍により解放される", "52962012"], "d": ["レニングラード・ノヴゴロド攻勢の際、ヴェリーキー・ノヴゴロドは1944年1月20日に奪回された。", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["ヴィテプスクが赤軍により解放される — バグラチオン作戦", "b06be69c"], "d": ["第1バルト方面軍と第3ベロルシア方面軍がヴィテプスクを包囲して奪取した。バグラチオン作戦で最初の大都市解放であった。", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["モギリョフが赤軍により解放される — バグラチオン作戦", "52fa985d"], "d": ["第2ベロルシア方面軍はモギリョフを奪取し、ドニエプル線を突破した。", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["赤軍がミンスクを奪回 — バグラチオン作戦", "87dc1fb5"], "d": ["6月22日に始まったバグラチオン作戦で、ベロルシア諸方面軍は中央軍集団を突破してミンスクを包囲し、都市は7月3日に奪回された。東方では5万に近いドイツ兵が包囲下に取り残された。ベラルーシのドイツ民政(ヴァイスルテニエン総区)は崩壊した。", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["赤軍がヴィリニュスを奪取", "0172450e"], "d": ["7月5〜13日のヴィリニュス攻勢で、第3ベロルシア方面軍はドイツ守備隊を包囲して都市を奪取した(ポーランド国内軍の「オストラ・ブラマ」作戦は同時に行われた)。ヴィリニュスはリトアニア・ソヴィエト社会主義共和国の首都となった。", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["赤軍がグロドノをドイツの占領から解放", "1d134151"], "d": ["東部戦線: 1941年のバルバロッサ作戦と1944年のバグラチオン作戦。", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["プスコフが赤軍により奪回される", "f18103aa"], "d": ["3年を超えるドイツの占領の後、プスコフは赤軍によって奪回された。", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["赤軍がナルヴァを奪取", "64854ae3"], "d": ["1944年2月から前線で荒廃していたナルヴァは、1944年7月のナルヴァ攻勢でソ連軍に奪取され、エストニア北東部はドイツ民政(エストラント総区)の支配から脱した。", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["レーゼクネが赤軍に奪取される — ラトヴィア東部が解放", "e9efd12d"], "d": ["第2バルト方面軍がレーゼクネを奪取し、ラトヴィアのラトガレ地方はドイツの統治を脱した。", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["ダウガフピルスが赤軍により解放される", "b4ee6622"], "d": ["第2バルト方面軍の第360狙撃師団がダウガフピルス(ドゥーナブルク)を奪取し、ラトガレ第2の大都市はドイツの統治を脱した。", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["シャウレイが赤軍に奪取される — シャウレイ攻勢", "ccb20729"], "d": ["第1バルト方面軍はリトアニア北部の鉄道の要衝シャウレイを奪取した。攻勢は1944年7月5日〜8月29日に及び、リガ湾に達した。", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["赤軍がブレスト・リトフスクをドイツの占領から解放", "6d5a837a"], "d": ["東部戦線: 1941年のバルバロッサ作戦と1944年のバグラチオン作戦。", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["カウナスが赤軍に奪取される — リトアニアの臨時首都がドイツの統治を脱する", "5c2b2c16"], "d": ["第3ベロルシア方面軍がカウナスを奪取し、スターリンの8月1日の日々命令が奪取を告げた。都市は1919〜1939年のリトアニアの臨時首都であった。", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["タルトゥが赤軍に奪取される — タルトゥ攻勢", "cc8069ab"], "d": ["第3バルト方面軍がドイツ第18軍の防衛を破ってタルトゥを奪取した。都市は数週間にわたり前線にあり、タルトゥ攻勢は1944年9月6日に終わった。", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["赤軍がタリンに入る — ドイツ軍が都市を放棄", "41ae1ec5"], "d": ["タリン攻勢の際、ドイツ軍は都市を放棄した。9月18日に政府庁舎を掌握したエストニア国民委員会政府は、赤軍の入城に際して統治を維持できなかった。エストニアは再びソヴィエト統治下に入った。", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["赤軍がメーメル(クライペダ)を奪取", "d01ad3dc"], "d": ["東プロイセンとバルト海沿岸に向かうソ連の作戦で、メーメル(クライペダ)港はドイツから奪われ、リトアニア・ソヴィエト社会主義共和国に編入された。1939年にドイツに割譲されていた地域は、こうしてドイツの統治を脱した。", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["クールラント・ポケットの降伏 — クールラント軍集団がゴヴォロフに降伏文書に署名", "3c88889b"], "d": ["1944年10月からリエパーヤ・ヴェンツピルス周辺に包囲されていたドイツのクールラント軍集団が降伏し、ラトヴィア西部はソ連の支配下に入った。", "a7bfcc52"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["オマーンのスルタンの軍が内オマーンの主要な中心地に入る — イバード派イマーム制が事実上終焉", "9a9962a5"], "d": ["1955年12月、オマーンのスルタンは権威を回復するために行動を起こし、その軍は内オマーンの主要な居住中心地(バフラー、イズキー、ニズワー)に入った。イバード派イマーム制による内オマーンの統治は事実上終わった。出典は月のみを示すが、地図では1955年12月1日と表示される。", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["クウェートがイギリスの保護を脱し完全な独立を獲得", "e9a86d04"], "d": ["クウェートとイギリスの間で1961年6月19日に交換された書簡により、1899年の協定以来続いたイギリスの保護は終わり、クウェートは完全に独立した。地図上では、クウェートにおけるイギリスの層はこの日に終わる。", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["カタールがイギリスとの条約の終了にともない独立を宣言", "8f288cc6"], "d": ["大ブリテンとの保護条約が終了した日の後、カタールは1971年9月3日に独立を宣言した。地図上では、ドーハにおけるイギリスの層はこの日に終わる。", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["ストランジャの城塞: Pınarhisar、Kırkkilise(Kırklareli)、Vizeの征服", "c6b1a9c1"], "d": ["1369年の冬をエディルネ宮殿で過ごしたムラト1世は、春にビザンツに対して再び行動を起こし、ストランジャ山地の麓にあるPınarhisar、Kırkkilise、Vizeの城を奪取した。これらの征服はコンスタンティノープルに恐慌を引き起こし、皇帝ヨハネス5世は助けを求めて教皇のもとへ行くことを決めた。", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["タシュケントがモグーリスタンのハン、ユーヌス・ハンの統治に移る", "a37ee010"], "d": ["ティムール朝の王子たちの間の王位争いのさなか、タシュケントとその周辺は東チャガタイ(モグーリスタン)のハン、ユーヌス・ハンの手に渡った。2年後にユーヌス・ハンが死ぬと、息子のマフムード・ハンが後を継いだ。都市は、1503年にシャイバーニー・ハンのウズベクが奪うまでモグールのハンのもとにあった。", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["バーブルがフェルガナをウズベクに譲ってカーブルへ向かう", "69df593c"], "d": ["ウマル・シャイフ・ミールザーの息子でティムール朝のバーブルは、1494年から統治していたフェルガナを、ムハンマド・シャイバーニー・ハンとの戦いの後にウズベクに譲り、ヒンドゥークシュを越えてカーブルに定着した。", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["ピーリー・レイス、現存する最古の世界地図を作成", "6ef941f5"], "d": ["ピーリー・レイスは、ゲリボルで919年(1513年)の日付を持つ世界地図を描いた。TDV イスラーム百科事典によれば、地図の資料のなかには「東西の世界から彼に届いた古い地図とクリストファー・コロンブスの地図」も含まれる。すなわち、当時失われたと考えられていたコロンブスの原航海図の痕跡をとどめていると考えられている。彼は地図を923年(1517年)にカイロでヤヴズ・スルタン・セリムに献上した。現存するのは西側・大西洋沿岸(スペイン、ポルトガル、西アフリカ、南アメリカの東海岸)のみを示す断片だけで、この断片は1929年にトプカプ宮殿で再発見され、ユネスコの世界の記憶に登録されている。", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["カルス周辺の統合: Şüregel、Arpaçay、Digorのオスマン統治への編入", "10f16b5c"], "d": ["二つのイラク遠征のあいだに、Pasin、Şüregel、Oltuの城がオスマンの手に入った。カルス城もこのときに併合された可能性が極めて高い。カルスの北と東にあるArpaçayとDigorの地方は、同じ作戦でオスマンの統制下に入った。", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["シルヴァンシャー朝の終焉: Elkas Mirzaがシャーフルフを捕らえ、シルヴァンはサファヴィー朝の州となる", "e6d64114"], "d": ["シャー・タフマースプが送ったElkas Mirzaはシルヴァンを略奪してBaykurd要塞を攻略し、15歳のシルヴァンシャー、シャーフルフを捕らえてタブリーズに連れ去った。地域で長く支配を維持したシルヴァンシャー朝の統治はこうして終わり、シルヴァンはサファヴィー朝の一州となった。", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["アルジェ軍団領のサハラへの拡大 — トゥッグルト・ワルグラの貢納化、トレムセンの最終的征服", "705ec920"], "d": ["TDV のトレムセン項によれば、960年(1553年)にアルジェから派遣された大軍が、Salih Reisの指揮下で都市を最終的に奪取し、3世紀にわたるザイヤーン朝に終止符を打った。同じ時期(1552年)にSalih Reisは、独立のスルタン国であるトゥッグルトとワルグラに遠征を行った。オスマン軍はトゥッグルトを奪い、ワルグラに進み、二つのスルタン国は貢納を課された。途上のビスクラには恒久的なオスマン守備隊が残された。こうしてアルジェ軍団領の境界は初めてテル・アトラスを越え、サハラの縁に達した。一方、ムスタガーネム前面での大会戦は、この年ではなく1558年に起こった。Hasan Paşaはそこでスペインのアルカウデテ伯を破り、北アフリカにおけるスペインの攻勢を終わらせた。", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["ハベシュ州の設立 — 紅海沿岸のオスマン統治への編入", "7dd470ec"], "d": ["ポルトガルがエチオピアを経由して紅海に浸透することを防ぐために設けられたこの州は、TDV のハベシュ州項によれば、962年シャァバーン月15日(1555年7月5日)に正式に設立され、サンジャクの中心はスワーキンとなった。Özdemir Paşaは1555年の秋に作戦を開始し、マッサワ港を制するデフレク諸島を奪い、1557年4月2日にマッサワ市を、次いでアルキーコを奪った。征服は、ティグレ州が1558年に、デバルワが1559年にオスマンの支配下に入ることで続いた。", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["セデフカール・メフメト・アアが主席建築家に任命 — スルタンアフメト・モスクの建築家", "27b66fce"], "d": ["アルバニアのイルバサン出身で、デヴシルメとして1562〜63年ごろに宮廷に入ったメフメト・アアは、建築家スィナンのもとで育ち、1606年10月11日にオスマンの主席建築家に任命された。TDV イスラーム百科事典は、同時代の資料が彼を「穏やかな気性で、謙虚で、約束を守り、敬虔で聡明」と評していることを伝える。3年後にアフメト1世の命でスルタンアフメト・モスクの建設に着手することになるメフメト・アアは、カアバの修復からイスタンブルとエディルネの多数の泉亭やモスクに至る幅広い作品を残した。6本のミナレットがメッカのカアバとの「同等」の議論を招いたというのは広く知られた民間の語りであるが、百科事典的な資料はこれを裏づけず、この配置を「それまで試みられなかった」ものと述べるにとどまる。", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["新スルタン・ムスタファ1世: 青白い顔、ぼんやりした眼差しの「カフェス」の囚人が即位", "c487b0d1"], "d": ["アフメト1世の死去により即位したムスタファ1世は、兄が生かしておいた最初の皇子として、長年にわたり厳重な監視のもと宮殿に幽閉されて暮らしていた。TDV イスラーム百科事典は彼を「青白い顔で、まばらな髭、大きな黒い目の虚ろな眼差し」と描写し、この長い幽閉が彼の精神状態を悪化させたと記す。96日続いたこの最初の治世において、彼は国政を執ることができなかった。その一方で、しばしば狩りに出かけ、造船所を見て回り、水に金貨を投げて魚を眺めたとも伝えられる。常備軍のイェニチェリとウラマーは、彼が君主にふさわしくないとみなして1618年2月26日に退位させ、代わって14歳の甥オスマン2世を即位させた。", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["エヴリヤ・チェレビの旅の夢 — 「シェファアト」と言うところを「セヤハト」と言った", "2d863e22"], "d": ["TDV イスラーム百科事典によれば、エヴリヤ・チェレビは、40年続くことになる旅の生活の始まりを、1040年ムハッラム月のアーシューラーの夜(1630年8月19日)に見た夢に結びつけている。夢のなかで彼はイスタンブルのアヒ・チェレビ・モスクで大勢の会衆とともに預言者ムハンマドを見て、興奮のあまり「シェファアト・ヤー・ラスールッラー」と言うべきところを「セヤハト・ヤー・ラスールッラー」と言った。伝承によれば、預言者はこの言い間違いに微笑み、彼にシェファアトも、旅も、巡礼も与えられるという吉報を告げた。彼は生涯結婚せず、この「旅」の約束に生涯を捧げた。", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["ムラト4世の矛盾: 酒に溺れた君主の禁酒令、力士の腕、作曲家の耳", "3d2ea5e0"], "d": ["11歳で即位したムラト4世の初期には、母キョセム・スルタンの影響力が決定的であった。TDV イスラーム百科事典は、キョセムが息子の権力志向を恐れて彼を「娯楽に向かわせ、贈り物や祭りで気を紛らわせた」と伝える。約20歳で政務を実際に掌握したとき、彼は背が高く、肩幅が広く、威風堂々たる君主であった。力の強い男を帯をつかんで持ち上げ、ハス・オダを何度か歩き回ったと伝えられる。TDV が記す際立った矛盾は次のとおりである。タバコとアヘンを嫌ったと言われる君主は酒に極端に溺れていたが、それにもかかわらず出征前にコーヒー、タバコ、のちには酒そのものをも禁じた。同時に、作曲ができるほど音楽の知識を持っていた。", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["ラーガーリー・ハサン・チェレビのロケットによる飛行 — エヴリヤ・チェレビのみを典拠とする伝承", "1f02e3f2"], "d": ["エヴリヤ・チェレビの『旅行記』によれば、ラーガーリー・ハサン・チェレビは、ムラト4世の御前でサライブルヌにおいて、50オッカの火薬を用いた7本の筒の花火仕掛けを作り、「我が君よ、あなたを神に託します、預言者イエスと語らいに行きます」と言って花火に乗り込んだ。伝承によれば、約250メートル上昇したハサン・チェレビは、鷹の翼に似た道具で海に滑空し、泳いでスルタンのもとに戻り、その褒美として日給70アクチェのスィパーヒーの身分を得た。", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["弓の名手Kara Mustafa Paşaが大宰相となる — 財政改革の時代が始まる", "583846a4"], "d": ["バグダード遠征でTayyar Mehmed Paşaが殉教した後、1048年シャァバーン月17日(1638年12月24日)に大宰相となった弓の名手Kara Mustafa Paşaは、スルタン・イブラヒムの治世において厳しい財政規律を課した。イェニチェリとスィパーヒーの員数を3分の1に削減し、貨幣の品位を正し、公定価格の制度を引き締めた。TDV が挙げる数字では、この節約は年に6000袋に達した。しかしこの厳しい統制は、彼に宮廷周辺での敵を作った。", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["ムスタファ1世が15年間の忘却の後に死去", "b4c872cd"], "d": ["1623年9月10日に2度目の退位をさせられたムスタファ1世は、死に至るまでの15年間、閉じ込められた一室で暮らした。この年月については資料にまったく情報がない。1048年ラマダーン月15日(1639年1月20日)に没した。資料の一部はこれを自然死とし、一部はムラト4世の関与があったと主張する。", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["「狂人イブラヒム」か、波のある病か?", "2abc230f"], "d": ["TDV イスラーム百科事典は、20世紀に広まった「狂人イブラヒム」という呼び名をはっきりと退ける。スルタン自身の書簡のなかで、彼が痛み、食欲不振、脚の脱力、頭の霧のような感覚、胸の圧迫感、失神の発作を訴えていることを伝える。これに対し、廃位の過程における彼の一貫した理にかなった受け答えは、継続的な不安定さの主張と矛盾する。百科事典は、その状態が「一定ではなく、重さが変化する」経過をたどったと結論づける。この時期、キョセム・スルタンの責務は次第に増し、宮廷に呼ばれたCinci Hocaが「効験ある祈り」によってスルタンに精神的な慰めを与えたことで、彼の政治への干渉力は大きくなった。", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["黒貂事件 — 大宰相Ahmed Paşaの毛皮税がイブラヒムの最期を準備した", "a2a47d62"], "d": ["スルタン・イブラヒムの黒貂の毛皮と龍涎香への執着が宮廷で次第に膨らむなか、大宰相Ahmed Paşaは1647〜1648年ごろ、国家の高官たちから黒貂の毛皮の代金を強制的に徴収する慣行を始めた。TDV イスラーム百科事典は、役人たちがこれを明白な「貢納」とみなしていたことを記す。イェニチェリの将校たちが支払いを一斉に拒否すると、この抵抗はスルタンの廃位に至る過程の直接の引き金となった。1648年8月7日の朝に集まった役人たちは、まずAhmed Paşaを殺害し、翌日イブラヒムを廃位した。", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["「国家は女たちが治めている」 — Varvar Ali Paşaのスィヴァスからの反乱", "5b027357"], "d": ["スィヴァスのベイレルベイであったVarvar Ali Paşaは、イスタンブルが「バイラミエ」の名で求めた3万クルシュを、「スィヴァスの年収はこの額に及ばない」と言って支払いを拒否した。TDV イスラーム百科事典によれば、彼の反乱の理由は、スルタンの病のために国政が女たちの手に渡り、それが頻繁な総督の交代による不安定を生んでいるという主張であった。1648年5月にはまず軍事上の成功を収めたものの、İpşir Mustafa Paşaに敗れ、1648年5月20日に処刑され、首はイスタンブルに送られた。", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["アナボル(ナフプリオン)のヴェネツィアへの喪失 — モレア戦争の転換点", "9d400557"], "d": ["TDV のアナボル項によれば、包囲の間に都市のムスリム住民の生存者は近隣の島々とアナトリアに逃れた(1686年)。標準的な学術文献(セットン『17世紀のヴェネツィア、オーストリア、トルコ』)によれば、ケーニヒスマルクの軍は2週間にわたりオスマン救援軍の攻撃を撃退した。8月29日のİsmail Paşaの攻撃が大敗に終わると、要塞は数日のうちに降伏した。アナボルは1540年に条約で引き継がれたオスマンの領土であり、その喪失によってモレア半島のヴェネツィアへの移行は加速した。", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["メフメト4世が狩りをやめる — 廃位前夜の最後のあがき", "7daa904b"], "d": ["モハーチの敗北(1687年8月)の後、俸給を支払われなかった軍隊は反乱を起こしてイスタンブルへ進軍した。メフメト4世は、宰相の印を逃れたSüleyman Paşaを殺させてその首を兵に示し、狩猟道具と猟犬を処分して悔い改めたと宣言した。しかしこの身ぶりも玉座を救うには足りず、数か月後に廃位された。", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["ムンカーチ(ムカチェヴェ)要塞の3年間の包囲後のオーストリアへの降伏", "ca2efc3d"], "d": ["1685年末に帝国軍に包囲されたムンカーチ要塞は、テケリ・イムレの妻イロナ・ズリーニの指揮下で3年間抵抗した。多数の刊行された参照文献によれば、要塞は1688年1月17日に将軍アントニオ・カラファに降伏した。これは、オスマン・ハプスブルク戦線においてハンガリーにおける親オスマン抵抗の最後の大要塞のひとつの陥落であった。", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Baltacı Mehmed Paşaと女帝エカチェリーナの伝承", "c1b739f1"], "d": ["プルート川で包囲されたロシア軍の救済を、エカチェリーナ1世がBaltacı Mehmed Paşaに送った贈り物/賄賂に帰する通俗的な語りは、何世紀にもわたって繰り返された。", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["プルートでの「逃した好機」論争 — 二つの見解", "61ee699c"], "d": ["オスマン軍がロシア軍を完全に包囲していたにもかかわらず和平で満足したことは、条約の直後から歴史家のあいだで議論の的となった。TDV 自身の表現では「大きな好機が逃されたことが明らかになり、この主張は反対の考えの者たちによって盛んに論じられた」。批判者によれば、ツァーリを捕虜にでき、ロシア軍の武器を接収できたはずであった。擁護者によれば、スウェーデンが北ヨーロッパで強大になることを防ぐために、ロシアを限定的に弱めることのほうが「賢明な政策」であった。TDV は両方の見解を伝え、どちらにも与しない。", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["32人の学術・翻訳委員会が設立される", "0e3a713c"], "d": ["Damad İbrahim Paşaの宰相職の時期に、イスタンブルで、TDV の言い方では「当時のアカデミーとみなしうる」32人の学者・書記の委員会が設立された。委員会は、アラビア語、ペルシア語、ギリシア語、ラテン語から歴史、哲学、地理の著作をトルコ語にもたらした。Yanyalı Esad Efendiが25人のチームでアリストテレスの『自然学』を訳したこと、詩人ネディームが歴史書の翻訳委員会の長を務めたことなどがそのなかにあった。日は TDV に示されておらず、年のみ表明されている。", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["マフムト1世がパトロナ・ハリルを宮殿に招いて罠にかける", "6147059f"], "d": ["即位から7週間後、マフムト1世は、信頼する者たち — 宮廷ではHacı Beşir Ağa、宮廷外ではクリム・ハンのカプラン・ギライ1世 — を通じて軍の有力者を自分の側に引き込み、パトロナ・ハリルの影響力を砕いた。1730年11月25日、トプカプ宮殿の割礼の間での会合に呼ばれたパトロナ・ハリル、Muslu Beşe、Kel Mehmed Ağaが中に入れられた。大宰相Silâhdar Mehmed Paşaの合図で、あらかじめ潜んでいた32人の武装した男たちが現れ、3人とも殺害した。マフムト1世はこうして反乱の統制を完全に掌握した。", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["フンバラジュ・Ahmed Paşa(ボンヌヴァル)がフンバラジュ軍団の長に任命される", "27b0b1d7"], "d": ["本名クロード・アレクサンドル・ド・ボンヌヴァル伯爵であるフランス出身の将校は、まずフランス軍とオーストリア軍に仕えたのち、サラエヴォでイスラームに改宗してAhmedの名を取り、1729年にオスマン国家に身を寄せた。マフムト1世の治世、1731年にフンバラジュ軍団の長に任命されたAhmed Paşaは、ユスキュダル・アヤズマに建てさせた兵舎で、ボスニアから呼び寄せた300人ほどの兵に訓練を施した。その数は間もなく600を超え、彼自身が数学の授業も行った。フランスのためにハンガリーでラーコーツィと企てた蜂起の試みが彼の影響力を揺るがし、1738年にカスタモヌに流された。1747年5月23日にイスタンブルで没し、墓はガラタ・メヴレヴィーハーネの墓地にある。", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["スメデレヴォのハプスブルク(ハンガリー王冠)からの奪回 — 1737〜39年戦争", "63dcf604"], "d": ["TDV のスメデレヴォ項によれば、1717年にパッサロヴィッツ条約でオーストリアに譲られていた要塞は、1737年に始まったオスマン・オーストリア戦争のドナウ・サヴァ戦線におけるオスマンの進軍によって奪回された。ハプスブルク(ハンガリー王冠)軍は地域で1738年8月まで持ちこたえたが、この日付以降、スメデレヴォは再びオスマン統治に入った。1年後に結ばれたベオグラード条約(1739年9月18日)は、この獲得を — ベオグラードと北セルビアとともに — 追認することになる。", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["モラヴァ谷のオスマン統治への復帰 — Yagodina、Kragujevac、Çaçak", "b219d3c9"], "d": ["1738年8月のスメデレヴォの奪回によって、スメデレヴォとオスマン本体のあいだに残っていたモラヴァ谷もオスマン統治に戻った。Yagodina、Kragujevac、Çaçakはこの日付以降オスマン領とみなされる。資料はこの3か所の復帰を別個に日付づけして記していない。地図はスメデレヴォの日付で動く。ベオグラード条約(1739年9月18日)がこの状況を追認した。", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["アブデュルハミト1世がオズィー陥落の報を読んでいる最中に卒中を起こして死去", "6ac60365"], "d": ["TDV イスラーム百科事典のabdulhamid-i項によれば、ロシア・オーストリア戦争の苦しい経過で健康が著しく悪化していたアブデュルハミト1世は、オズィー要塞がロシア軍に占領されたと告げる大宰相の報告書を読んでいる最中に、突然の卒中により死去した(1203年ラジャブ月11日/1789年4月7日)。遺体は、イスタンブルのバフチェカプに自ら建てさせた廟に葬られた。同日、甥のセリム3世が即位した。", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["オスマン・ロシア防衛同盟 — フランスに対する共同防衛", "c87079d1"], "d": ["ナポレオンのエジプト占領を受けて、セリム3世とロシア皇帝パーヴェル1世は、14か条・8年の防衛同盟を結んだ。両国は、共通の友と敵を持つこと、相互援助、単独講和をしないことを約した。", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["オスマン・両シチリア(ナポリ)防衛同盟 — フランスに対する共同の大義", "1d2be816"], "d": ["フランスによるイタリア、マルタ、エジプトの占領を前に、オスマン国家と両シチリア王国は9か条の防衛同盟を結んだ。両国は共同して戦争を遂行すること、単独講和をしないこと、互いに陸と海で援助を与えることを約した。", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["七島共和国の成立 — ロシア・オスマンの保護下のイオニア諸島", "08839694"], "d": ["1799年にロシア・オスマン連合艦隊がフランス軍をイオニア諸島から追い出し(ケルキラ要塞は1799年3月5日に陥落)、1800年3月21日付の12か条の協定により、島々は内政で自治を持ち、外交ではオスマンに従属する「Cezâyir-i Seb'a-i Müctemia Cumhuru」(七島共和国)として成立した。1799年3月5日からこの日までは共同占領の時期である。", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["ティルジット — 七島共和国に対するロシアの権利がフランスに譲渡される", "98a78beb"], "d": ["ティルジットでロシアとフランスの間で成立した合意により、ロシアは七島に対する権利をフランスに譲り、フランス軍は1807年夏に島々に駐留し、七島共和国は消滅した。", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["アヤマヴラとイオニア諸島のイギリス保護領への移行 — ナポレオン後の秩序", "0af821dc"], "d": ["1797年にフランスに移っていたアヤマヴラとその他のイオニア諸島は、ナポレオンの最終的な敗北の後、1815年11月5日にパリでイギリス、ロシア、オーストリア、プロイセンの間で調印された特別条約により、「イオニア諸島連邦」の名のもとにイギリスの保護下に置かれた。これは1815年11月20日の一般的なパリ条約とは別の文書である。保護は1864年まで続き、その後、島々はギリシアに譲渡されることになる。", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["プリズレンの征服 — コソヴォにおけるオスマンのサンジャク中心地", "f84c220f"], "d": ["859年ラジャブ月4日(1455年6月20日)、征服者メフメト2世の指揮するオスマン軍は、セルビアのデスポトであるジュラジュ・ブランコヴィッチ(オスマン史料ではVılkoğlu)との戦いの後、プリズレンを奪取した。都市は13世紀半ばにビザンツからセルビア王国に移り、ミルティン王、ドゥシャン皇帝、ウロシュ王の時代に王の居所となったが、ドゥシャンの死後は重要性が低下していた。征服の後、サンジャクの中心とされ、1912年までの4世紀半にわたってこの地位を保った。プリズレンは、ユーゴスラヴィア解体以前、バルカンの3つの言語 — アルバニア語、トルコ語、セルビア語 — が共に話される唯一の都市であった。", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["バスティーユの陥落 — フランス革命の始まり", "96e931f1"], "d": ["国王ルイ16世が財務長官ネッケルを罷免したこと(1789年7月11日)が引き起こした怒りと経済危機のさなか、パリの民衆は武器と火薬を求めてバスティーユ要塞に向かった。午後に始まった戦闘で、3000人を超える蜂起者に対してわずか100人ほどの守備兵しかいなかった要塞は、17時ごろに降伏した。要塞司令官ベルナール=ルネ・ド・ローネーを含む数人の役人が殺害され、7人の囚人が解放された。ほとんど空であり、すでに取り壊しが計画されていた要塞は、王権の専制の象徴であった。その陥落は、ルイ16世に「いいえ陛下、これは反乱ではなく、革命です」と告げられたと伝えられる。7月14日は今日フランスの国民の祝日であり、この事件は、まもなく全土に広がった民衆運動とフランス革命(1789〜1799年)の象徴的な始まりとされる。革命は、その後の10年で絶対王政を倒し、ヨーロッパの政治地図とオスマンをも含む国際的な均衡を恒久的に変えることになった。", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["マムルーク軍がマラティヤに入る — 都市がイルハン朝からマムルーク統治に移る", "2540363d"], "d": ["マムルーク朝は、ダマスクス総督Seyfeddin Tengizの率いる軍をマラティヤに向けて送り、軍は715年ムハッラム月22日(1315年4月28日)に都市に入った。マラティヤはその日までイルハン朝の支配下にあり、ユーフラテス川の西で、イルハン朝とマムルーク朝の勢力圏が接する線の要衝であった。都市の支配者の交代は、両国の長い争いのなかでマムルーク朝が上流ユーフラテスに向けて進んだことを示す。マラティヤはこの日付の後、しばらくエレトナ家の統治に入り、1338年から再びマムルーク朝の支配に戻ることになる。", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["エシュレフ侯国の終焉 — ベイシェヒルとセイディシェヒルがハミト侯国に移る", "e4e70846"], "d": ["イルハン朝のアナトリア総督エミール・チョパンの子Demirtaşは、独立を宣言したトルクメンの侯国に対して行動を起こし、ベイシェヒルに入って、かつて自分を訴えたエシュレフ家のSüleyman Şahを殺させた(1326年10月9日)。ベイシェヒルとセイディシェヒルの地方に13世紀末に成立していたエシュレフ侯国は、こうして終わった。TDV のハミト家項がその後を伝える。Demirtaşが除いたエシュレフ家のベイシェヒル、セイディシェヒル、アクシェヒル、ドアンヒサルはハミト侯国の境界に編入された。同年、ハミト家のDündar BeyもDemirtaşに引き渡されて殺された。これらの土地は1381年に8万金でムラト1世に売却されてオスマン統治に移ることになる。", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["マラティヤが再びマムルーク朝の支配下に入る — エレトナ家統治の終焉", "08b80aa2"], "d": ["1315年にマムルーク統治に入ったマラティヤは、イルハン朝国家の解体の年月に、しばらくエレトナ家の手に渡っていた。TDV のマラティヤ項は復帰を一文で伝える。都市は1338年から再びマムルーク朝が支配した。これは、アナトリア南東部でイルハン朝後の空白がマムルーク朝とエレトナ家のあいだで分け合われた年月の一断面である。", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["イズミル港の十字軍艦隊への喪失 — アイドゥン侯国の海軍力が砕かれる", "775c65fe"], "d": ["教皇クレメンス6世の勧めにより、ヴェネツィア、ジェノヴァ、キプロス王国、ロドス騎士団、ナクソス公の船で組織された十字軍艦隊は、イズミル港をアイドゥン侯国から奪った(1344年10月28日)。港は、ウムル・ベイの父Mehmed Beyが1328〜1329年にジェノヴァ人マルティーノ・ザッカリアから奪ったもので、エーゲ海におけるアイドゥン侯国の海軍力の拠点であった。1334年9月に同じ目的で来た十字軍艦隊は撤退を余儀なくされたが、この2度目の遠征は成功した。ウムル・ベイは抵抗を続け、他のトルコ系侯国と結んで1345年1月17日に十字軍艦隊を破ったが、港は取り戻せなかった。", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["カラマン侯Alâeddin Beyがコンヤ、アクサライ、ニーデをカラマンの領土に編入", "2b8b0f70"], "d": ["マムルーク朝がアルメニア王国を滅ぼしてチュクロヴァ全域を自領に編入したことと、中央アナトリアのエレトナ国家で起こった混乱を利用しようとしたカラマン侯Alâeddin Beyは、コンヤ(1366〜1367年)を筆頭に、ニーデ・カラヒサル(イェシルヒサル)、アクサライ、アクシェヒル、ウルギン、イスハクル、カイセリをカラマンの領土に編入した。コンヤはセルジューク朝の首都としての重みから、カラマン家にとって単なる一都市ではなく、正統性の主張であった。", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["ウズン・ハサンがカラ・コユンル国家を終わらせる — ヴァン湖盆地がアク・コユンルに移る", "d8d6c2e8"], "d": ["アク・コユンルの君主ウズン・ハサンは、1467年に自らに向かって進軍してきた不倶戴天の敵、カラ・コユンルの君主ジャハーン・シャーの不意を突いて、カラ・コユンル国家を終わらせた。1438年から統治していたジャハーン・シャーの消滅により、ヴァン湖盆地 — ヴァン、ビトリス、Bargiri(ムラディエ)、Hoşap、Kotur — はカラ・コユンルからアク・コユンルの統治に移った。この勝利はアク・コユンル国家を東アナトリアとイランにおける唯一の大国とし、ウズン・ハサンを、一世代後にオスマンと対峙させる道に乗せた。", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["ジェム・スルタンがローマに連れてこられる — 人質外交と年4万ドゥカート", "1c6715a8"], "d": ["教皇インノケンティウス8世は、ロドス騎士団の長ピエール・ドービュッソンと合意して、ジェム・スルタンをローマに連れてこさせた(1489年3月4日)。ジェムは1482年7月29日にロドスに身を寄せ、そこからサヴォワの地に、最終的に教皇の監視下に移っていた。バヤジト2世は、弟を拘束しておくことへの見返りとして、騎士団に年4万ドゥカートを支払い、彼らにオスマン領内での自由貿易の権利を与えることを受け入れていた。この支払いは貢納ではなく、王位の正統な競争者をヨーロッパで動けなくしておくための代価であった。ジェムが自由になれば、アナトリアで軍を集めることができ、さらには十字軍の正統性の源泉となりえた。こうして王朝の問題は、30年にわたりオスマン外交の主たる制約となった — バヤジトが西方で慎重に振る舞った理由はこれである。この制約は、1495年のジェムの死によって取り除かれた。", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["ジョージア王国が三分される — カルトリ、カヘティ、クタイシを中心とするイメレティ", "f9c5f798"], "d": ["バグラティオニ家の治める統一ジョージア王国は、長い内部抗争の末に正式に3つの王国に分かれた。東のトビリシを中心とするカルトリ、北東のカヘティ、西のクタイシを中心とするイメレティである。TDV のジョージア項は分割を裏づけている — 「ジョージアは3つの王国(Kartliya、Kahetya、İmeretiya)と5つの侯国に分かれた」。この分割は、次の世紀のオスマン・サファヴィー朝の争いにおいて決定的となった。1555年のアマスヤ条約によれば、イメレティ、Dadyan、Güryel、Daveliはオスマンに、カルトリ、カヘティ、Mosukはサファヴィー朝に残された。すなわち、atlasが西ジョージアと東ジョージアを別々の主に帰属させることは、この分割に由来する。ヤヴズ・スルタン・セリムは、まだトラブゾン総督であった1508年に、イメレティ(Açıkbaş)王国を服従と貢納の下に置いていた。", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["トリポリのスペインによる占領 — ハフス朝支配の終焉", "de319d23"], "d": ["アンマール家の後、トリポリにおけるハフス朝の支配は1510年まで続いた。その年、都市はオリヴェート伯ドン・ペドロ・ナバロの率いるスペイン軍に占領され、虐殺を免れたムスリムは都市を去った。占領は、スペインの北アフリカ沿岸におけるメリリャからトリポリに至る要塞網の東端であった。トリポリの人々は925年(1519年)にイスタンブルへ使節を送り、スペインの侵略に対してオスマンの援助を求めることになり、都市は1551年にトゥルグト・レイスとスィナン・パシャによって奪取されてオスマン統治に入ることになる。", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["マルタとトリポリが聖ヨハネ騎士団に与えられる — ロドスを追われた騎士団の新たな拠点", "2595729e"], "d": ["スレイマン1世が928年(1522年)にロドスから追い出した聖ヨハネ(ホスピタル)騎士団は、8年間の無国籍の後、スペイン・ドイツ王カール5世によってマルタに定住させられた。同じ寄進で、トリポリの防衛も騎士団に与えられた。マルタは、理想的な港を持つことから、海で力を持つ騎士団にとって好都合な拠点となった。彼らはまずビルグに定住し、サンタンジェロ要塞を強化し、センリア岬にサン・ミシェル要塞を築いた。この定住は、地中海の真ん中でオスマンの海路を断つ恒久的な敵の拠点を生んだ。トゥルグト・レイスの947年(1540年)のゴゾ島襲撃に始まる衝突は、1565年のマルタ包囲まで続くことになる。", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["ヴェストファーレン和約 — 三十年戦争が終結し、神聖ローマの統一が解体", "d7719f05"], "d": ["三十年戦争(1618〜1648年)を終わらせた条約は、ミュンスターとオスナブリュックで同じ日に調印された(1648年10月24日)。神聖ローマ帝国の300ほどの侯国は、独自の外交を行う権利を得た。帝国は国家であることをやめ、屋根のようなものに変わった。スウェーデンは西ポンメルンとシュテッティンを取り、ブランデンブルクは東ポンメルンとマクデブルク大司教領の継承権を得た — ホーエンツォレルン家が1701年に王国へと進む領土の蓄積はここに始まる。オランダとスイスの独立は正式に承認された。オスマンにとっての意味は間接的だが大きい。ハプスブルク家が西部戦線から手を引いたことで、中央ヨーロッパに再び東へ向きうる力が生まれた。", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["プロイセン王国の宣言 — フリードリヒ1世がケーニヒスベルクで戴冠", "337a9f74"], "d": ["ブランデンブルク選帝侯フリードリヒ3世は、皇帝レオポルト1世の同意を得て、ケーニヒスベルクで戴冠し、「プロイセンにおける王」の称号を得た(1701年1月18日)。称号は東プロイセンから取られた。そこが神聖ローマ帝国の外にあり、皇帝に従属する選帝侯は帝国の境界の外でしか王になれなかったからである。ホーエンツォレルン家の散らばった領土は、この日以降、ひとつの国家の名で呼ばれるようになった。", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["サルデーニャがスペインからサヴォイア家に移る — サルデーニャ王国の誕生", "adf778b7"], "d": ["スペイン継承戦争を締めくくる取り決めの最後の環で、サルデーニャ島はスペインから取り上げられてサヴォイア家に与えられた。サヴォイア公はその代わりにシチリアを手放し、サルデーニャ王の称号を得た。カリャリとサッサリはこうして2世紀にわたるスペイン統治から離れた。誕生したサルデーニャ王国は、1世紀半後にイタリア統一を成し遂げる国家の核である。すなわち、1870年にローマに入ったイタリア王国の根はここに遡る。", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["コルシカがジェノヴァからフランスに売却される — ヴェルサイユ条約", "770343df"], "d": ["ジェノヴァ共和国は、何世紀も保持してきたが反乱のために事実上統制できなくなっていたコルシカをフランスに譲渡した。TDV のコルシカ項は事件を一文で伝える。ジェノヴァはあまり自分のものにできなかったこの島を、1768年にフランスに売った。譲渡は、ジェノヴァが地中海における最後の大きな領土的存在から撤退したことを示す。島は1796年にしばらくイギリスの手に渡り、のちに再びフランスに返還されることになる。島がフランス領であったことが、翌年アジャクシオで生まれるナポレオン・ボナパルトをフランスの臣民とした。この年(1768年)、コルシカはバスティアを含めてジェノヴァからフランスに売却された(TDV コルシカ項。日は未確認)。", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["ティルジット条約 — プロイセンが領土の半分を失い、ワルシャワ公国が成立", "d30bb2cc"], "d": ["イエナ・アウアーシュタットの敗北の後、プロイセンはナポレオンとティルジットで過酷な講和を受け入れざるをえなかった(1807年7月9日)。エルベ川以西のすべての土地と、1793年と1795年の分割で得たポーランドの土地を手放した。後者からワルシャワ公国が作られ、ビャウィストク周辺はロシアに与えられた。プロイセンは人口と領土のおよそ半分を失い、軍は4万2000に制限された。atlas では、ポズナンとトルンはこの日からワルシャワ公国に、ビャウィストクはロシアに移る。この条約により、ウッチとチェンストホヴァ(1772年以降にプロイセンに移ったポーランドの州)はワルシャワ公国に移り、グダニスク(ダンツィヒ)は独立の自由都市となった。", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["イタリア軍がローマに入る — 教皇領の終焉とイタリア統一の完成", "a3689f2e"], "d": ["普仏戦争でナポレオン3世が倒れ、ローマを守っていたフランス守備隊が撤退すると、イタリア軍が都市に入り、教皇はヴァチカンに退いた。こうして1000年を超えて存続した教皇領は終わり、ローマをも統一に加えたイタリア王国は政治的な力としてヨーロッパと世界の舞台に現れた。これは atlas の最後の半世紀にとって直接の帰結をもたらす事件である。統一されたイタリアは、1911年にトリポリとドデカネス諸島をオスマンから奪う国家である。", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["チェレンコの戦い — ハラル首長国の終焉とエチオピアの占領", "5671a0d9"], "d": ["ダーウードがアウサのイマームになると、オロモの統治する土地の真ん中に残されたハラルは再び独立した首長国となり、1887年のエチオピアの占領までこの状態を保っていた。ジハードを宣言した首長アブドゥッラーは、5000人の兵を率いて1887年1月7日にエチオピア軍をシェレネコ(Çelenko)で迎え撃ったが、敗北を悟ると南ハラルのオガデン地方へ逃れた。戦いは、火器で装備されたエチオピア軍と首長国軍の不均衡を示し、紅海の彼方の最後の独立したムスリム首長国のひとつを消した。ハラル、ジジガ、ダガブールはこうしてエチオピアに編入された。", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["シャー・イスマーイールのデルベント奪取 — サファヴィー朝の支配がカフカスの門に達する", "305542c4"], "d": ["シルヴァンシャーのファッルフ・ヤサールが1500年に敗れて殺されたことで、バクーとシャマヒはサファヴィー朝の手に渡っていたが、デルベントはさらにしばらく別に残っていた。シャー・イスマーイールは1509年に都市を攻略し、ルームル部族のひとつをここに入植させた。こうしてサファヴィー朝の支配は、カフカスの北の門、カスピ海と山々のあいだのこの狭い通路に達した。1538年にシルヴァンがサファヴィー朝の直接統治に入ることで、結びつきは恒久的となった。デルベントは1578年の遠征でオスマンの手に渡り、1607年まで7つのサンジャクを持つベイレルベイ領の中心となることになる。TDV の記述は次のとおり。「サファヴィー朝国家の成立と発展は、デルベントにおける新たな時代の始まりをなした。シャー・イスマーイールは1509年に都市を攻略し、ルームル部族のひとつをここに入植させた。1538年にシルヴァンが直接サファヴィー朝の支配に入ると…」", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["カルスのオスマン領への最終的編入 — 東の国境の要", "6235c85a"], "d": ["アク・コユンル国家がサファヴィー朝によって滅ぼされた後、カルスはしばらくアフシャール系トルクメンのSevündük Han Kurçibaşıの手にあった。スレイマン1世の二つのイラク遠征(940年/1534年)のあいだ、Pasin、Şüregel、Oltuの城が奪取されたとき、カルス要塞もオスマンに服した可能性が極めて高いが、都市の最終的な編入はその3年後である。TDV の記述は次のとおり。「カルスは、オスマンに仕えていたドゥルカディル家のMehmed Hanによって、944年(1537年)に最終的にオスマン領に編入された。」長い争いのために都市と要塞が大きく荒廃していたため、迅速な修復が着手された。955年(1548年)に要塞が修復されているときにサファヴィー朝が都市を攻撃し、要塞を再び破壊した。カルスはこの後340年にわたり、オスマンの北東国境の錠前としてとどまり、1877〜78年の戦争の後、ロシアに譲られることになる。", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["ニコポルの奪回 — 6か月のロシア占領が終わる", "7fb299d7"], "d": ["1806〜1812年のオスマン・ロシア戦争でドナウ川の南岸に渡ったロシア軍は、1810年10月に将軍クトゥーゾフの指揮のもとでニコポルを奪取していた。6か月後、ドナウ線を保てないと悟って都市を放棄した。去る前に、要塞の重要な部分を爆破した。TDV の記述は次のとおりである。「1810年10月(1808〜1812年のトルコ・ロシア戦争の時期)、ニコポルは有名なロシア将軍ミハイル・クトゥーゾフの軍によって奪取された。ロシア軍は都市を去る前、1811年4月に要塞の重要な部分を爆破して都市に大きな損害を与えた。」ロシア軍の撤退の後、オスマンは要塞を再建させた。1813〜1814年の碑文はこの修復の記録である。", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["スィリストレの撤収 — ドナウの中央の要塞が城壁を破壊されたまま放棄される", "561628bb"], "d": ["ドナウ川のオスマン最強の要塞のひとつスィリストレは、1810年にロシア砲兵の砲撃を受け、武器庫の爆発によって要塞と市外区が大きく損なわれた。ロシア軍は都市を奪取した後、保持するかわりにその防備を破壊することを選んだ。クトゥーゾフ将軍は城壁の破壊を命じ、1811年5月にツァーリにスィリストレの城壁が爆破されたことを報告した。TDV の記述は次のとおり。「1810年に都市はロシア軍に砲撃された…ロシア軍が都市を奪取した後、撤退する前に、クトゥーゾフ将軍はスィリストレの破壊を命じた。1811年5月、ツァーリにスィリストレの城壁が爆破されたことを報告した。」同じ要塞は、1827〜1828年の戦争でロシア軍によって再び奪取され、その包囲をヘルムート・フォン・モルトケが詳しく描くことになる。", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["ザンド朝の終焉 — イランにおけるガージャール朝の支配", "5dda30a4"], "d": ["ザンド朝の最後の君主ロトフ・アリー・ハーンの敗北により、1751年に成立した王朝は終わり、イランの全体がアーガー・ムハンマド・ハーンの手に渡った。ガージャール国家の正式な成立は2年後、アーガー・ムハンマド・ハーンがテヘランで王の中の王の冠を戴いた年(1796年)とされるが、実効支配は1794年に移っている。", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["ローザンヌとセーヴルの相違: 押しつけられた講和から対等な講和へ", "4b578583"], "d": ["セーヴル(1920年8月10日)はイスタンブル政府に押しつけられた、一度も発効しなかった文書であった。一方ローザンヌ(1923年7月24日)は、アンカラが対等な当事者として調印し、トルコ大国民議会が1923年8月23日に承認した講和である(ローザンヌ第1条、第143条)。国境について、セーヴルはトルコのヨーロッパ側の国境をチャタルジャ線まで引き下げ、エディルネを含む東トラキアとイムロズ(ギョクチェアダ)およびボズジャアダをギリシアに与える(セーヴル第27条、第84条)。イズミルとその周辺は、名目上はトルコの主権下にとどめられるが統治はギリシアに委ねられ、5年後に現地の議会が編入を求めることができる(第65〜83条)。ローザンヌはメリチ・アルダ線を引き、エディルネとカラアーチュはトルコにとどまり、イムロズとボズジャアダはトルコ領となる(ローザンヌ第2条、第12条、第14条。カラアーチュ議定書)。海峡について、セーヴルはすべての水域に及び、トルコ人の委員が1票のみを持つ国際委員会を設け、要塞は破壊され、地域は連合国の使用に開放される(セーヴル第36〜61条、第178〜180条)。ローザンヌは自由通航の原則を保つが、トルコ人を議長とする委員会、非武装地帯、イスタンブルに置く1万2000人の守備隊を残す(ローザンヌ第23条。海峡条約)。アルメニアの承認と米国大統領による国境の仲裁、およびクルドの自治計画(セーヴル第62〜64条、第88〜93条)はローザンヌには含まれない。アラブの地、エジプト、スーダン、キプロスについて、セーヴルは詳細な譲渡条項を置く(セーヴル第94〜97条は委任統治、第98〜100条はヒジャーズ、第101〜122条はエジプト、スーダン、キプロス、モロッコ、チュニジア、リビアの放棄。TDV の条項の範囲もこれと同じ)。ローザンヌは放棄をより簡潔に記し、ドデカネス諸島はイタリアに、キプロスはイギリスに残り、モスルの国境は先送りされる(ローザンヌ第3条、第15〜21条)。セーヴルはカピチュレーションを再建して拡大し、財政委員会によってトルコの予算と借入を監督し、武装兵力(憲兵とその増強要素)は5万人を超えてはならず、軍事・海軍の航空は禁止される(セーヴル第155条、第164条、第191〜195条、第231〜264条、第261〜263条)。ローザンヌはカピチュレーションを廃止し、債務を分担させ、独立した軍の制限は置かない(ローザンヌ第28条、第46〜63条。第113条は外国郵便局も廃止する)。少数者条項は、セーヴルではより広く連合国の介入に開かれているのに対し、ローザンヌでは国際連盟が保証する相互的なものである(セーヴル第140〜151条。ローザンヌ第37〜45条)。\n\n軸ごとの比較:\n• 東トラキア、エディルネ、チャタルジャ — セーヴル: チャタルジャ線が国境。東トラキアとエディルネはギリシアへ(第27条、第84〜85条) | ローザンヌ: メリチ川とアルダ川に沿う国境。エディルネとカラアーチュはトルコに(第2条。カラアーチュ議定書)\n• イズミル地方 — セーヴル: 主権はトルコ、統治と軍はギリシア、5年後に編入の申請(第65〜83条) | ローザンヌ: イズミルについての特別の地位の条項はなし。アナトリアはトルコの国境内にある(第2〜3条の一般の国境。イズミル個別の条文上の根拠はなし)\n• 海峡とイスタンブル — セーヴル: 国際海峡委員会、トルコは1票。要塞の破壊、地域は連合国の使用下。イスタンブルはトルコの手にあるが少数者の条件に従う(第36〜61条、第178〜180条) | ローザンヌ: 自由通航の原則。トルコ人を議長とする委員会、非武装地帯、イスタンブルに1万2000人の守備隊(第23条。海峡条約)\n• アルメニアとクルディスタン — セーヴル: アルメニアが承認され、国境は米国大統領が決定。クルドの自治、1年後に独立の申請(第62〜64条、第88〜93条) | ローザンヌ: 該当する条項なし(第1〜143条の要約には出てこない)\n• エーゲ海の島々、ドデカネス諸島 — セーヴル: イムロズ、ボズジャアダとエーゲ海の島々はギリシアへ。ドデカネス諸島とカステッロリゾはイタリアへ(第84条、第122条) | ローザンヌ: イムロズとボズジャアダはトルコに、東エーゲ海の島々はギリシアに、ドデカネス諸島とカステッロリゾはイタリアに(第12〜15条)\n• キプロス、エジプト、スーダン、アラブの地 — セーヴル: シリア/メソポタミアとパレスチナの委任統治、ヒジャーズは独立。エジプトの保護、スーダン、キプロスの併合が承認される(第94〜98条、第101〜117条) | ローザンヌ: シリアの国境は1921年のフランス・トルコ協定に、イラクの国境は後日に。エジプト、スーダン、キプロスの放棄(第3条、第16〜20条)\n• カピチュレーション — セーヴル: 再建され、拡大される。司法改革の計画は連合国の委員会に(第136条、第261〜263条、第308〜309条) | ローザンヌ: 完全に廃止。外国郵便局と最高衛生評議会は廃止(第28条、第113〜114条)\n• 財政統制と債務 — セーヴル: 連合国の財政委員会が予算と借入を監督し、オスマン債務管理局が拡大し、財源が担保となる(第231〜264条) | ローザンヌ: オスマン債務管理局は諸国家の持分に分けられる。戦争損害は相互に放棄される(第46〜63条、第58条)\n• 軍事上の制限 — セーヴル: 軍は5万人、空軍と戦車は禁止、連合国の統制委員会(第152〜207条) | ローザンヌ: 一般の制限はなし。ギリシア領の島々と海峡・トラキア地域のみの非武装化(第13条。海峡とトラキアの条約)\n• 少数者 — セーヴル: 連合国の保証と介入の権利、放棄財産の取り消し、返還(第140〜151条、第86条、第142〜144条) | ローザンヌ: 非ムスリム少数者に国際連盟が保証する権利、ギリシアにおけるムスリムの相互的権利。ギリシア・トルコ住民交換(第37〜45条。住民交換条約)\n• 法的地位 — セーヴル: イスタンブル政府により調印され、アンカラは拒否し、発効しなかった(TDV) | ローザンヌ: 対等な当事者。トルコ大国民議会の承認は1923年8月2日、賛成213、反対14(TDV。第1条、第143条)", "95c8b4ce"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["最初のオスマン朝のアクチェの鋳造", "38d2d638"], "d": ["オルハン・ガーズィーの名で鋳造された最初の銀のアクチェは、侯国の独立した主権の貨幣上の宣言である。アクチェは5世紀にわたり基本の貨幣単位であり続けた。", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["ルメリア・ベイレルベイリクの設立", "ffa16089"], "d": ["ヨーロッパ側の征服地が一つの軍事・行政の傘の下にまとめられた。ベイレルベイリクの体制は、帝国の地方組織の背骨となった。", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["イルドゥルム・バヤジトとデスピナ・ハトゥンの婚姻", "4b10dc6c"], "d": ["コソヴォの後にセルビア専制公国との間で築かれた従属関係は、ラザルの娘オリヴェラとバヤジトの婚姻によって固められた — 初期の婚姻外交の典型的な例である。", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["アナトリア・ベイレルベイリクの設立", "5ef8d3a7"], "d": ["併合された侯国の領土の統治のために、アナトリア・ベイレルベイリクが組織された。ルメリアとアナトリアの双翼の行政体制が完成した。", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["ブルサのウル・ジャーミィの完成", "27bcc4a5"], "d": ["ニコポリスの戦利品で建てさせた二十のドームを持つウル・ジャーミィは、初期オスマン建築の記念碑的な例であり、書道の野外博物館である。", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["チャンダルル・ハリル・パシャの罷免と処刑", "5e19438f"], "d": ["征服の後、包囲に距離を置いていた名門チャンダルル家出身の大宰相が処刑された。大宰相が初めてスルタンの命令で殺され、デヴシルメ出身の宰相の時代が開かれつつあった。", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["モルダヴィアの貢納化", "25bd3693"], "d": ["モルダヴィアのヴォイヴォダ領は貢納の支払いを受け入れた。ワラキア、トランシルヴァニアとともに、ドナウ北方の三重の従属地帯は、帝国の北の緩衝地帯となった。同じ日に加わったその他の地：Yaş。", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["ドゥブロヴニク（ラグーザ）の貢納", "d127c78a"], "d": ["商人共和国ラグーザは、貢納と引き換えに自治と通商特権を確保した。オスマン朝のアドリア海への窓として豊かになった。共和国の領土であるムリェト（Mljet）島も、この地位を共有した。", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["ワラキア遠征：串刺し公", "fd4530bb"], "d": ["貢納の支払いを拒み使者を殺したヴラド・ツェペシュに対して行われた遠征により、ワラキアは従属に戻された。夜襲と串刺しの恐怖の場面は、ヨーロッパで伝説となった。同じ日に加わったその他の地：Bükreş。", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["ファーティフ複合施設の開設", "a150ea55"], "d": ["八つのマドラサ（Sahn-ı Semân）を持つこの複合施設は、イスタンブルをイスラーム世界の学問の中心に変える計画の最初の大きな一歩であった。", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["アリー・クシュチュ、イスタンブルに", "8508229d"], "d": ["サマルカンド天文台の最後の大きな代表者アリー・クシュチュは、ファーティフの招きでアヤソフィア・マドラサの教授となった。イスタンブルに数学・天文学の伝統を築いた。", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["ファーティフ・カーヌーン・ナーメ", "b08944c9"], "d": ["国家の機構、儀礼、刑罰をまとめた最初の包括的な慣習法典。「世界の秩序のために」兄弟殺しを許可する有名な条項をめぐって、議論が続けられてきた。", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["最初のオスマン朝の金貨（スルターニー）の鋳造", "2fd5c0dd"], "d": ["ヴェネツィアのドゥカートに相当する最初のオスマン朝の金貨が鋳造された。帝国の財政は国際的な貨幣秩序に加わった。", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["トプカプ宮殿への移転", "b9cd6a5e"], "d": ["新宮殿（トプカプ）の完成により、国政の中心はここに移った。宮殿は4世紀にわたり帝国の頭脳であり続けた。", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["フィレンツェ共和国が公国に転換 — アレッサンドロ・デ・メディチ", "c08764e1"], "d": ["教皇クレメンス7世の圧力により、フィレンツェの統治委員会（バリーア）は新しい憲法を採択した。5世紀続いた共和政体は廃され、アレッサンドロ・デ・メディチが世襲の公と宣言され、5月1日に事実上即位した。フィレンツェはこうして、独立した都市共和国からメディチ家の世襲の公国に転換した。", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["カーヌーニーとヒュッレム・スルタンの婚姻", "abc05f26"], "d": ["カーヌーニーがヒュッレムと正式な婚礼を挙げたことは、宮廷の慣習を根本から変えた。「ハセキ・スルタン」の制度が生まれ、王朝政治における女性の時代の扉が開かれた。", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["フランスへの最初の包括的なカピチュレーション", "e2264e48"], "d": ["ハプスブルクの挟撃に対するフランスとの同盟の一環として、ジャン・ド・ラ・フォレとマクブル・イブラヒム・パシャの間で通商上の特権が調印された。その日には外交の手段であったカピチュレーションは、世紀を重ねるうちに財政的従属への扉となることになった。", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["インド洋遠征：ディウ包囲", "fcd1217a"], "d": ["スエズから出た艦隊は紅海を越えてグジャラートのディウを包囲した。城塞は取れなかったが、オスマン朝の力は初めてインド洋に及び、ポルトガルの独占は揺らいだ。", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["スィーディー・アリー・レイスのインドへの旅", "e5da3b2c"], "d": ["バスラの艦隊をエジプトに連れ帰る任務を負ったスィーディー・アリー・レイスは、嵐によりインドに流された。帰途の冒険を語った『諸国の鏡（Mir'âtü'l-memâlik）』は、最初のオスマン朝の旅行記の一つである。", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["ピーリー・レイスの処刑", "63026444"], "d": ["ホルムズ遠征から艦隊をバスラに残して戻った大航海者・地図製作者は、84歳で処刑された — わが国の科学史における最も議論のある決定の一つである。", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["スレイマニエ複合施設の開設", "1c6458b2"], "d": ["建築家シナンが「見習い（カルファ）の作品」と呼んだこの複合施設は、マドラサ、病院（ダールッシファー）、図書館を備え、古典期最大の教育・慈善の複合体となった。", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["マルタ包囲", "f57f6a85"], "d": ["地中海の鍵であるマルタは四か月包囲された。トゥルグト・レイスは戦死し、包囲は解かれた。カーヌーニー時代の海軍にとって最初の大きな後退となった。", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["セリミエ・モスクの完成", "3b0484e1"], "d": ["シナンが「親方の作品」と呼んだ、単一のドームが空間を支配するセリミエは、オスマン古典建築の頂点とみなされる（ユネスコ世界遺産）。", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["イスタンブル天文台の設立", "169bdf5d"], "d": ["タキユッディーンの、当時最も設備の整った観測所の一つであった天文台は、1577年の彗星の後に起きた論争により1580年に破壊させられた。制度としての天文学は3世紀遅れた。", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["チュルドゥルの勝利 — 東方戦争の開始", "13125a54"], "d": ["サファヴィー朝の軍がチュルドゥル（Çıldır）で敗れたことで、カフカースの門が開かれた。トビリシが取られ、ジョージアはオスマン朝の支配下に入った。", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["松明の戦い — シルヴァンが決定的にオスマン朝に", "3bbc23bc"], "d": ["夜の松明の灯りの下でも続けられたためこの名で呼ばれる戦いで、サファヴィー朝は決定的に敗れた。シルヴァンとバクーにおけるオスマン朝の支配は固められた。", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["大悪貨改鋳 — アクチェの危機", "9205c3d4"], "d": ["長期の戦争とアメリカ大陸の銀の圧力により、アクチェの銀の含有量は半分に引き下げられた。価格革命は、シパーヒー制の解体とジェラーリーの混乱を助長した。", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["タブリーズの征服", "6506bdb9"], "d": ["セルダール・オズデミロウル・オスマン・パシャはタブリーズに入った。サファヴィー朝の旧都はオスマン朝の統治下に置かれた。オスマン・パシャは数週間後に陣営で死去した。", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["フェルハド・パシャ条約 — 東方における最大の国境", "c429972f"], "d": ["シャー・アッバースの使節ハイダル・ミールザーのイスタンブル到着（1590年1月18日）の後、征服した地がオスマン朝に残ることを条件に結ばれ、12年に及んだ戦争を終結させた条約により、タブリーズ、カラバフ、シルヴァン、ジョージア、ルリスタンがオスマン朝に残った。帝国は東方で、歴史上最大の国境に達した。", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["オスマン＝サファヴィー戦争（1603〜1612年）の開始 — シャー・アッバースの反攻、タブリーズの喪失", "abf27dd8"], "d": ["軍を再編したシャー・アッバースは、ジェラーリーの混乱に乗じて攻勢に転じた。タブリーズは陥落し、カフカースでの獲得地は数年のうちに失われた。同じ遠征とその後に失われたその他の集落：Nahçıvan, Hoy, Merend, Selmâs。カラジャダー（アハル）とムクリーの諸侯もサファヴィー側に戻った。", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["エヴリヤ・チェレビーの誕生", "2b6051ff"], "d": ["五十年を超える旅を十巻の『旅行記（セヤハトナーメ）』にまとめたエヴリヤ・チェレビーは、17世紀のオスマン世界の比類のないパノラマを残した。", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["ナスーフ・パシャ条約", "bb69e388"], "d": ["1603年から続いた戦争を終結させた条約により、1590年の獲得地は放棄され、1555年のアマスヤの国境に戻った。東方戦線で均衡が再び築かれた。", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["スルタンアフメト・モスクの開堂", "e39dfd43"], "d": ["六本のミナレットと青いイズニクのタイルをもつ「ブルーモスク」は、古典期最後の大きなスルタンの複合施設である。", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["スルタン・イブラヒムの殺害", "bc4eb452"], "d": ["浪費と統治の行き詰まりを理由に、軍団とウラマーの同盟はイブラヒムを廃位した。十日後にファトワーにより絞殺された。七歳のメフメト4世が即位し、権力は事実上、大母后キョセム・スルタンの手に移った。", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["キャーティブ・チェレビーの死", "e167e89d"], "d": ["書誌『諸学の疑念の解明（Keşfü'z-zunûn）』と地理書『ジハーンヌマー』でオスマンの学問史の頂点に立つ人物。ヨーロッパの文献を用いる先駆的な手法で知られる。", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["エディルネ事件 — ムスタファ2世の廃位", "0291c1cd"], "d": ["スルタンがエディルネに居住したことと、フェイズッラー・エフェンディの権勢への怒りが、軍と商工業者の大蜂起に発展した。シェイヒュルイスラームはリンチされ、スルタンは廃位され、宮廷はイスタンブルに戻った。", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["パリへの大使：ユルミセキズ・メフメト・チェレビー", "26312a3f"], "d": ["フランスに送られた大使節は、西欧を現地で調べた最初の体系的な観察となった。その『使節記（Sefâretnâme）』はチューリップ時代の刷新に着想を与えた。", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["最初のオスマン朝の印刷所の設立", "4943f7e5"], "d": ["トルコ語の書物を印刷する許可が与えられた。最初の著作『ヴァンクル辞典』は1729年に印刷された。印刷所は、チューリップ時代の刷新の最も永続的な遺産である。", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["カピチュレーションの恒久化", "d044a79e"], "d": ["フランスに与えられた特権はスルタン一代に限られるものではなくなり、恒久的な条約に結びつけられた。一方的に廃棄できなくなったカピチュレーション体制は、ローザンヌでようやく廃止された。", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["帝国海軍工学校の設立", "9bf3f439"], "d": ["チェシュメの惨事の後に近代的な海軍士官を養成するために設立された工学校は、西洋式の技術教育の最初の恒久的な機関である。陸軍の工学校は1795年に続いた。", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["ロンドンの最初の常駐大使館", "6b5630eb"], "d": ["ニザーム・ジェディード計画の一環として、ヨーロッパの首都に常駐大使館が開かれた。オスマン外交は相互主義の原則に移った。", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["アレムダル・ムスタファ・パシャの死", "4426534e"], "d": ["1808年11月15日の夜に始まったイェニチェリの蜂起で、バーブ・アーリーで包囲された改革派の大宰相は、期待した援軍が来なかったため、翌日に火薬庫に火をつけ、数百人の攻撃者とともに死んだ。同盟の誓約書（セネディ・イッティファーク）の体制と最初の改革の試みは、彼とともに葬られた。", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["最初の官報：Takvîm-i Vekāyi", "c637f623"], "d": ["国家の官報の発行が始まった。近代的な世論と公式の通達の伝統の始まりである。", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["バルタ・リマヌ通商条約", "e790b383"], "d": ["イギリスには国内取引においてさえ最も特権的な地位が認められ、専売（イェド・イ・ヴァーヒド）の制度は廃止された。国内の生産が保護を失う中で、この条約はオスマン市場が自由貿易に完全に開かれたことを示す文書となった。", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["レバノン首長国の終わり — ベシール・シハーブ3世の解任", "f85ae454"], "d": ["キリスト教徒とドルーズ派の対立とシューフ地方の内部の均衡を制御できなかった首長ベシール2世（3世）は、1842年1月に解任された。1516年から（マアン家、続いてシハーブ家の手によって）続いた地方の首長国の体制は終わり、地域は直接のオスマン朝の統治に、続いて二重のカイマカム制に移った。", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["貨幣改革（Tashîh-i sikke）：メジディイェ体制", "c77be809"], "d": ["貨幣改革により品位の悪化した貨幣が回収され、金リラ（メジディイェ）を基礎とする安定した金銀複本位制が確立された。", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["バールベックにおけるハルフーシュ家の地方支配の終わり", "8438f4ae"], "d": ["1521年から（ジャンビルディー・ガザーリーの反乱の後）バールベックで小さな地方王朝として支配してきたハルフーシュ家の勢力は、バーブ・アーリーの新しい行政の整備によって終わった。都市はダマスクス州に属する平凡な郡の中心とされた。", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["シルケティ・ハイリイェ（Şirket-i Hayriyye）の設立", "462830e7"], "d": ["ボスポラス海峡で蒸気船を運航するために設立された会社は、最初のオスマン朝の株式会社とみなされる。都市の生活には蒸気船の桟橋が刻印された。", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["最初の対外債務契約", "9017c579"], "d": ["クリミア戦争の資金のために、ロンドン市場から最初の対外借款が受けられた。21年間で15回の借入を重ねて至った地点は、1875年のモラトリアムとデュユーン・ウムーミイェであった。", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["電信線のイスタンブルへの到達", "d320f39f"], "d": ["クリミア戦争の必要から敷設された最初の電信線が運用に開かれた。帝国は数十年のうちに、世界で最も広い電信網の一つを手にした。", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["土地法（アラズィ・カーヌーン・ナーメ）", "6bae243a"], "d": ["土地法を近代化した法典は、国有地（ミーリー）における事実上の処分権を地券に結びつけた。今日の中東の所有秩序の基礎文書の一つである。", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["ダールルフュヌーン（Dârülfünun）での最初の講義", "08f74066"], "d": ["大学レベルの教育を行うダールルフュヌーンが、公開講義で活動を始めた。中断を挟みつつ続いた機関は1900年に恒久的に開設され、イスタンブル大学の核となった。", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["州制規則（ヴィラーイェト・ニザームナーメ）", "ad20853b"], "d": ["エヤレット制に代えて、フランスの模範に基づく州（ヴィラーイェト）の組織が築かれた。ミドハト・パシャのドナウ州での実施を手本として、全国に広められた。", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["アブデュルアジズのヨーロッパ旅行", "9ff0fa1e"], "d": ["オスマン朝のスルタンによる、平和を目的とした最初のヨーロッパ旅行。パリ万博とロンドン訪問は、外交と近代化の両方の陳列窓の役割を果たした。", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["ガラタサライ帝国学院の開設", "f9688524"], "d": ["フランス語で教育を行う高等学校は、宗教や民族の区別をしない学生構成によって、タンジマートの教育における平等の理想の象徴となった。", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["メジェッレ（Mecelle）の最初の巻の施行", "6475461c"], "d": ["イスラーム法の債務・物権の分野を近代的な法典の技法でまとめたメジェッレは、最初のイスラーム民法典とみなされる。ジェヴデト・パシャを長とする委員会は、16巻を1876年に完成させた。", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["アブデュルアジズの廃位", "eb7397ea"], "d": ["立憲派の政治家と軍の高官たちは、静かなクーデターでアブデュルアジズを廃位した。五日後の不審な死と、続いて起きたチュラーン事件は、数年続く清算を生んだ。", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["チュラーン襲撃（アリ・スアヴィ事件）", "d2a9ac87"], "d": ["ジャーナリストのアリ・スアヴィは、ムラト5世を再び即位させるためにチュラーンを襲撃した。襲撃は血なまぐさく鎮圧され、アブデュルハミト体制は警備の環を恒久的に強化した。", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["レジ管理局の設立（煙草専売）", "bad9b030"], "d": ["煙草の収入は、デュユーン・ウムーミイェの下にある外国資本のレジ会社に譲渡された。農民と監視人（コルジュ）の間の「レジ密輸」をめぐる衝突は数十年続いた。同じ日に失われたその他の集落：Zeyla。", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["皇帝ヴィルヘルム2世のイスタンブルとエルサレムの訪問", "2988cd06"], "d": ["ドイツ皇帝の二度目の訪問は、オスマン＝ドイツの接近を固めた。バグダード鉄道の利権への道が開かれ、ダマスクスで「三億人のムスリムの友」の演説が行われた。", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["ヒジャーズ鉄道のメディナへの到達", "95009b9c"], "d": ["ムスリムの寄付と国内の工学のみで築かれた1464 kmの路線がメディナに達した。巡礼の旅は数週間から数日に短縮された。アブデュルハミト2世の時代の最大のインフラの事業である。", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["3月31日事件", "1d7c2bb2"], "d": ["立憲政に反対する大規模な蜂起はイスタンブルを掌握した。テッサロニキから来た行動軍が反乱を鎮圧し、アブデュルハミト2世は廃位された。", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["エディルネ包囲の開始", "234d9b28"], "d": ["シュクリュ・パシャの五か月に及ぶ防衛は、バルカンの破局の中の抵抗の叙事詩となった。都市は飢えにより陥落し、1913年7月に取り戻された。", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["バーブ・アーリー襲撃", "b304d02d"], "d": ["エディルネの引き渡しの準備をしていた政府は、統一派の武装襲撃により倒された。陸軍大臣ナーズム・パシャは殺された。統一と進歩委員会の完全な支配の時代が始まった。", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["レバノン山ムタサッルフ領の廃止", "b5639051"], "d": ["1861年の組織規程（Reglement Organique）によって設けられ、1864年に更新された国際的な議定書に基づく自治のムタサッルフ領の体制は、第一次世界大戦中にオスマン国家によって一方的に破棄された。内務省は地域に直接ムスリムのムタサッルフを任命し始めた。1861〜1915年の間に八人のムタサッルフが務めた自治の時代は、こうして閉じた。", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["王子たちの間での国の分割", "82f26bfb"], "d": ["アンカラの敗走の後、スレイマン・チェレビはルメリアに渡ってエディルネでスルタン位を宣言した。イーサー・チェレビはブルサを、チェレビ・メフメトはアマスヤ＝トカト＝シヴァスの地域を保った。地図ではこの三つの分け前は別々の色で示される。", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["ゲリボル協定：ミシヴリまでの黒海沿岸がビザンツに譲られる", "a4164eca"], "d": ["アンカラの敗走の後ルメリアで持ちこたえようとしたエミール・スレイマンは、ゲリボルでビザンツ皇帝マヌエルと協定に調印した。カルタル、ペンディク、ゲブゼといくつかの島、ルメリアのテッサロニキとテッサリア、黒海ではミシヴリ（Misivri）まで延びる沿岸の帯をビザンツに譲り、ビザンツがオスマン朝に支払っていた税も廃止された。ストランジャ沿岸のアフトポル、イーネアダ、レゾヴォはこうして二十一年間ビザンツの統治下に残った。ムラト2世は1424年の和平でこれらの地の多くを取り戻した。", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["イルドゥルム・バヤジトの捕囚中の死", "7e968d83"], "d": ["ティムールの手で捕らわれていたスルタンはアクシェヒルで崩御した。遺体はブルサに運ばれて埋葬された。その死は、王子たちの間の王位争いを後戻りできないものとした。", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["ゲリボル協定 — ビザンツへの譲歩", "dfacbd00"], "d": ["ルメリアでの立場を確保しようとしたスレイマン・チェレビは、ビザンツとラテン人の諸国と協定を結んで、テッサロニキ、マルマラ沿岸、いくつかの島を返還し、貢納の支払いさえ受け入れた。", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["ウルバトの衝突 — イーサー・チェレビの敗北", "500c5d24"], "d": ["ブルサを保持していたイーサー・チェレビは、弟メフメトにウルバトで敗れた。何度かの立て直しの試みも成果を挙げなかった。", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["イーサー・チェレビの消滅", "0effa11e"], "d": ["スレイマン・チェレビの支援で何度かアナトリアに戻ったイーサー・チェレビは、最後の敗北の後に姿を消した。その分け前はチェレビ・メフメトに移り、地図ではメフメトの領域が西に広がった。", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["ムーサー・チェレビがワラキアに渡る", "8441267a"], "d": ["スレイマン・チェレビに対してブルサとアンカラを失いトカト＝アマスヤに退いたチェレビ・メフメトは、弟ムーサーにルメリアへ行くよう促した。ムーサーはワラキアのヴォイヴォダ、ミルチャの招きを受け入れて海路でワラキアに達した。ここからスレイマンを二つの戦線の間に挟む闘争に踏み出すことになる。", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["チェレビ・メフメトがブルサとアンカラを再び取る — アナトリアの分け前がスレイマン・チェレビから離れる", "bfb69f12"], "d": ["ムーサー・チェレビのルメリアでの成功（ヤンボル、1410年2月13日）を受けて、アナトリアにいたエミール・スレイマン・チェレビはルメリアに渡った。スレイマンのアナトリアからの離脱の後、メフメト・チェレビはアンカラを含むブルサ周辺を再び掌握し、即位の印としてヒジュラ暦813年の貨幣を鋳造させた。地図ではマルマラのアナトリア側は、エミール・スレイマンの分け前からチェレビ・メフメトの色に移る。", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["コスミディオンの戦い", "0efc2caa"], "d": ["ビザンツの支援を受けてイスタンブルの城壁の前で行われた戦いで、スレイマン・チェレビは弟ムーサーを破ったが、ルメリアにおける彼への支持はすでに急速に失われ始めていた。同じ日に失われたその他の集落：エラソナ（Elassona）、アイドス（Aytos）、ボラユル（地図上でルメリアのムーサーからスレイマンへ移った地）。", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["ムーサー・チェレビのコンスタンティノープル包囲", "4932f586"], "d": ["スレイマンを支援したビザンツを罰しようとしたムーサー・チェレビは、コンスタンティノープルを包囲した。この包囲はビザンツをチェレビ・メフメトとの同盟へと押しやった。", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["エミール・スレイマンの死 — ムーサーがルメリアを支配", "325c1549"], "d": ["エディルネから逃げる途中で捕らえられたスレイマン・チェレビは殺された。ルメリアの全体はムーサー・チェレビの手に渡った。地図ではルメリアは青色から紫色に変わる。", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["チャムルルの戦い — 統一の再建", "0b23173e"], "d": ["ビザンツ、セルビア専制公国、ルメリアの諸侯の支援を得たチェレビ・メフメトは、弟ムーサーをチャムルルで決定的に破った。ムーサーは逃走中に殺された。ムーサーの手にあったルメリアはエディルネとともにメフメトに移り、メフメト・チェレビはエディルネで自らをオスマン国家の唯一の君主と宣言した。十一年続いた空位時代は終わり、地図上の王子たちの分け前は一つの体に統合された。", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["ウィーン遠征の決定 — ヴァシュヴァール和約は更新されず、目標はジェールからウィーンに変更された", "1bf278f2"], "d": ["皇帝レオポルト1世はまだ期限の切れていないヴァシュヴァール条約の更新を望み、メフメト4世も和平に傾いているように見えた。しかし大宰相メルズィフォンル・カラ・ムスタファ・パシャは、中部ハンガリー王に宣言させたテケリ・イムレの不満を理由に和約を更新させなかった。ヴァーニー・メフメト・エフェンディをはじめとする説教師を動かして、スルタンを戦争に説得した。行われた協議で、スルタンはベオグラードに留まり、総司令官はジェール（Yanıkkale）を取るべく進むことが決められた。しかしセーケシュフェヘールヴァールでの協議で、クリミア・ハンのムラト・ギレイとブダ総督ウズン・イブラヒム・パシャの反対にもかかわらず、目標はウィーンの包囲に変更された。", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["第2次ウィーン包囲の開始 — 軍がウィーンの前に", "bb542e49"], "d": ["大宰相カラ・ムスタファ・パシャの指揮するオスマン軍は、1683年7月14日にウィーンの前に到着した。皇帝レオポルト1世は都市の守備をシュターレンベルクに任せてオーストリアの内地に退いた。最初のものとは異なり、直接ウィーンを標的として準備されたこの二度目の包囲は、9月12日まで続くことになった。", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["パルカーニの敗走とエステルゴムの喪失", "a7366740"], "d": ["ウィーンから退いた軍はパルカーニ（Parkan）で二度目の敗走を喫した。続いてハンガリーの要衝の城塞エステルゴムが陥落した。撤退は崩壊へと変わり始めた。", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["メルズィフォンル・カラ・ムスタファ・パシャの処刑", "ce8b10ac"], "d": ["ウィーンの敗走の責任者とされた大宰相はベオグラードで絞殺された。しかしその処刑は戦線を立て直しもせず、揺らいだ国家の威信を取り戻しもしなかった。", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["神聖同盟の結成", "060280d0"], "d": ["教皇庁の主導で、オーストリア、ポーランド、ヴェネツィアの間でオスマン朝に対する神聖同盟（ムカッデス・イッティファーク）が結成された。1686年にはロシアも加わった。こうして帝国は十六年続く多戦線の戦争に入った。", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["第1次ブダ防衛", "ccc43630"], "d": ["神聖同盟軍の最初のブダ包囲は、四か月続いた城塞の粘り強い防衛によって退けられた。しかしハンガリーの城塞は一つまた一つと落ち続けていた。", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["ノヴェー・ザームキの喪失", "689ab78c"], "d": ["二十二年間オスマン朝の手にあり、ヨーロッパで諺となったノヴェー・ザームキ城塞が陥落した。上ハンガリーにおけるオスマン朝の存在は解体した。", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["テケリのヴァラドでの逮捕 — 中部ハンガリー王国は解体、上ハンガリーの城塞は降伏", "1741aaaf"], "d": ["ウィーンの敗走の後、オスマン朝はテケリも戦争と敗北をもたらした者の一人とみなし始めていた。1685年10月15日、総司令官メレク・イブラヒム・パシャの命令によりヴァラドのベイレルベイ、アフメト・パシャは、援軍に来たテケリを捕らえさせた。彼をハプスブルクに引き渡すことでより良い和平の条件を得られると期待された。逮捕の知らせが広がると、妻ズリーニ・イロナが守るムンカーチを除き、中部ハンガリー王国のすべての城塞と都市がハプスブルクに降伏した。クルツ（反ハプスブルク）兵の多くはハプスブルク軍に移った。テケリが1686年1月2日にベオグラードで釈放されたとき、王国はもはや消滅していた。", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["ブダの喪失 — 145年続いたハンガリーの首都", "70800e2b"], "d": ["七十八日間続いた包囲の末にブダは陥落し、最後のベイレルベイ、アブドゥッラフマーン・アブディー・パシャは城壁で殉教した。1541年からオスマン朝の統治下にあった都市の喪失は、ハンガリーの喪失の象徴とされる。同じ日に失われたその他の集落：Peşte。", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["第2次モハーチ（ハルシャーニ）の敗走 — トランシルヴァニアとモハーチの喪失", "a7922681"], "d": ["1526年に大勝利を収めた平野で、今度は大敗を喫した。軍は崩れ、反乱した兵士たちは大宰相を罷免させた。敗北はトランシルヴァニアの喪失をも招いた。", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["アテネの喪失とパルテノンの爆発", "b6691730"], "d": ["ヴェネツィアの砲兵が放った榴弾が、オスマン朝が火薬庫として用いていたパルテノンを爆破した。二千年の神殿は廃墟となった。都市はヴェネツィアの手に渡った（1688年に取り戻されることになる）。", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["メフメト4世の廃位とスレイマン2世の即位", "9f53037c"], "d": ["戦線の惨事と軍の反乱を受け、39年の治世の末にメフメト4世は廃位された。代わりに四十年間籠（カフェス）に置かれていた弟のスレイマン2世が据えられた。", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["ベオグラードの最初の喪失 — 神聖同盟の包囲", "c6b9b19a"], "d": ["1521年からオスマン朝の手にあったベオグラードは神聖同盟軍に降伏した。セルビアの門は敵に開かれ、危険はニシュ＝ソフィアの線に迫った。同じ日にアトラスでオスマン朝からハプスブルクに移ったその他の集落：Hisarcık (Grocka) — ベオグラードの兄貴分中心地の連鎖に従う（TDV belgrad；申告付きの近似）。", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["バーデンがポジャレヴァツの前でモラヴァ川を渡る — ポジャレヴァツがオーストリアの手に落ちる", "bcf3fc59"], "d": ["辺境伯ルートヴィヒ・フォン・バーデンは1689年8月にポジャレヴァツでモラヴァ川を渡ってニシュの方向へ進んだ。都市は1690年の夏までオーストリアの手に残った（TDV suleyman-ii は1690年にポジャレヴァツが取り戻されたと述べる）。日付と Röder の読みは、この作業では再確認されていない。", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["ニシュの喪失 — ハプスブルク（ハンガリー王冠）の進出、最も危機的な年", "c5e27b3f"], "d": ["ハプスブルク（ハンガリー王冠）の進出はニシュもオスマン朝の統治から奪った。襲撃はスコピエとプリシュティナにまで及んだ。ヴィディンはこの後、1689年10月に陥落した（別項）。戦争の最も暗い年に、国家は首都さえ脅威にさらされていると感じた。", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["オルショヴァとフェトヒュルイスラームがオーストリアの守備隊に入る", "ee8dd875"], "d": ["ヴィディンが戦わずして取られた（1689年10月、TDV vidin）後、バーデンは1689年10月25日にオルショヴァとフェトヒュルイスラームを修復して守備隊を置いた。オルショヴァは1690年の秋までオーストリアに残った。日付は Bánlaky/Röder に基づき、この作業では再確認されていない。", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["ニシュが再びオスマン朝に", "0c4f44eb"], "d": ["ファーズル・ムスタファ・パシャは1690年7月に遠征に出た。シェヒルキョイ（ピロト）、ポジャレヴァツ、ギュヴェルジンリク（ゴルバツ）が取られた後、包囲されたニシュは1690年9月27日にオスマン朝の手に渡った（TDV semendire）。同じころヴィディンも取り戻されていた。同じ日にアトラスでハプスブルクからオスマン朝に戻ったその他の集落：Yagodina (Jagodina) と Ürküp (Prokuplje) — 地点ごとの日が見つからないため、ニシュの日が取られた（TDV semendire；申告付きの近似；Röder 1842 は宰相が9月8日〜24日にヤゴディナを通過したと記すが、矛盾は解消されていない）。", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["スメデレヴォでオーストリア軍が降伏", "90da20c4"], "d": ["ニシュが1690年9月27日に取られた後、四日間の包囲でスメデレヴォのオーストリア軍が降伏した（TDV semendire）。Bánlaky/Röder は9月24日とするが、史料は矛盾しており、TDVが採られた。", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["ベオグラードの奪回", "ab435838"], "d": ["大宰相キョプリュリュザーデ・ファーズル・ムスタファ・パシャは1690年10月8日にベオグラードをオーストリアから取り戻した。1688年に失われた都市はこうしてオスマン朝に戻った（TDV suleyman-ii）。同じ日にアトラスでハプスブルクからオスマン朝に戻ったその他の集落：Hisarcık (Grocka) — ベオグラードの兄貴分中心地の連鎖に従う（TDV suleyman-ii；申告付きの近似）。", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["スランカメンの敗走 — ファーズル・ムスタファ・パシャの殉教", "10d626f1"], "d": ["世紀で最も血なまぐさい会戦の一つで、大宰相は額を撃ち抜かれて殉教した。軍は崩れた。立て直しの望みはこの戦いとともに消えた。", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["キオス島の喪失", "07c084f8"], "d": ["ヴェネツィア艦隊はキオスを占領した。エーゲ海におけるオスマン朝の支配は脅威にさらされた。島は翌年に取り戻されることになる。", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["ムスタファ2世の自ら出征する決定", "61c3ba9c"], "d": ["新しいスルタンは、祖先の道を歩んで軍の先頭に立って出征すると宣言した。この決定は軍の士気を生み、二年続く親征の時代を始めた。", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["キオスの奪回", "6b496fca"], "d": ["オイヌセス諸島の海戦でヴェネツィア艦隊を破ったメゾモルト・フセイン・パシャは、キオスを取り戻した。オスマン海軍における短い復活の兆しとなった。", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["ルゴイの勝利 — ムスタファ2世の最初のオーストリア遠征", "d5ee9b34"], "d": ["スルタンが自ら参加した最初の遠征で、リポヴァが取り戻され、ルゴイでオーストリア軍が敗れた。長年続いた敗北の連鎖で、最初の切れ目が生じた。アトラスはカランシェベシュ（Caransebeş）もこの遠征でハプスブルクからオスマン朝に戻ったものとみなす。史料は1695年9月とだけ記し（TDV mustafa-ii）、アトラスの日はルゴイの記録から取られた（申告付きの近似）。", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["アゾフ城塞の喪失", "2b78b5cd"], "d": ["黒海への進出を目指すピョートル1世は、二度目の包囲でアゾフを取った。ロシアは初めてオスマン朝の城塞に恒久的に定着し、海軍力となる道への最初の一歩を踏み出した。", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["ウラシュ（Olaşin）の勝利", "02ac9ca8"], "d": ["スルタンの二度目の遠征でドナウ河畔で収められた勝利は、オーストリアのティミショアラ奪取の計画を挫いた。しかし戦争の全体的な均衡は変えなかった。", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["ゼンタの敗走 — 戦争の行方が決まる", "475c4a7b"], "d": ["軍はティサ川を渡る途中でオイゲン公の急襲を受けた。川の両岸に分断された部隊は数時間で壊滅し、大宰相エルマス・メフメト・パシャをはじめ数千の兵と政治家が死んだ。オスマン史上最も重い敗走の一つであるゼンタは、和平の席を避けられないものとした。", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["カルロヴィッツ和平交渉の開始", "1f395cf3"], "d": ["イギリスとオランダの仲介で始まった交渉で、オスマン朝の代表団は初めて「uti possidetis」（保有しているものは保持される）の原則を受け入れざるを得なかった。七十二回の会議に及んだ交渉は、近代オスマン外交の誕生とみなされる。", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["カヴァラのメフメト・アリーがエジプトに上陸", "514c943f"], "d": ["フランスの占領下にあるエジプトを取り戻すために派遣されたオスマン軍の中には、カヴァラで集められた志願兵の部隊もあった。三十代のメフメト・アリーはこの部隊の副指揮官であった。エジプトには総督としてではなく、一中隊の将校として足を踏み入れた。", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["アルバニア兵がエジプト総督を倒す", "c76a0ec2"], "d": ["俸給の支払われなかったアルバニア人の部隊が蜂起し、総督フスレヴ・パシャを城塞から逃げざるを得なくさせた。フランス軍の撤退で生じた空白の中で、マムルークの諸侯、アルバニア人の軍団、バーブ・アーリーの任命する総督たちは三つ巴の闘争に入った。メフメト・アリーはこの三角の中で均衡を取って頭角を現した。同じ日に失われたその他の集落：Tâif。", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["カイロのウラマーがメフメト・アリーを総督と宣言", "a16752f2"], "d": ["税の圧力に苦しんだカイロの商工業者とウラマーは、ナキーブ・ル・アシュラーフのウマル・マクラムの指導のもとで蜂起し、総督フルシド・パシャを認めないと表明して、メフメト・アリーを総督の座に就けた。オスマン史において総督が民衆によって選ばれたことは、まれな出来事である。", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["バーブ・アーリーが既成事実を受け入れる：エジプト総督の勅令", "b86736a3"], "d": ["エジプトで自らの候補を押し立てる力のなかったバーブ・アーリーは、メフメト・アリーに宰相の位とともにエジプト総督の勅令を送った。地図ではエジプトはこの日付から従属（薄い色調）の層に移る。法的にはオスマン領だが、事実上はカヴァラ王朝の国である。同じ日に従属の層に移ったその他の集落：Kahire, İskenderiye, Dimyat, Asyut, Asvan, İbrim, Süveyş, Reşîd (Rosetta)。", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["イギリスのフレイザー遠征軍がアレクサンドリアに上陸", "4d6c31be"], "d": ["オスマン朝がフランスに接近したことへの対抗措置として、イギリスはエジプトに上陸部隊を送った。メフメト・アリーはそのとき上エジプトでマムルークと争っていたが、急ぎ戻って防衛を組織した。", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["ロゼッタ（Reşid）の敗走 — イギリス軍の撃退", "3636004c"], "d": ["レシド（ロゼッタ）の町に入ったイギリス軍の部隊は、市街戦で大きな損害を出した。9月には部隊がエジプトから完全に撤退した。この勝利は、メフメト・アリーのエジプトとイスタンブルの両方での威信を固めた。", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["城塞事件：マムルークの諸侯の一掃", "84030b97"], "d": ["ヒジャーズ遠征のために催された式典の行列に招かれたマムルークの諸侯は、カイロ城塞の狭い通路で閉じ込められて排除された。5世紀続いたマムルークの勢力はこうして終わり、エジプトでメフメト・アリーの前に競争相手はいなくなった。", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["ヒジャーズ遠征の開始 — 軍はスエズから海路で、巡礼路から陸路でヤンブーへ進んだ", "1c05c159"], "d": ["1803年からサウード＝ワッハーブ派の支配下にあった両聖都を取り戻すことは、マフムト2世にとって最大の正統性の問題であった。バーブ・アーリーの力が及ばなかったため、任務はエジプト総督に与えられた。メフメト・アリーは十六歳の息子トスンを軍の先頭に立てて送った。", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["ヤンブーの占領 — ヒジャーズ遠征の最初の沿岸拠点", "179bc78d"], "d": ["スエズから新造の船で出発した二千人ほどのアルバニア歩兵は、1811年10月にヤンブー近くに上陸した。町は二日間の弱い抵抗の後に降伏した。トスンの指揮する騎兵は巡礼路を陸路でたどり、アカバとワジュフ経由で二週間後になってようやくヤンブーに達した。ヤンブーは、メディナとメッカへ進軍するエジプト軍のヒジャーズでの最初の拠点となった。", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["サフラ・ジェディーダの隘路での最初の敗走", "99ef804d"], "d": ["狭い山の隘路で待ち伏せされたエジプトの先鋒部隊は壊滅した。この敗北は遠征の戦術上の教訓となった。ベドウィンの部族の支持を得ずにヒジャーズを進むことは不可能であると分かった。", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["メディナの奪回", "6f6a5d55"], "d": ["長い包囲の後、メディナは降伏した。預言者の都市の奪回はイスタンブルで礼砲の祝賀で祝われ、メフメト・アリーには褒賞としてジェッダ総督の地位も与えられた。", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["メッカの奪回 — 巡礼路の開通", "3d6d66a0"], "d": ["メッカに入ったエジプト軍は、カアバで再びオスマン朝のスルタンの名でフトバを読ませた。十年間途絶えていた巡礼団が再び出発できるようになった。地図ではヒジャーズはオスマン朝の支配に戻るが、統治がカイロにあるため従属の色調で示される。同じ日に従属の統治に移ったその他の地：Cidde。", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["ターイフの奪回 — ヒジャーズ遠征の完了", "6315fb31"], "d": ["メディナ（1812年12月）とメッカ（1813年1月）の後、トスン・パシャの指揮するエジプト軍は最後にターイフをワッハーブ派から取り戻した。十年続いたサウード家の支配は終わり、ヒジャーズの三つの聖なる中心も再びオスマン＝エジプトの管理下に入った。", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["メフメト・アリー自らがヒジャーズに渡る", "fda0ea2d"], "d": ["遠征がゆっくり進んでいるのを見た総督は、統治を直接自らの手に取った。部族の長たちと交渉して、サウード側の戦線を内側から崩そうと努めた。エジプトの紅海貿易における取り分も、この遠征で増えた。", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["ビセルの戦い：サウード側の軍が敗走", "9c9ab91f"], "d": ["会戦で大敗を喫したサウード家は内陸に退いた。結ばれた休戦は長続きしなかった。二年後に作戦はネジドの中心に移されることになった。アトラスはこの勝利の後、ターイフ東方のトゥラバとフルマをサウード家の手から離れたものとみなす（出来事の出典はLorimer, Gazetteer。地点ごとの証言と1月13日の日付は申告付きの近似である）。", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["イブラヒム・パシャのネジド遠征の出発", "d5ed80d1"], "d": ["弟トスンの死により指揮を受け継いだイブラヒム・パシャは、砂漠で二年続く過酷な行軍に乗り出した。井戸から井戸へと進む軍は、部族を一つずつ排除して、サウード家の首都に迫った。", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["ディルイーヤの陥落 — 第一次サウード国家の終わり", "aa96206d"], "d": ["六か月続いた包囲の後、ディルイーヤは降伏して破壊された。首長アブドゥッラー・ブン・サウードはイスタンブルに送られて処刑された。オスマン朝の旗がアラビア内陸のこれほど奥深くまで及んだのは初めてであった。ネジドの守備隊は1824年まで残った。同じ日に加わったその他の地：Dir'iye (Necid)。", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["スーダン遠征の開始", "b1fc6905"], "d": ["メフメト・アリーの目的は三重であった。軍に兵を集めること、センナールの金に到達すること、逃れたマムルークの残党を滅ぼすことである。息子イスマーイール・パシャの指揮する部隊はナイル川をたどって南に下った。", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["ドンゴラが暴力なくエジプト軍の手に渡る（マムルーク勢は1820年6月に撤退していた）", "bc5942c0"], "d": ["ナイル川の大湾曲部にあるドンゴラは、マムルーク勢が1820年6月に放棄したのち、暴力なくイスマーイール・パシャ率いるエジプト軍の手に渡った。地図上でスーダンはこの日から従属層に現れる。征服者はカイロであり、統治者もカイロとなる。", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["ジャバル・アッダイカの戦い――シャーイキーヤ連合がエジプト軍に決定的に敗れる", "befc9539"], "d": ["クルティでの最初の衝突から1か月後、ムハンマド・アリー・パシャの子イスマーイール・パシャの軍は、ジャバル・アッダイカ付近での第二の決定的な戦いでシャーイキーヤを破った。シャーイキーヤの首長マック・スバイルは降伏し、マック・シャーウィーシュは抵抗を続けた。以後、ナイル川湾曲部におけるエジプトの支配は恒久的なものとなった。", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["センナール（フンジュ）王国の降伏", "3cac7dd2"], "d": ["3世紀続いたフンジュ朝は戦わずして降伏した。同じ年にナイル川の二つの支流の合流点に築かれた陣営は、短期間のうちにスーダンの行政の中心ハルツームに変わった。同じ日に加わったその他の地：Sennar。", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["コルドファンの占領", "06440602"], "d": ["西に送られた第二の部隊は、バーラ（Bâra）でダルフールの軍を破り、ヌフードの周辺とともにコルドファンを取った。エジプトのスーダン支配は、こうしてナイル渓谷から西の草原に広がった。", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["クレタにエジプト軍が上陸", "835aee90"], "d": ["ギリシア人の蜂起がクレタに波及すると、バーブ・アーリーは島にエジプト軍が送られることを求めた。メフメト・アリーの島での影響力はこの介入によって始まり、八年後にクレタ総督の地位が彼に与えられることで結実した。", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["シェンディでのイスマーイール・パシャの殺害", "223860c9"], "d": ["重い税と兵の要求に憤った地方の首長ニミルは、宿営していた家に火を放ってイスマーイール・パシャとその随行者を焼いた。報復の遠征は地域を血の海に変え、スーダンの統治はこの後、厳しさの上に築かれた。", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["マフムト2世がモレアのためメフメト・アリーに支援を要請", "03594a42"], "d": ["イェニチェリの軍が三年かけても鎮圧できなかったモレアの蜂起のために、スルタンはヨーロッパ式に訓練されたエジプト軍に頼った。見返りにモレア総督の地位とクレタが約束された。この要請は、帝国が自らの州に頼らざるを得なくなった最初の公然たる告白であった。", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["イブラヒム・パシャがモドンに上陸", "9c993dba"], "d": ["エジプト艦隊に護られた上陸部隊は、モレアの南西端に足を踏み入れた。正規歩兵と野砲を備えたこの軍は、蜂起した武装集団に対して短期間のうちに優位を確立した。", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["トリポリツァの奪回 — モレアの中心が陥落", "8a478c11"], "d": ["蜂起の統治の中心トリポリツァの陥落により、モレアの大部分は再び管理下に入った。地図では半島は、エジプト軍の手にあるため従属の色調で現れる。", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["ミソロンギ（Mesolongi）の陥落", "07257f87"], "d": ["一年続いた包囲の後、都市は取られた。しかし防衛がヨーロッパの新聞に生んだ反響は、ギリシアの大義への共感を頂点に押し上げ、列強の介入の土壌を整えた。", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["アテネのアクロポリスの降伏", "3b19f946"], "d": ["アクロポリスの陥落により、ギリシアの蜂起は軍事的にはほぼ終わっていた。まさにこの時点で、問題は内乱ではなくなり、ヨーロッパ外交の主題となった。", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["ロンドン条約：三国がギリシアの自治を強要", "7ce46fd8"], "d": ["イギリス、フランス、ロシアは、オスマン朝とギリシア人の間に休戦と自治の条件を受け入れさせるため共同で行動することを決め、拒まれた場合は艦隊が介入すると通告した。バーブ・アーリーは提案を拒んだ。", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["アレクサンドリア協定：エジプトのモレアからの撤退の決定", "cc978f37"], "d": ["ナヴァリノで艦隊を失ったメフメト・アリーは、イスタンブルに諮らずイギリスの提督と直接合意して、軍をモレアから撤退させることを受け入れた。総督が列強と単独で協定を結ぶことは、将来の危機の前触れであった。", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["エジプト軍がモレアから撤退", "8fb742dd"], "d": ["最後の部隊が船に乗せられた。半島は事実上失われ、1830年のロンドン議定書により独立ギリシアの核となった。メフメト・アリーは約束されたモレア総督の地位を得られず、その代わりに大艦隊と軍を失っていた。同じ日に失われたその他の集落：Modon, Koron。", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["クレタの統治がメフメト・アリーに委ねられる", "7f76396d"], "d": ["モレアの喪失の埋め合わせとして、クレタ総督の地位がメフメト・アリーに与えられた。島は十年間カイロから統治された。地図ではその間、従属の色調で現れる。同じ日に加わったその他の地：Kandiye (Girit)。", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["イブラヒム・パシャがシリアに入る — 第一次危機の開始", "1a5cc386"], "d": ["口実は、エジプトから逃れた農民を引き渡さないアッコの総督であった。真の理由は、メフメト・アリーがシリアの木材、港、人的資源を必要としたことである。軍はシナイを越えて、パレスチナ沿岸を急速に掌握した。", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["アッコ包囲の開始", "b211d96d"], "d": ["1799年にナポレオンを止めた城塞は、六か月抵抗した。包囲は、エジプト軍の近代的な砲兵の最初の大きな試練であった。", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["アッコの陥落", "0f47917b"], "d": ["城壁を砕く砲台が突破口を開くと、城塞は取られた。シリアの門は開かれた。バーブ・アーリーは同じころ、メフメト・アリーを反逆者と宣言し、総督の地位を廃した。", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["ダマスクスの降伏", "48da3b62"], "d": ["都市は戦闘なく降伏した。イブラヒム・パシャは税制と非ムスリムに認められる平等を宣言して、地元の支持を得ようとした。同じ政策が数年後に彼に対する反乱の原因にもなった。同じころに加わったその他の地：Beyrut, Trablusşam, Sayda。", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["ホムスの戦い", "867810ee"], "d": ["シリアを救うために送られたオスマン軍は、開けた地で敗走した。イェニチェリの廃止から六年後に創られた新しい軍が、まだ準備できていなかったことが分かった。", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["アレッポの占領", "9c0ead76"], "d": ["北シリアの通商・統治の中心も陥落した。こうしてエジプト軍はトロス山脈の麓に迫り、アナトリアの門にある隘路へ向かった。", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["ベレン（Beylan）の隘路の敗走 — チュクロヴァの開放", "4bae872b"], "d": ["アマヌス山脈の狭い隘路で防衛線が破られた。アンタキヤ、アダナ、タルススがエジプト軍に移った（マラシュの占領はTDVによれば1833年であり、別項）。地図ではチュクロヴァは従属の色調に変わる。アナトリアの内陸に至る道はもはや無防備であった。", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["ギュレク隘路の陥落 — イチェルの沿岸（メルスィン、シリフケ）がエジプトの管理下に", "d9049b5b"], "d": ["トロス山脈のチュクロヴァの門であるギュレク隘路は、エジプト軍の手に渡った。イブラヒム・パシャはイチェル・サンジャクに自らのミュテセッリムを任命し、沿岸のすべての港（船着き場）はエジプトの管理下に入った。地図ではメルスィンとシリフケはこの日から（下限。任命の日は史料にない）エジプトに属するものとして示される。キュタヒヤの決定ではアダナのムハッスルルクのみが言及されるため、この管理はアナトリアからの撤退とともに終わる。", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["コンヤ・エレーリがエジプトの占領下に — コンヤ＝アダナの道のトロスの入口", "fb908900"], "d": ["ギュレク隘路を越えたエジプト軍のコンヤに至る道上のエレーリは、1832年にイブラヒム・パシャの占領下に入り、1833年のキュタヒヤの取り決めで撤退されると再びカラマン州に結びつけられた。地図ではアダナとコンヤの間の占領線の、史料に基づく中間点である。ウルクシュラとカラプナルについては都市レベルの証言が見つからなかった。", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["エジプト軍がコンヤに入る", "13952a2d"], "d": ["トロス山脈を越えた軍は中央アナトリアに達した。オスマン朝の総督の軍が、初めて帝国の中核の地を進んでいた。同じ日に加わったその他の地：Karaman。", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["コンヤの会戦：大宰相が捕虜に", "ec82cc9a"], "d": ["霧の中で崩れたオスマン軍は大敗を喫し、大宰相レシト・メフメト・パシャは捕らえられた。国家の中央軍はもはやなく、イスタンブルとエジプト軍の間に立ちはだかる力は残っていなかった。", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["マラシュがエジプトの占領を受ける", "f558e383"], "d": ["TDVによれば、マラシュは1833年にカヴァラのイブラヒム・パシャの占領を受け、十九か月近く彼の統治下に残った。マラシュはキュタヒヤの取り決めの州境の外に残ったため、この統治は法的なものではなく事実上のものである。", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["カラヒサル・サーヒブ（アフヨン）がエジプトの占領を受ける — コンヤ＝キュタヒヤの道", "ae0c2c78"], "d": ["コンヤの会戦の後キュタヒヤに進んだエジプト軍の進路上にあるカラヒサル・サーヒブは、1833年にしばらくイブラヒム・パシャの手に残った。地図ではコンヤとキュタヒヤの間の占領線の、史料に基づく中間点である。アクシェヒル、ウルグン、イスハクルについては都市レベルの証言が見つからなかったため、これらはオスマン朝の色のままである。", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["エジプト軍がキュタヒヤに到達", "214f8df6"], "d": ["イブラヒム・パシャはイスタンブルから三日の道のりのキュタヒヤで止まった。それ以上進まなかったのは軍事的ではなく政治的な理由であった。ロシアの介入とヨーロッパの反応が計算に入れられていた。", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["ロシア艦隊がビュユクデレの前に", "6f836d61"], "d": ["イギリスとフランスから支援を得られなかったマフムト2世は、昨日までの敵ロシアに頼った。スルタンの「溺れる者は蛇にもすがる」という言葉で語られるこの決定は、ロシア兵が海峡に現れることに終わり、ヨーロッパに警鐘を鳴らさせた。", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["キュタヒヤの合意（口頭）— シリアとアダナがカヴァラ家に", "25fe9985"], "d": ["バーブ・アーリーはエジプト、クレタ、ヒジャーズに加えて、ダマスクス、アレッポ、トリポリ・シャーム、サイダの総督の地位をメフメト・アリーに、アダナのムハッスルルクをイブラヒム・パシャに委ねた。見返りに軍はトロス山脈の南に退いた。これは条約ではなく、スルタンが一人の総督に与える勅令の形であった — 問題は解決されず、先送りされたのである。", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["エジプト軍のアナトリアからの撤退がギュレクで完了", "a53ac2a3"], "d": ["キュタヒヤの取り決めの後、エジプト軍はアナトリアを引き払った。6月中旬ごろに軍の全体がギュレク隘路からチュクロヴァに渡った。イチェルの沿岸（メルスィン、シリフケ）は再びオスマン朝の統治に戻る。アダナのムハッスルルクとシリアはエジプトに残る。", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["ヒュンキャール・イスケレスィ条約", "da741d5c"], "d": ["ロシアと八年間の相互防衛同盟が調印された。秘密条項によれば、ロシアが攻撃された場合、オスマン朝は海峡を軍艦に対して閉ざすこととされた。これはオスマン外交の最も議論のある決定の一つとなり、イギリスをエジプト問題で積極的にさせた。", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["パレスチナ＝ナーブルスの反乱、エジプトの統治に対して", "4fe43e27"], "d": ["徴兵、武器の収集、新税は、パレスチナで広範な蜂起を招いた。反乱は厳しく鎮圧された。エジプトの統治の地元住民の間での支持は急速に失われた。", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["マラシュのエジプト統治の終わり（おおよそ）", "bb46ca42"], "d": ["TDVの「十九か月近く」という期間を1833年の占領から数えると、エジプトの統治は1834年の夏ごろに終わる。キュチュカリオウル家のムスタファ・ベイが1834年にエジプト軍に抗し切れずマラシュの方面に退いたことも、マラシュがそのときエジプトの管理外の避難所であったことを示している。", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["ドルーズ山の蜂起", "12e74626"], "d": ["ドルーズ派の地域で起きた抵抗は二年続いた。シリアに積もった不満は、1840年に連合艦隊が沿岸に上陸したとき、エジプト軍の背後を空にすることになる。", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["メフメト・アリーが独立の意図を表明", "48633bbd"], "d": ["総督は列強の領事に、エジプトとシリアの独立を宣言することを考えていると明らかにした。イギリスはこれに断固として反対した。地中海に強力でフランスに近い国家が生まれることは、インドへの道を脅かすからである。", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["オスマン軍がユーフラテス川を渡る", "9af1ea69"], "d": ["マフムト2世は、キュタヒヤで失ったものを取り戻すため、軍をシリア国境に向けた。軍に顧問として加わっていたプロイセンの将校モルトケは、陣地の選択と早期の攻勢に異議を唱えたが、その異議は聞き入れられなかった。", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["ニジプの戦い — オスマン軍の壊滅", "156b3cdf"], "d": ["配置の悪いオスマン軍は、数時間のうちに敗走した。敗北の知らせがイスタンブルに届く前にスルタンは死んだ。国家は数日のうちに軍を、君主を、続いて艦隊を失うことになる。", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["マフムト2世の死", "07eccfff"], "d": ["三十一年の治世のあいだにイェニチェリを廃し、中央の統治を再建したスルタンは、最大の敵を破ることなく崩御した。病気には的確な診断が下されなかった。その死は、イェニチェリの精神が動き出すことへの恐れから、都市で軍事上の措置が取られるまで、6月30日まで伏せられた。", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["アブデュルメジトの即位とマフムト2世の葬儀", "d0f3d2cc"], "d": ["父の死により十六歳のアブデュルメジトが即位した。同じ日にマフムト2世の遺体はトプカプ宮殿に運ばれた。恐れられた混乱は起きず、ムスリムと非ムスリムの広範な民衆が葬列に加わった。", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["艦隊のアレクサンドリアへの引き渡し", "a53e6103"], "d": ["海軍総督アフメト・フェヴズィ・パシャは、大宰相コジャ・フスレヴ・パシャが艦隊をロシアに与えるのではないかと疑い、艦隊をアレクサンドリアに連れて行ってメフメト・アリーに引き渡した。オスマン国家は同じ月のうちに、軍もスルタンも艦隊もない状態になった。", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["列強の共同覚書", "2a3b8316"], "d": ["五か国はバーブ・アーリーに覚書を渡し、エジプト問題で単独で合意しないよう求めた。内政問題はこうして正式に「ヨーロッパの問題」となった。オスマン国家は自らの州について決定する権限を事実上失った。", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["ロンドン条約：四か国がオスマン朝の側に", "a517f775"], "d": ["フランスを除外して調印された条約は、メフメト・アリーに最後通牒を突きつけた。十日以内に受け入れれば、エジプトの世襲の総督の地位と、終身の条件でアッコ、二十日以内に受け入れればエジプトのみ、拒めば何もなし。総督は拒んだ。", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["ベイルート砲撃と連合軍の上陸", "0905ce92"], "d": ["英墺艦隊はベイルートを砲撃した。レバノン山地ではエジプトの統治に対して蜂起した住民に武器が配られた。イブラヒム・パシャのシリアでの支配は、内乱と外部の介入の間で崩れた。", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["ベイルートと沿岸の都市の喪失", "09bdaf23"], "d": ["バールベック方面での戦闘の後、エジプト軍は沿岸から退いた。地図ではレバノンの沿岸は従属の色調から外れて、直接オスマン朝の統治に戻る。", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["アッコが二時間で陥落", "5aec21f0"], "d": ["連合艦隊の砲撃で城塞の火薬庫が爆発し、アッコは数時間のうちに降伏した。八年前にイブラヒム・パシャが六か月かけてしか取れなかった城塞は、海軍砲兵の優位を示した。", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["アレクサンドリア協約", "85cb47b0"], "d": ["メフメト・アリーはシリア、アダナ、クレタ、ヒジャーズを放棄すること、オスマン艦隊を返還すること、スルタンの宗主権を認めることを受け入れた。見返りに、エジプトの世襲の総督の地位が保証された。", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["エジプト軍がシリアとチュクロヴァから撤退", "719a28dc"], "d": ["九年の占領は終わった。イブラヒム・パシャの軍はシナイ経由でエジプトに戻った。地図ではアレッポからガザまで、アダナからクレタまで広がる帯が再び直接オスマン朝の統治に移る。同じ日に失われたその他の集落：Urfa, Maraş, Tarsus, Antakya, Kandiye (Girit), Hama, Şam, Kudüs, Yafa, Nablus。", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["勅令：エジプト総督位がカヴァラ家の世襲に", "87b89ff8"], "d": ["スルタンの勅令は、総督位が王朝の中で父から子へ受け継がれることを認めた。その代わり軍の定員は一万八千に引き下げられ、税はイスタンブルに結びつけられ、貨幣鋳造と条約締結の権限は廃された。エジプトは州のまま残ったが、もはや別の王朝の国であった。ヒジャーズと両聖都の統治はバーブ・アーリーに戻った。同じ日に従属の層から直接の層に戻ったその他の集落：Mekke, Medine, Cidde, Yenbu。", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["ロンドン海峡条約", "0e95a1ea"], "d": ["ヒュンキャール・イスケレスィ条約に代わった条約は、平時には海峡がすべての軍艦に対して閉ざされることを定めた。ロシアが単独で得た特権は、こうしてヨーロッパの共同の保証に変わった。海峡問題は国際的な地位を得た。", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["イブラヒム・パシャが事実上のエジプト総督に", "9e14f5d9"], "d": ["老いて精神の能力を失ったメフメト・アリーに代わって、息子のイブラヒム・パシャが総督の座に就けられた。しかし数か月後の1848年11月に、父より先に死んだ。", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["カヴァラのメフメト・アリー・パシャの死", "871310e0"], "d": ["カヴァラで生まれ、エジプトで王朝を築き、帝国を二度深淵の縁まで追いつめた総督は八十歳で死んだ。彼が築いた王朝は1953年までエジプトを支配した。国家は彼が開けた傷をヨーロッパの介入によって閉じることができたと見て、タンジマートの道を進んだ。", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["スレイマン・ブン・クタルムシュがアイン・サイラムで敗れて死んだ。アンティオキアがアナトリア・セルジューク朝を離れた", "0412dfa1"], "d": ["1084年にアンティオキアをビザンツから取ったスレイマン・ブン・クタルムシュは、シリア・セルジューク朝の君主トゥトゥシュと戦ったアイン・サイラムの戦いで死んだ。都市は大セルジューク朝のスルタン、マリク・シャーの統制下に移り、ヤギ・シヤーンが総督に任命された。", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["マリク・シャーが死んだ。アンティオキアはヤギ・シヤーンとともにシリア・セルジューク朝のトゥトゥシュに従った", "c61da1b4"], "d": ["大セルジューク朝のスルタン、マリク・シャーの死の後、国は後継者の間で分割された。アンティオキア総督ヤギ・シヤーンは、シリアの支配者トゥトゥシュに従った。", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["ニカイアが十字軍に降伏した。セルジューク朝の中心はコンヤに退き、ビザンツは西アナトリアの奪還を始めた", "8a4e90fa"], "d": ["十字軍によるニカイアの包囲の後、都市は1097年6月19日にビザンツに降伏した。セルジューク朝のスルタン、クルチ・アルスラーン1世は中心を内陸のコンヤに退き、ビザンツは西アナトリアの海岸のエフェソスなどの地を取り戻した。", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["クルチ・アルスラーン2世がドリュラエウム(エスキシェヒル)とキュタヒヤをビザンツから取った", "3ddee6c2"], "d": ["ミュリオケファロン(1176年)の後、ビザンツのアナトリア内陸にあるドリュラエウムとキュタヒヤの要塞は、マヌエルの最後の年々、あるいはその死の後に、ヒジュラ暦576年/1180年にクルチ・アルスラーン2世の手に渡った。", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["カラマンオウル・メフメト・ベイがエルメネクのスバシュ職に任命され、イチ・イル地方を統治下に置いた", "6d62be11"], "d": ["カラマンオウル・メフメト・ベイは、ヒジュラ暦675年(1276年)にエルメネクのスバシュ(軍事長官)に任命され、イチ・イル地方を統治下に置いた。エルメネクは、翌年コンヤに進軍することになるカラマン侯国の最初の中心地となった。", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["エルトゥールル・ガーズィーの死とオスマン・ベイの侯国継承 — ソユトとドマニチの遺産", "395fb9fa"], "d": ["TDVによれば、エルトゥールル・ガーズィーはヒジュラ暦680年（1281〜82年）に没した。項は1288年と1289年の日付も与えられていることを記す。オスマン・ベイは、父から征服された都市ではなく、セルジューク朝のスルタンが辺境地帯の最前線に置いたエルトゥールルに与えた二つの割り当てを継承した。ソユトでの冬営地（ユルトルク）とドマニチでの夏営地（ヤイラク）である。つまり侯国は征服の遺産ではなく、二つの牧地の割り当てで事業を始めたのである。地図ではこの二つの地は「征服」ではなく「継承」として示される。", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["シチリアの晩祷 - アンジュー家、シチリア島を失う", "547db635"], "d": ["パレルモで復活祭の月曜日の晩課の時刻に、アンジュー家のシャルル1世の統治に対して勃発した蜂起は、シチリア島をアンジュー家から切り離した。シチリア王国は二つに分かれ、島はアラゴンに向かい、アンジュー家はナポリを中心とする大陸の王国に留まった。同家のアドリア海および地中海の海外領もこの王国に属したままであった。1267年から手中にあったコルフと、1270年代から保持していたドゥラスはナポリ王国の一部として存続し、アルバニア沿岸のヴロラ(アヴロニャ)、カニナ、ヒマラの城塞もナポリ中心の王国に残った(ヴロラの指揮官ジョン・オブ・タクシスは1282年を通じてビザンツに抵抗した。ドゥラス、ヴロラ、カニナはおそらく1285年初めにビザンツに渡った)。一方マルタは、1284年になってようやくアラゴン人の手に落ちた。", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["クラジャヒサル襲撃 — オスマン・ベイの最初の軍事行動", "79b00b14"], "d": ["TDVのオスマン1世の項：「イネギョルの近くの小さなクラジャ城塞を略奪して火を放った（ヒジュラ暦684年／1285年）。」これは、史料で年代を特定できるオスマン・ベイの最初の軍事行動である。恒久的な集落は取られず、城塞は略奪されて焼かれた。したがって征服というより古典的な辺境の襲撃である。侯国の軍事活動の起点とされる。", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["カラジャヒサルの征服 — 最初の都市の獲得とエスキシェヒルの掌握", "178ae619"], "d": ["TDVのオスマン1世の項：オスマン・ベイはヒジュラ暦687年（1288年）に「カラジャヒサルを征服してエスキシェヒルを領有した」。これは侯国の最初の真の都市の獲得であり、伝承によれば、オスマン・ベイはこの成功により辺境のサンジャク・ベイに昇ったという。彼の名による最初の金曜のフトバはカラジャヒサルで読まれ、ここに最初のカーディーが任命されたと伝えられる。TDVのエスキシェヒルの項は、オスマンの伝承が1291年の日付を与えるが、その正確さは疑わしいと述べる。", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["アッカのマムルーク朝への陥落 - 十字軍勢力のシリア沿岸からの一掃:サイダとベイルート", "3ca7a464"], "d": ["長らくエルサレム十字軍王国の中心であったアッカは、マムルーク朝のスルタン、アル=マリク・アル=アシュラフ・ハリールに征服され、十字軍のパレスチナにおける支配は終わった。アッカから退いたテンプル騎士団はサイダに逃れたが、マムルーク軍が近づくと海上の城を捨ててキプロスへ逃れ、同市はその夏のうちにマムルーク朝の手に渡った。1197年から十字軍の手にあったベイルートも、1291年にダマスクス総督サンジャル・アッ=シュジャーイーに奪われた。こうして2世紀にわたる十字軍の存在はシリア・パレスチナ沿岸から消えた。", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["ビレジクとヤルヒサルの夜襲による征服", "f461b0af"], "d": ["TDVのビレジクの項：「ビレジクのテクフルを含む地域の他のテクフルたちはオスマン・ガーズィーに対する暗殺を企てたが、その企てが察知されると、オスマン朝の軍は急襲でヤルヒサルとビレジクを征服した（1299年）。」二つの城塞は一つの作戦で、同じ夜の襲撃で取られた。この年代は、オスマン国家の建国の年とされる転換点である。同じ日に加わったその他の地：İnegöl。", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["コユンヒサル（バフェウス）の戦い — ビザンツ軍に対する最初の大きな勝利", "584a9512"], "d": ["TDVのオスマン1世の項：オスマン・ベイは1302年7月27日にバフェウス（コユンヒサル）でビザンツ軍と戦ってこれを破った。この勝利は、オスマン・ベイを地域の辺境の君主から王朝の創始者の地位に引き上げた転換点である。戦いの後、ブルサ平野はオスマン朝の管理下に入り、イズニクの封鎖が始まった。", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["ディンボスの勝利と続くキテとウルバトの占領", "e168ab64"], "d": ["TDVのオスマン1世の項：ヒジュラ暦702年（1303年）に、ブルサ、ケステル、キテ、アドラノスのテクフルたちが結んだ同盟は、ディンボス隘路で敗走させられた。敵は戦いながら狭い隘路まで退き、ケステルのテクフルは戦場で死んだ。勝利の直後にキテとウルバトの城塞が占領され、ブルサの陸上の連絡が断たれ、封鎖が強化された。若いオルハンもこの戦いに加わった。", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["サカリヤ遠征：レブレビジヒサル、レフケ、メケジェ、ゲイヴェの占領", "a51ba4d3"], "d": ["TDVのオスマン1世の項は、ヒジュラ暦704年（1304年）のサカリヤ遠征の順序を伝える。「レブレビジ城塞に来ると、テクフルは服従した…レフケに達した…メケジェに着いた…ゲイヴェに行き、空であった城塞を取った。」レフケは、サカリヤ渓谷のビレジクに開く門である。この一度の遠征は、渓谷沿いに延びる城塞の連鎖をオスマン朝の管理下に移し、イズニク盆地の東翼を閉ざした。", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["キオスがジェノヴァのザッカリア家の支配に移った", "9eebe4de"], "d": ["アイドゥン侯国の脅威を前に、ビザンツ皇帝はジェノヴァ人ベネデット・ザッカリアに助けを求め、島は彼の支配に移った(名目上のビザンツの封臣関係)。ザッカリア家の支配は1329年まで続いた。", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["サモスがキオスのジェノヴァ人(ザッカリア家)の所有に入った", "0e6f51e3"], "d": ["キオスを支配下に置いたジェノヴァのザッカリア家は、ほとんど無人となっていたサモスも所有に加えた(TDV:1304年から1329年)。", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["ゲイヴェ隘路の城塞の征服：カラチェピュシュ、カラティギン、アプス", "76907c78"], "d": ["TDVのオルハンの項：オルハンはヒジュラ暦705年（1305年）のサカリヤ遠征で「カラチェピュシュ（カトイキア）、イズニクの前のカラティギン、アプス（ヒプスー：ゲイヴェ隘路にある）の城塞を征服した」。この三つの城塞は、サカリヤ渓谷とイズニク盆地の間の通路を閉ざして、イズニクの陸上の援助を完全に断った。ゲイヴェの隘路にあるカラチェピュシュとアプスにはガーズィー・アブドゥッラフマーンが置かれた。都市はもはや飢えによってのみ陥落させられる状態となった。", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["アドラノス（オルハネリ）遠征 — オスマン・ベイの最後の遠征", "4811546c"], "d": ["TDVのオルハンの項は、1323年の秋のアドラノス城塞の遠征をオスマン・ベイの最後の遠征として記す。アドラノスのテクフルは、二十年前にディンボスでオスマン朝に対して結ばれたテクフルたちの同盟の一員であった。この遠征はその清算の意味を持っていた。城塞の決定的な征服の日は知られていない。作戦はオルハン・ベイによって続けられた。", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["オスマン・ガーズィーの死去とオルハン・ベイの侯位継承", "021487cd"], "d": ["侯国にその名を与えたオスマン・ガーズィーは、アスポルチャ・ハトゥンおよびメケジェの寄進文書の証言により、724年（1324年）に没した。1305年から遠征で軍の先頭に立っていた子オルハンは、父の死に際し王位争いを経験することなく侯国の長に就いた。創設世代が軍旗を揺るぎなく引き継いだことは、辺境侯国から国家への道において、一族が最初の大きな試練を静かに乗り越えたことを示している。", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["キオスのザッカリア家からの奪取とビザンツへの結びつけ", "f6741b26"], "d": ["皇帝アンドロニコス3世はザッカリア家を島から遠ざけ、島をベネデット3世の総督職のもとでビザンツに結びつけた。島は1346年にジェノヴァ人シモーネ・ヴィニョージによって占領されることになる。", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["サモスがザッカリア家からビザンツに戻った(キオスの連鎖)", "08034974"], "d": ["ザッカリア領主権の崩壊(キオスの1329年のビザンツへの結びつけ)とともに、サモスにおけるジェノヴァの所有も終わった。", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["ペレカノン（マルテペ）の戦いとコジャエリ全域の占領", "389e7bd4"], "d": ["TDVのオルハンの項：戦いの初日、オルハン・ガーズィーはビザンツ軍を引きつけるため三百人の部隊を送った。二日目にパザルル指揮下の部隊が平地に下りると戦いは拡大し、皇帝が矢で傷つくとビザンツ軍にパニックが起きた。結果は決定的である。「オルハンはコジャエリの全体を掌握した。勝利の後、イズニクの人々にはいかなる望みも残らなかった。」ヘレケからユスキュダルまでの沿岸の町がオスマン朝の支配に入り、ゲブゼは地域の中心とされた。これは、イスタンブルを救うために来た最後のビザンツ帝国の軍であった。", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["イズニクに最初のオスマン・メドレセが設立される", "c85fb625"], "d": ["オルハン・ベイはイズニクを奪った直後、チャンダルル・カラ・ハリルを同地のカーディーに任じ、バシリカをモスクに改め、その傍らにイマーレトとメドレセを建てさせて都市の整備を始めた。TDVの「ダーヴド・エル・カイセリー」の項によれば、メドレセの建設は1336年に完成し、オルハン・ガーズィーは日給30アクチェの教授職にダーヴド・エル・カイセリーを迎えた。このメドレセはオスマンの学問生活における最初の制度的な一歩であり、侯国は征服の力に加えて学問の伝統も備えることになった。征服したビザンツの都がイスラームの学問の中心に変わったことは、オスマンが定住国家たろうとする志向の最初の具体的な徴であった。", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["ビザンツの貢納化 — イズミット包囲と条約", "0c1ec8d3"], "d": ["TDVのオルハンの項：オルハンはヒジュラ暦733年（1333年）の夏に、イズミットを大軍と投石機で包囲し、皇帝は条約に同意した。包囲を断念することの見返りに、ビザンツはオルハンに毎年1万2000枚の金貨（ヒュペルピュロン）を支払うことを受け入れた。「こうしてオスマンの首長の目には、ビザンツは貢納国の状態に陥った。」見返りに、オルハンは皇帝の友となり、ビザンツに従属する都市を攻撃しないこととされた。辺境の侯国が東ローマを課税下に置いたことは、力の均衡がどれほど転じたかの宣言であった。", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["サモトラケがヴェネツィア人からジェノヴァのガッティルージオ家に移った", "c499ed5f"], "d": ["1204年から島を保持していたヴェネツィア人を、ジェノヴァのガッティルージオ家が島から追い出した。", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["カレスィ侯国の併合：バルケシル、ベルガマ、ビガ、エドレミト、エルデク", "c7cb0511"], "d": ["TDVのオルハンの項（イナルジュク）は併合をヒジュラ暦735年（1334〜35年）に置く。デミルハン・ベイの死を受けて、カレスィのガーズィーたちとハジ・イルベイは、ドゥルスン・ベイを王位に招き、オルハンに助けを求めた。オルハンはまずバルケシルに進軍した。和平の交渉に向かったドゥルスン・ベイがベルガマの城塞から放たれた矢で死ぬと、侯国は全面的にオスマン領に編入された。同じ作戦でキルマスティとミハリチが服従し、ギョルヤズ（Gölyazı）が取られ、以前に安全を保証して残されていたウルバトが決定的に占領された。オルハンはカレスィ・サンジャクにスレイマン・パシャを任命し、ビガを辺境の中心とした — ルメリアへの渡海のための海事の人材はこうして得られた。注：TDVのカレスィオウル家の項は同じ出来事にヒジュラ暦746年（1345年）の日付を与える。百科事典は内部で矛盾している。同じ日に加わったその他の地：Çanakkale。", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["サモスがキオスのマオナの所有に入った", "01628b2f"], "d": ["ジェノヴァ人シモーネ・ヴィニョージがキオスを取り、統治がマオナ会社に委ねられたことで、サモスもキオスのジェノヴァ人(マオナ)の所有に入った(TDV:1346年から1475年)。", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["オルハン・ガーズィーとジェノヴァ人との最初のカピチュレーション", "e64cb196"], "d": ["ヴェネツィア-ジェノヴァ戦争の間にジェノヴァ人と手を結んだオルハン・ガーズィーは、1352年2月の海峡の海戦の後、ペラの防衛に弓兵1000人を送り、兵員輸送のために6万金貨を用立てた。その見返りにジェノヴァ人に最初のカピチュレーションを与えた。協定の全文は現存しない。これはオスマンがヨーロッパの海洋勢力と結んだ最初の公式な協定であり、35年後の1387年に更新されることになる。", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["ゲリボルの奪取 - ルメリアにおける恒久的な橋頭堡", "ba51a160"], "d": ["1349-1352年の間にカンタクジノスの同盟者として周辺を知っていたゲリボルを、オスマンは1354年に占領した。都市の城壁を崩した大地震が好機をもたらした。チンペの狭い橋頭堡はこうして海峡のルメリア側における本当の拠点となり、トラキアへの門は大きく開かれた。ゲリボルは1366年のサヴォイア十字軍により失われるが、1376年の二度目の征服で最終的にオスマンの支配下に入ることになる。同日に編入されたその他の地:キリトバヒル。", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["ルメリアの征服者スレイマン・パシャの死", "2dc98228"], "d": ["オルハン・ベイの長子でルメリア征服の立役者であったスレイマン・パシャは、史料に758年(1357年)、759年、760年(1359年)として挙げられる年のうち最も受け入れられている1357年の秋に、狩りの最中に落馬して死んだ。1352-1354年の渡海でルメリアにおけるオスマンの恒久的な存在を築いた王子の死により、世継ぎの順は弟ムラトに移った。ボラユルに葬られたスレイマン・パシャの廟は、オスマンのヨーロッパにおける最古の王家の記念建造物として残った。", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["ペンチク法 - イェニチェリ軍団の礎", "e5877c2d"], "d": ["ルメリア征服の後、ウラマーのカラマンル・カラ・ルステムの勧めにより、戦争捕虜の5分の1、またはそれに相当する金銭を国家に割り当てるペンチク制度が施行された。これらの捕虜から選ばれた者をトルコ人の家庭で育てて兵とすることで、スルタン直属の常備歩兵部隊、すなわちイェニチェリ軍団の核が形成された。部族騎兵に依拠した辺境侯国が、中央軍を持つ国家へと変わることは、この制度から始まった。", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["西トラキアへの進出:ギュミュルジネの征服", "9ef69221"], "d": ["エディルネの奪取後、マリツァ川の西へ向かった辺境部隊は、ガーズィー・エヴレノス・ベイの指揮下で西トラキアの中心ギュミュルジネを占領した。同市は、エヴレノス・ベイの襲撃をマケドニアへ広げるための前進司令部となった。こうしてエーゲ海岸に達するトラキアの部分がオスマンの支配下に入り、テッサロニキへの道が開かれた。", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["ヴァルナ、ドブルジャ侯国に移り首都となる", "2bfe73f9"], "d": ["ブルガリア帝国の解体過程で、黒海沿岸のヴァルナはドブロティツァが築いたドブルジャ侯国に編入され、この小国の首都とされた。", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["フィリベの西:タタルパザルジュクとイフティマンの併合", "1664d0e1"], "d": ["1372年のフィリベ(プロヴディフ)奪取の後、マリツァ川上流端のタタルパザルジュクと、ソフィアへの隘路を押さえるイフティマンがオスマンの統治下に組み込まれた。チルメンの戦いの後に臣従した地方ベイたちの手にあったこの線は直接統治に移され、フィリベ-ソフィア間の経路が途切れなくつながった。この進出は、12年後のソフィア征服への道を準備するものである。", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["サヴジュ・ベイの反乱 - 王子とビザンツ皇太子の共同の叛旗", "75198c33"], "d": ["ムラト1世の子サヴジュ・ベイと、ビザンツ皇帝ヨハネス5世の子アンドロニコス・パライオロゴスは、1373年5月の初めにブルサとコンスタンティノープルで同時に、それぞれの父に対して蜂起した。二つの王朝の世継ぎを結んだこの同盟は速やかに鎮圧され、サヴジュ・ベイは捕らえられて目をつぶされ、処刑された。オスマンの伝承が反乱の年として挙げる787年(1385年)は誤りである。この事件はビザンツがオスマンの臣従に入った年月の直後にあたり、二つの宮廷がいかに絡み合っていたかを示している。", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["ストルマ川・メスタ川流域:キュステンディル、ペトリチ、ネヴロコプ、ドラマの併合", "8c0980c4"], "d": ["チルメンの勝利の後オスマンに貢納を始めたセルビア・ブルガリアの地方ベイたちの手にあったストルマ川とメスタ川の流域は、辺境ベイたちの進出により直接オスマンの統治下に置かれた。キュステンディル、ペトリチ、ネヴロコプ、ドラマの併合によってマケドニアの東半分が開け、テッサロニキとセレスは包囲網に入った。地図上でのルメリアの南西への拡大は、この作戦の結果である。", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["エレトナ侯国の終焉とカーディー・ブルハーネッディーン国家の成立", "60dcaf57"], "d": ["1335年にイルハン朝の総督領から興り、スィヴァスとカイセリを中心に四十六年間中央アナトリアを支配したエレトナ家は、宮廷内の抗争で解体した。1378年5月に宰相となったカーディー・ブルハーネッディーンは、ライバルのクルチュ・アルスランとハジ・シャドゲルディを排除したのち、1381年秋にスルタンを宣言して侯国に終止符を打ち、自らの名を冠した国家を建てた。こうしてオスマン朝の東の隣国は持ち主が変わり、スィヴァス＝カイセリ線はその後十七年間カーディー・ブルハーネッディーンの手にとどまることになった。", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["ティムールがヘラートを取る：カルト朝の終わりとホラーサーンのティムール朝への移行", "15f6019e"], "d": ["ホラーサーンは1380年にサルバダール朝、カルト朝、ムザッファル朝の間の争いで分裂していた。ティムールは息子ミーラーンシャーを地域に送った後、自らヘラートに進み、しばらく包囲した後、都市をカルト朝のマリク、ギヤースッディーン・ピール・アリーから受け取った。彼の出発の後に起きた反乱はミーラーンシャーによって血で鎮圧され、1255年からヘラートを支配してきたカルト朝は終わった。マシュハドからニーシャープールまで、ホラーサーンの全体がこの日付でティムール朝の統治に入った。", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["マケドニア内陸への進出:マナストゥルとオフリドの征服", "63bb7838"], "d": ["エグナティア街道上のマナストゥル(ビトラ)と湖畔のオフリドは、アルバニア方面への襲撃の際にオスマンの統治下に入った。いずれもアドリア海に至る道の要衝であり、オフリドはバルカン最古の正教大主教座の所在地でもあった。TDVはオフリドの征服年について確かな情報はなく、787年(1385年)とクラリェヴィチ・マルコの死後の797年(1395年)が挙げられていると記しており、ここでは1385年を採った。マナストゥルは以後の世紀にルメリア最重要の軍事拠点の一つとなる。", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["サヴラの戦い - アルバニアの扉が開く", "dda6671b"], "d": ["バルシャ家に対して追い詰められたアルバニアの領主カルロ・トピアの救援要請を受け、オスマン軍はサヴラ平原でバルシャ2世の軍を破り、バルシャは戦場で命を落とした。現地の領主の招きで入ったこの戦いは、オスマンにアドリア海岸まで広がるアルバニアの地における最初の恒久的な影響力をもたらした。地域の領主たちの反目を好機とするこの政策は、次の1世紀のバルカン征服の変わらぬ方法となった。", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["ティムールの「三年遠征」：アゼルバイジャンと北イランの征服", "2a98ec51"], "d": ["ホラーサーン遠征のあいだにイランの分裂した状態を間近に見たティムールは、ヒジュラ暦788年（1386年）に西に進んだ。「三年遠征」と呼ばれる1386〜1388年の作戦で、マーザンダラーン、ルリスタン、ジョージアを経てアゼルバイジャンに入り、カラバフに達した。タブリーズ、アルダビール、ウルミア、ナヒチェヴァンがティムール朝の統治に入った。北イランとアゼルバイジャンの掌握は、かつてジョチ・ウルスとイルハン朝の間であったように、キプチャク・ハン国との長い争いの始まりともなった。", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["フレンクヤズュスュの戦いとコンヤ包囲 - 最初のカラマン遠征", "af4e5d77"], "d": ["娘婿でありながらオスマンの西アナトリアでの拡大を快く思わなかったカラマン侯アラーッディーン・アリ・ベイに対し、ムラト1世は自ら出征した。フレンク・ヤズュスュと呼ばれる地で行われた戦いで、訓練され経験を積んだオスマン軍はカラマン軍を破った。続いてコンヤ城が包囲されたが、アラーッディーン・ベイが赦されたため侯国は完全には廃されなかった。この遠征は、オスマンとカラマンの間で1世紀続き、1468年の最終的な併合で終わる長い対決の幕開けである。", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["ムシュがカラ・コユンルの統治からティムールの統治に移った(789年/1387年)", "ed2e7a11"], "d": ["モンゴル時代の後にカラ・コユンルの統治に移っていたムシュは、789年(1387年)に、カラ・コユンルの領土を手にしたティムールの統治下に入った。アトラスではムシュはこの年にカラ・コユンルからティムール朝へと記される。", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["ゲリボル造船所の設立 - オスマン海軍の誕生", "47546241"], "d": ["オスマン国家の最初の組織的な造船所は、1390年にユルドゥルム・バヤジトによってゲリボルに、ビザンツから残った造船所の跡地に設けられた。西アナトリアの諸侯国の海の遺産を受け継いだオスマンは、こうして初めて自ら船を建造する海軍力となった。ダーダネルス海峡の要衝に位置する造船所は、コンスタンティノープルの包囲からエーゲ海遠征に至るまで、1世紀半にわたりオスマン海軍の主要基地として機能した。", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["ハミド・イリ、オスマンに編入:ウスパルタ、ブルドゥル、ウルボル、エイルディル", "e3da7de5"], "d": ["カラマン侯アラーッディーン・ベイがハミド・イリを攻撃し、民衆が訴えたことを受けて出征したユルドゥルム・バヤジトは、ハミド侯国の残りの領土をすべて掌握し、その統治を息子イサ・チェレビに与えた。", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["ムザッファル朝の終わり：シャー・マンスールのシーラーズ前での敗北", "5fd14eb8"], "d": ["1318年からヤズド、ファールス、イスファハーン、ケルマーンを支配してきたムザッファル朝の最後の有力な君主シャー・マンスールは、親族と結束してティムールに対して行動を起こした。シーラーズ近郊の戦いで、将の一人が敵側に移ったことにより兵力の多くを失い、敗れて殺された。ティムールが続けて王朝のすべての成員をも殺させたことで、ムザッファル朝の支配は終わり、ファールスとケルマーンはティムール朝の統治に加わった。", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["アマスヤのオスマン領への併合", "fe2860cf"], "d": ["ユルドゥルム・バヤジトの中央アナトリア作戦の際、包囲されたアマスヤのアミールは市をオスマンに引き渡し、バヤジトは1393年に市に入った。スルタンはこの地の統治を息子メフメト・チェレビに委ね、王子のサンジャク（県）としてのアマスヤは、以後オスマン王家の最も重要な教育の場の一つとなった。同日に手を離れたその他の集落：ラディク（アマスヤ）、メルジフォン、オスマンジク、チョルム。この選択は後の空位時代に決定的な意味を持つことになり、チェレビ・メフメトは国家再統一の闘いをまさにこのアマスヤを拠点として進めた。", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["ティムールがバグダードを占領 — ジャライル朝がアナトリアに逃れる", "4d5602b3"], "d": ["ティムールは長い包囲の後にバグダードを取った。都市の主ジャライル朝のスルタン・アフマドは西に逃れ、まずマムルーク朝に、次いでオスマン朝の宮廷に身を寄せた。ティムールの西方への拡大は、こうして初めてオスマン朝の勢力圏と直接接した。二人の君主の間の敵意の最初の環は、ここから始まる。", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["黒海沿岸のヴァルナの奪取", "a84b2abf"], "d": ["ドナウ川と黒海の間のブルガリア帝国領が圧迫される中で、沿岸最大の港ヴァルナがオスマンの統治下に入った。港の奪取はドブルジャ方面への進出の道を開き、オスマンに黒海西岸の最初の大きな船着き場をもたらした。ヴァルナは51年後、十字軍が殲滅される1444年の勝利の舞台ともなる。", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["ネヴシェヒルとユルギュップの一帯がカラマン侯国からオスマンの手に渡った", "06ff59e8"], "d": ["バヤジト1世(雷帝)のカラマン侯国に対する遠征で、ネヴシェヒル(ムシュカラ)とユルギュップの一帯は、ヒジュラ暦800年/1398年にオスマンの統治に移った。1402年のアンカラの戦いの後、ティムールは地域をカラマン侯国に返した。", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["カーディー・ブルハーネッディーン国の滅亡", "b13391e3"], "d": ["アク・コユンルの君主カラ・ユルク・オスマン・ベイの捕虜となったカーディー・ブルハーネッディーンは、スィヴァスの引き渡しと引き換えに自らを解放するよう申し出たが、市民は抵抗し、スルタンは城壁の前で処刑された。スィヴァスの有力者たちは息子アラーッディーン・アリ・チェレビを擁立したが、アク・コユンルの圧力のもとでユルドゥルム・バヤジトに援助を求め、スレイマン・チェレビ指揮下のオスマン軍がカラ・ユルクを破って同市を掌握した。こうしてカーディー・ブルハーネッディーン国は歴史から消え、スィヴァス、トカト、ニクサル、カイセリはオスマン領に編入された。同日に編入されたその他の地：クルシェヒル、チョルム。", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["ティムールとの対立：逃亡者の引き渡しの拒否", "33790bc8"], "d": ["ティムールの圧力により、ジャライル朝のスルタン・アフマドとカラ・コユンルの指導者カラ・ユースフはオスマン領に逃げ込んだ。ティムールはこの二人の逃亡者の引き渡しを求め、イルドゥルム・バヤジトは拒んだ。これを受けて、二人の君主の間で相互の激しい侮辱を含む書簡の応酬が始まった。戦争の思想的な土台は、まだ一人の兵も動かないうちに、これらの書簡によって築かれた。", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["ブルサのユルドゥルム施療院 - 最初のオスマン病院", "5f0dc59a"], "d": ["ユルドゥルム・バヤジトはブルサに壮麗なウル・ジャーミィを建てさせた年月に、都市に施療院も贈った。イマーレト、メドレセ、ハン、橋からなる大規模な慈善事業計画のうち、医療にあてられた環がこれであった。国家が設立した最初の病院であるこの建物は、医師を養成する医学校の役割も果たし、オスマンの保健施設の模範を定めた。アンカラの惨事のわずか2年前に完成したこの建造物は、ユルドゥルムがブルサを帝国の首都に変えようとした構想の最後の環の一つである。", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["ティムールがシヴァスを破壊", "f4d79de6"], "d": ["アク・コユンルのカラ・ユリュク・オスマン・ベイとエルズィンジャンの首長ムタハルテンの案内でシヴァスに進んだティムールは、都市を十八日間包囲し、誰の血も流さないという約束で受け取った後、大虐殺を行った。守備兵を堀に詰め込んで生き埋めにした。城壁をはじめ都市の重要な建造物は破壊され、シヴァスは人口の面で崩壊した。これは、アンカラの戦いの二年前にティムールがオスマン領に加えた最初の大きな打撃である。", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["イルドゥルム・バヤジトがエルズィンジャンとケマフを奪回", "7047ca08"], "d": ["ティムールがシリア遠征に出たことを好機とみたイルドゥルム・バヤジトは、ティムールに従属するエルズィンジャンの首長ムタハルテンの手からエルズィンジャンとケマフを取った。シヴァスの破壊に介入しなかったにもかかわらず、この動きは、ティムールの東アナトリアにおける勢力圏への直接の挑戦を意味した。二人の君主の仲は、この後、修復できないものとなった。", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["ティムールがタブリーズから送った最後通牒 — 四つの条件", "3e1ac50e"], "d": ["ティムールはタブリーズから送った使者を通じて四つの条件を伝えた。ケマフのムタハルテンへの返還、アナトリアの諸侯から取った領土の持ち主への返還、オスマン朝の王子を人質として送り、帽子（külâh）と帯を服属の印として受け入れること、そしてカラ・ユースフの引き渡しである。バヤジトはこれらのどれも受け入れなかった。政治家たちの求めとムタハルテンの仲介にもかかわらず、交渉は決裂した。ティムールは、中国遠征に出る前にアナトリア問題を決定的に片づける決意であった。", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["サルハン侯国の再興 — マニサがオスマン朝から離れる", "ac747b05"], "d": ["アンカラの敗走の三週間後、ティムールの支援でオルハン・ベイが侯国の長となり、サルハン地方は再び独立した。マニサを中心とする地域は、1390年のオスマン朝の併合から十二年後に地図から消えた。これは、ティムールの侯国を復活させる政策の、日付が確実に知られる最初の実施の一つである。", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["エミール・スレイマンが国庫とともにルメリアに逃れる", "0a2b7363"], "d": ["ブルサにあった国庫、文書、家族、兄弟たちを連れたエミール・スレイマンは、ゲムリクから船でギュゼルジェヒサル（アナドル・ヒサル）に渡り、そこからゲリボルに達して、エディルネで君主位を宣言した。国家の文書と国庫がルメリアに運ばれたことは、オスマン朝の重心が一世代のあいだバルカンに移ることの始まりである。地図ではルメリアはこの日付からエミール・スレイマン自身の色で描かれる。", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["ティムールがアナトリアの諸侯国を再建──テュルクの統一が崩壊", "15187774"], "d": ["ティムールはアンカラでの勝利の後、同行していた諸侯を旧領に戻した。カラマンオウル・メフメトとアリー両ベイにはカラマン領とカイセリ、クルシェヒル、スィヴリヒサル、ベイシェヒルが、ゲルミヤンオウル・ヤークーブ2世ベイにはキュタヒヤとゲルミヤン領が、ジャンダルオウル・イスフェンディヤル・ベイにはカスタモヌ－シノプの線に加えてチャンクル、カレジクが与えられた。アイドゥン、メンテシェ、テケの各領も旧王家に戻った。イルドゥルム・バヤジトが10年かけて築いたアナトリアのテュルク統一は、ひと夏のうちに崩壊した。地図上ではこれらの侯国が再びそれぞれの色で現れる。同じ過程で手を離れたその他の集落：アクサライ、デニズリ、エレーリ（コンヤ）、エルメネク、ウルグン、カラプナル、カイセリ、コンヤ、クルシェヒル、キュタヒヤ、スィヴリヒサル、ソケ。", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["ティムールがイズミルを聖ヨハネ騎士団から奪取", "66dd1dd4"], "d": ["キュタヒヤ、デニズリ、アイドゥン、アヤスルク、ティレ経由で西に下ったティムールは、1344年からキリスト教徒の手にあった沿岸のイズミルを包囲して取った。イルドゥルム・バヤジトが長年取れなかったこの城塞を短期間で占領したティムールは、周辺の城塞も取った後、アイドゥン地方を旧来の持ち主に残して東に戻った。都市はこの後、アイドゥンオウルのジュネイド・ベイの統治に入った。", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["イーサー・チェレビがブルサを掌握 — アナトリアの分け前が生まれる", "955128c1"], "d": ["アンカラの敗走の後カレスィの方面に退いていたイーサー・チェレビは、ティムールがイズミルにいる間にブルサを掌握した。ティムールの兵に略奪され焼かれた旧都で君主位を宣言し、自らの名で貨幣を鋳造させた。1403年1月にはアナトリアで「トルコ人の君主」の称号で認められていた。地図ではマルマラのアジア側沿岸に延びるこの分け前は、イーサー・チェレビ自身の色で現れる。", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["ティムールのアナトリアからの撤退", "93a98839"], "d": ["イルドゥルム・バヤジトがアクシェヒルで崩御した知らせを受けたティムールは、アナトリアでの仕事は終わったとみなして東に向かった。後には、彼への忠誠を表明した侯国と、互いに対立したオスマン朝の王子たちが残された。シヴァスなどいくつかの都市は、ティムールに従属するメズィド・ベイのような首長の手に残された。ティムールは二度とアナトリアに戻らなかったが、彼が築いたこの分裂した秩序は十年続いた。", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["エミール・スレイマンがアナトリアへ渡る:ブルサが彼の手に落ちる", "9b27aa5f"], "d": ["イーサー・チェレビの敗北を聞いたエミール・スレイマンは、チャンダルル・アリ・パシャとともに強力な軍を率いてアナトリアへ渡り、ブルサを奪取した。1404年3月の記録は、カラデニズ・エレーリも彼の統治下にあったことを示す。まもなくルメリアとアナトリアの大部分を支配したスレイマンに対し、チェレビ・メフメトは抵抗できなかった。同じ過程でチェレビ・メフメトからエミール・スレイマンへ移ったその他の集落：アクヤズ、アナドル・ヒサル、アブス（Hypsu）、アドラノス（オルハネリ）、アクヒサル（パムクオワ）、アルムトル、アイドス城、アイワルク、バルケシル、ベフラムカレ（アッソス）、ベルガマ、ベイコズ、ビガ。地図上ではこの日付からチェレビ・メフメトによるブルサ再奪取（1410年）まで、両岸が単一の色でエミール・スレイマンの取り分として表示される。", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["イェニシェヒル平野の戦い — チェレビ・メフメトがアマスヤに退く", "f1568288"], "d": ["ブルサとアンカラを失ったチェレビ・メフメトは、イェニシェヒル平野でエミール・スレイマンに敗れて西アナトリアのすべての獲得地を失い、トカト＝アマスヤの拠点に退いた。この敗北の後、直接の衝突を避けてアナトリアの内陸で権威を固める方向に向かった。空位時代の最も長い静かな局面は、このように始まった。", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["エミール・スレイマン、チェレビ・メフメトからアンカラを奪う", "d6a2acd6"], "d": ["ティムールのアナトリア撤退後もチェレビ・メフメトの手に残っていたアンカラを、1406年にエミール・スレイマンが包囲した。城の守将ヤークーブ・ベイはしばらく持ちこたえたが、大宰相チャンダルル・アリ・パシャの策略によって城をスレイマンに明け渡した。これを受けてチェレビ・メフメトはカラマン侯メフメト・ベイと協定を結び、スレイマンに対して行動を起こした。", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["チェレビ・メフメト、スィヴァスをティムール朝のメズィド・ベイから奪還", "90079b0c"], "d": ["ティムールの侵攻後、スィヴァスの統治はティムールに臣従するメズィド・ベイに委ねられていた。アマスヤにいたチェレビ・メフメトは部将バヤジト・パシャを派遣して同市を奪取させ、激しい抵抗の末にスィヴァスは二度目のオスマン家の手に渡った。こうしてメフメトの領分は、アンカラの戦いから6年後に東方で旧来の国境に達した。", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["アルトゥク家の終焉:マルディンのカラ・コユンルへの引き渡し", "15b06f33"], "d": ["1106年からマルディンに君臨し、一族の中で最も長く続いた系統であったアルトゥク家は、アク・コユンルの圧力に耐えられなかった。都市を守れないと悟ったマリク・アフメトは、カラ・コユンルの君主カラ・ユースフと協定を結んでマルディンを引き渡した。3世紀を超えるアルトゥク家の支配はこうして終わった。マルディンとその周辺は、1世紀後にオスマンに移るまで、カラ・コユンルとアク・コユンルの争いの舞台となった。", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["ヤンボルの戦い - ムーサー・チェレビ、エディルネに入城", "8f978408"], "d": ["ワラキア経由でルメリアに渡ったムーサー・チェレビは、ワラキアとセルビアの支援を得てヤンボルでエミール・スレイマンの軍を破り、エディルネに入城した。空位時代においてルメリアがエミール・スレイマンの手を離れたのはこれが初めてであった。しかしその支配は長続きせず、4か月後にコスミディオンで敗れてバルカン内陸へ退くことになる。", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["インジェイズの戦い - チェレビ・メフメトのルメリアでの最初の敗北", "3c35cd43"], "d": ["ビザンツの船でルメリアに渡ったチェレビ・メフメトはインジェイズでムーサー・チェレビと交戦したが、ムーサーは配下のイェニチェリ7千人でメフメトを破り、メフメトはアナトリアへ戻らざるを得なかった。この敗北はメフメトを、直接の戦闘ではなくルメリアのウチ・ベイたちとセルビア専制公国を味方につける戦略へと向かわせた。9か月後のチャムルルの勝利の下地は、この外交によって整えられた。", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["コンヤ包囲とカラマン侯国との協定 - ハミド・イリ、サイド・イリ、ベイシェヒル、セイディシェヒル、アクシェヒルの奪還", "0996257e"], "d": ["空位時代にオスマン領を攻撃してブルサを包囲し焼いたカラマン侯国に対し、チェレビ・メフメトは大規模な遠征を組織し、ヒジュラ暦818年ムハッラム月にコンヤを包囲した。カラマン侯メフメト2世・ベイは和を乞わざるを得なかった。協定の結果、ハミド・イリ（ウスパルタ周辺）とサイド・イリが再びオスマン領に編入され、ベイシェヒル、セイディシェヒル、アクシェヒルも返還された。ティムールが1402年にカラマン侯国に与えたスィヴリヒサルもオスマンに戻った。アンカラの戦いで崩れたアナトリアの統一が繕われ始めたこの遠征は、チェレビ・メフメトが「第二の創建者」とされる具体的な根拠の一つである。", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["アイドゥン侯ジュネイド・ベイからのイズミル奪取", "2377ca51"], "d": ["空位時代を通じて諸王子の間で絶えず陣営を替えたアイドゥン侯ジュネイド・ベイの本拠イズミルは、10日間の包囲の末にチェレビ・メフメトによって奪われた。ジュネイドは赦されてニグボル(ニコポル)のサンジャク・ベイに送られた。1402年にティムールがアイドゥン侯国に返還した同市は、こうして13年後にオスマン領へ戻った。ジュネイドは1422年に同市を再び奪うが、問題が決着するのは1424-1426年のムラト2世の時代である。", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["トルラク・ケマルの処刑 - サルハンは最終的にオスマン領に", "8a09dbf1"], "d": ["シェイフ・ベドレッディン運動の西アナトリア側を担ったトルラク・ケマルは、マニサ周辺で敗れて処刑された。この日以降サルハン地方は最終的にオスマンの支配下に入り、1402年にティムールが復活させた侯国は歴史から消えた。空位時代の西アナトリアにおける最後の政治的残滓はこうして一掃された。", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["ヴロラ(アヴロニャ)、ベラト、カニナの征服", "1e1949b8"], "d": ["オスマンは1417年に、アドリア海岸のヴロラを、内陸のベラトの町とカニナ城とともに支配下に収めた。1年後、ヴェネツィアが同市の奪還を試みて失敗し、ここにサンジャク制が敷かれてオスマンの権威は恒久化した。ヴロラの奪取により、オスマンは初めてアドリア海に直接の港を持つことになり、イタリアに対する海を越えた足がかりを得た。", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["中央アナトリアの奪還:カイセリとクルシェヒル", "204eacb3"], "d": ["空位時代にカラマン侯国の手に渡った中央アナトリアの諸都市は、チェレビ・メフメトが国家を再建する遠征の間にオスマンの統治に戻った。カイセリとクルシェヒルの編入によって、アンカラの戦いで失ったクズルウルマク流域はおおむね取り戻された。この進出は、4年前のコンヤ包囲に始まる東方への政策の継続である。", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["マムルーク朝、カイセリをドゥルカディル家のナースィルッディーン・ムハンマドに与える", "aad4b00c"], "d": ["カラマン侯メフメト・ベイに対して出征したマムルーク軍はカイセリを占領した。マムルーク軍の司令官は同市とその周辺をドゥルカディル家のナースィルッディーン・ムハンマドに委ねて自国へ帰った。", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["メフメト1世の死とムラト2世の即位", "98acac77"], "d": ["空位時代(フェトレト)を終わらせてオスマンの領土を再び一手にまとめたメフメト1世は、1421年6月25日にエディルネで死去し、息子のムラトがブルサで即位した。死の前にビザンツと結ばれた取り決めによれば、幼い息子たちは人質として皇帝のもとに送られ、皇帝も手元に置く王位請求者のムスタファ・チェレビーを釈放しないことになっていたが、ムラト2世は弟たちを皇帝に送ることを拒んだ。", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["テケ侯国の最終的な解体:アンタルヤの奪取", "e65565b2"], "d": ["アンカラの戦いの後、ティムールの復活によって再建されたテケ侯国は、ハムザ・ベイ指揮下のオスマン軍がアンタルヤを包囲して終焉した。侯国最後の有力者オスマン・チェレビは排除された。これで地中海岸のテケ地方は、21年にわたる分離の後に最終的にオスマンに編入された。同侯国はハミド侯国から分かれた一派として、1321年からアンタルヤに君臨していた。", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["トゥラハン・ベイのモレア遠征とヘクサミリオン城壁の破壊", "c6c2706d"], "d": ["ビザンツが対立する王位請求者ムスタファ・チェレビを支持したことを受け、ムラト2世はトゥラハン・ベイをモレアに派遣した。トゥラハン・ベイはコリント地峡を端から端まで塞ぐヘクサミリオンの城壁を壊して半島に入り、大きな破壊を引き起こした。和平は、城壁を二度と築かないことと年貢を納めることを条件に結ばれた。モレア専制公国はこうして軍事的に無防備にされ、1460年の最終的な征服の下地は37年前に準備された。", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["アトス山(アイナロズ)の修道院群、オスマンの保護下に入る", "562de5ea"], "d": ["テッサロニキが包囲下に置かれていた年月に、ハルキディキ半島東端のアトス山修道院共和国はムラト2世に庇護を求め、オスマンの宗主権を受け入れた。修道士たちの所有権と礼拝の権利は保障され、修道院群は納税と引き換えに内政で自由を認められた。この制度はオスマンが正教の諸機関と結んだ保護関係の最も長続きした例となり、5世紀続いた。", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["タージェッディン侯国の併合:ニクサル", "370ffd47"], "d": ["アマスヤ総督ヨルギュチ・パシャの圧力を受け、タージェッディン家のヒュサーメッディーン・ハサン・ベイは、ニクサルを中心とする領国の鍵を830年(1427年)に引き渡し、ルメリアにサンジャクを与えられた。14世紀後半に成立し、境界がときにケルキト、アマスヤ、サムスン、オルドゥ、ギレスンにまで及んだこの侯国はこうして終わった。同年、ハジェミール家に属する土地も検地されてジャニクのサンジャクに編入され、中部黒海の侯国の時代は閉じた。", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["ベオグラードのハンガリーへの譲渡 — タタ条約", "62481183"], "d": ["セルビアの専制公ステファン・ラザレヴィチの死を受けて、ハンガリー王ジギスムントと後継者ジュラジ・ブランコヴィチの間で結ばれたタタ条約により、ベオグラード要塞はハンガリーに譲渡された。ドナウ川とサヴァ川の合流点に立つ要塞は、それまでセルビア専制公国の手にあり、オスマンにとって中央ヨーロッパに開く門の鍵であった。この譲渡は、ベオグラードを100年にわたってオスマンの進出の前で最も厳しい障害とした。1440年と1456年の包囲は失敗し、要塞は1521年にようやく陥落することになる。", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["マルディン、カラ・コユンルの守将からアク・コユンルのカラ・ユルク・オスマン・ベイへ", "d82bc97f"], "d": ["カラ・ユースフが1409年に奪ったマルディンはカラ・コユンルが総督を置いて統治していたが、守備を任されたエミール・ナーシルが、835年(1432年)に同市をアク・コユンルのカラ・ユルク・オスマン・ベイに引き渡した。アク・コユンルの統治は16世紀初めまで続いた。", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["カラマン侯国、カイセリをドゥルカディル家から奪う", "2b09e8e8"], "d": ["カラマン侯はドゥルカディル家に対して収めた勝利により、カイセリ、ユルギュップ、デヴェリ・カラヒサル、ウチヒサルを自国に加えた。", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["ブチュクテペ事件 - 最初のイェニチェリの蜂起とムラト2世の復位", "6388dda1"], "d": ["エディルネで起きた、歴史上知られる最初のイェニチェリの蜂起であるブチュクテペ事件は、俸給(ウルーフェ)を半アクチェ引き上げよという要求から始まり、若いメフメト2世の廃位に終わった。ムラト2世は850年サファル月8日にマニサから急ぎ出立し、第二の治世を始めた。この事件は、カプクル軍団がもはや王位に発言権を持つ力となったことを示す最初の徴候であり、ファーティフの生涯にわたるイェニチェリへの警戒を形作った。", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["エピロス沿岸の併合:アルタとプレヴェザ", "796f7ecf"], "d": ["ヤニナが1430年に降伏してから19年後、エピロス専制公国の沿岸部のアルタとプレヴェザもオスマンの統治下に入った。これによりイオニア海に開くアンブラキア湾が掌握され、ヤニナの海への連絡路が完成した。プレヴェザは、90年後にバルバロスの歴史的勝利にその名を与えることになる湾の要衝である。", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["ムラト2世の死去とメフメト2世の二度目の即位", "8f8256ad"], "d": ["息子の婚礼の後に病に倒れたムラト2世は、855年ムハッラム月1日(1451年2月3日)にエディルネで死去した。19歳のメフメト2世は、855年ムハッラム月16日(1451年2月18日)に二度目のオスマン王位に就いた - 今度は恒久的に。5年前にブチュクテペで退位させられた若い君主の復帰は、2年後のコンスタンティノープル征服で頂点に達し、オスマン侯国を世界帝国に変える治世の始まりである。", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["オスマン-クリム合同軍による最初のカッファ攻囲", "e346d163"], "d": ["1454年6月にファーティフ・スルタン・メフメトと協定を結んだクリム・ハン国のハジ・ギレイは、7千騎でカッファを陸から包囲し、50〜60隻のガレー船からなるオスマン艦隊も沖に陣取った。ジェノヴァ領のカッファは貢納を払って包囲を解かせ、最終的な征服は21年後の1475年に持ち越された。この最初の共同作戦は、オスマン-クリムの軍事協力が後にカッファの最終的な征服で繰り返される最初の例であった。", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["北エーゲ海の島々の奪取:ボズジャアダ、イムロズ、タソス", "76575895"], "d": ["コンスタンティノープル征服の直後、ファーティフ・スルタン・メフメトは新首都の海路を確保するため、ダーダネルス海峡のエーゲ海側の島々に向かった。ボズジャアダ(テネドス)とイムロズ(インブロス)はビザンツから、タソスはジェノヴァ系のガッティルージオ家から取られた。海峡の両岸を封じるこれらの島々は、以後コンスタンティノープルの糧食と防衛線の最初の環となった。教皇とヴェネツィアの艦隊の介入により支配はしばらく行き来し、1459年になってようやく確定した。", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["コソヴォの征服:プリシュティナとイェニパザルの奪取", "d7ed2345"], "d": ["セルビア専制公国に進軍したオスマン軍は、コソヴォ平原のプリシュティナとラシュカ地方の中心イェニパザルを占領した。同じ作戦で銀鉱山で名高いノヴォ・ブルドも奪われた。これでセルビアの南半分が直接オスマンの統治下に入り、スメデレヴォの専制公国はその中核の領土から切り離された。この征服は、4年後のセルビアの完全な併合に至る道の決定的な一歩であった。", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["イペク(ペチ)、オスマンの統治下に入る - ドゥカキン・サンジャクの中心の一つ", "19511588"], "d": ["1455年のファーティフ・スルタン・メフメトのセルビア遠征の直後に、セルビア総主教座の所在地イペクがオスマンの統治に移った。オスマンの史料にはこの移行に関する記録はない。町は時とともに小さなムスリムの町となり、ドゥカキン・サンジャクでサンジャク・ベイの居所の一つとなった。", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["エネズとサモトラキ島の征服 - 西トラキア沿岸の完成", "106e723b"], "d": ["マリツァ川が海に注ぐ地点のエネズは、80年間そこを保持していたジェノヴァ系のガッティルージオ家から奪われ、同市に属するサモトラキ島も同じ作戦で占領された。エネズの陥落により、西トラキアの沿岸帯はテッサロニキからゲリボルまで途切れないオスマン領となった。ガッティルージオ家の手にはミディッリ(レスボス)だけが残り、それも6年後に奪われることになる。", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["ベオグラード攻囲の失敗", "3d53a604"], "d": ["ファーティフ・メフメトは、コンスタンティノープル征服後、中欧の鍵とされるベオグラードを包囲した。しかしヤーノシュ・フニャディがドナウ川から連れてきた増援と、十字軍の説教師カピストラーノが集めた義勇兵が城の陥落を防いだ。スルタンは攻囲の前で見せた個人的な勇猛にもかかわらず、負傷して撤退せざるを得なかった。この失敗は、ハンガリー国境を65年間オスマンの進出に対して閉ざし、ベオグラードは1521年にカーヌーニーによってようやく奪われることになる。", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["北モレアの征服:バリャバドラ(パトラ)", "c08a8509"], "d": ["セルビアの併合と同じ年に、モレア専制公国に向かったファーティフ・スルタン・メフメトの軍は、半島北西部のバリャバドラを占領した。コリント湾の入口を押さえるこの港はモレアへの陸路からの入口の鍵であり、その奪取は2年後の最終的な征服の下地を整えた。同市はビザンツ専制公たちがラテン世界と連絡を取る最後の大きな船着き場であった。", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["黒海西岸の奪取:アマスラ", "f43608fc"], "d": ["ジェノヴァの黒海西部における城塞植民市アマスラは、ファーティフ・スルタン・メフメトの海軍と陸軍の共同圧力により、抵抗せずに降伏した。バルトゥン-ゾングルダク沿岸のこの港は、カンダル侯国とオスマン領との間のラテン人の飛び地として存在していた。その奪取によって沿岸は一体化した。アマスラの陥落は、2年後(1461年)のシノプとトレビゾンドへの大黒海遠征の第一歩である。", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["ミディッリ島(レスボス島)の征服", "fe17aeba"], "d": ["ファーティフ・スルタン・メフメト率いるオスマン軍は、866年ズルヒッジャ月に、短くも激しい包囲の末にミディッリをジェノヴァ系ガッティルージオ家の手から奪い、併合した。北エーゲ海最大の島の陥落は、ジェノヴァ人の同地域における最後の重要拠点も一掃した。島はアナトリア沿岸に近いことから、以後オスマン海軍の前哨として働き、またバルバロス兄弟が育った地として海事史に名を残すことになる。", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["16年に及ぶオスマン-ヴェネツィア戦争の開始", "563ddb68"], "d": ["ヴェネツィア人は、オスマンのモレアとエーゲ海での進出を止めるため、カラマンおよびアク・コユンルの統治者たちと同盟し、1463年に戦争を始めた。東にウズン・ハサン、西にヴェネツィア、その間にカラマンという包囲戦略は、ファーティフを同時に複数の戦線で戦わせることを強いた。16年続いた戦いは、オトゥルクベリからアルバニア遠征まで当時のあらゆる大きな作戦を含み、1479年のイスタンブル条約でようやく終わることになる。", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["ヘルツェゴヴィナの大部分の征服:トレビニェとモスタル", "f54c0100"], "d": ["ボスニアから分かれた統治を築いたヘルツェゴヴィナ公ステファン・ヴクチッチ・コサチャの領土は、ボスニア王国の滅亡から3年後に大部分がオスマンの統治に移った。南部のトレビニェは1466年に「ほぼヘルツェゴヴィナ全域とともに」奪われた。ネレトヴァ橋の二つの小さな城の周りに築かれたモスタルも、ヘルツェゴヴィナの中心ブラガイの1466-1468年の征服の少し前に奪われたに違いない。1468-1469年のボスニア総括検地簿には「キョプリュリュ・ヒサル」の名で記録されている。公国の残りの城とともにヘルツェゴヴィナの征服が完了するのは1483年である。", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["第2次アルバニア遠征 - ファーティフ自らのスカンデルベグへの進軍", "9cdd2bfa"], "d": ["スカンデルベグの四半世紀を超える抵抗を砕くため、ファーティフ・スルタン・メフメトは1466-1467年に自ら指揮する大規模な遠征を行った。オスマン軍はアクチャヒサル(クルヤ)を包囲し、地域を押さえるためイルバサン(エルバサン)城を築いた。遠征はアルバニアの抵抗の背骨を折ったが、城を落とすことはできなかった。地域の完全な服属は、スカンデルベグの死後10年を要することになる。", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["アク・コユンルの先鋒部隊がビンギョル要塞をカラ・コユンルから奪った", "51b94cbc"], "d": ["ジャハーン・シャーがウズン・ハサンに対して行った遠征の最後の数週間に、アク・コユンルの先鋒部隊はビンギョル要塞を占領した。ジャハーン・シャーが1467年11月10日に殺されたことで、地域におけるカラ・コユンルの支配は終わった。", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["カラ・コユンル国の崩壊:ジハーン・シャーの殺害", "30bc6358"], "d": ["ウズン・ハサンに向けた遠征から冬の到来で引き返す途中に奇襲を受けたカラ・コユンルの君主ジハーン・シャーは、ビンギョルとクウの間を逃走中に殺された。この打撃の後、国家は立ち直れず、最後の君主ハサン・アリは1469年にウズン・ハサンの子ウウルル・メフメトに捕らえられて殺された。東アナトリア、アゼルバイジャン、イラクで1世紀近く君臨したカラ・コユンルの支配は、こうしてアク・コユンルに移った。", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["スカンデルベグの死 - アルバニアの抵抗の鎮静", "9158c35f"], "d": ["オスマンの宮廷で育ちながら、1444年のズラティツァの敗北の後に反乱を起こし、四半世紀を超えてアルバニアで抵抗したスカンデルベグは、身を寄せていたレジェで死んだ。ムラト2世とファーティフの時代にオスマン軍を幾度となく足止めしたこの抵抗は、彼の死により中心的な指導者を失った。教皇とヴェネツィアが支えたアルバニア戦線の崩壊により、オスマンは10年以内にアクチャヒサルとシュコドラを奪い、地域を最終的に領土に加えた。", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["カイセリにオスマンの統治が確立された:ゲディク・アフメト・パシャがカラマン侯国を終わらせた", "33cf35fc"], "d": ["ゲディク・アフメト・パシャが1474年にカラマン侯国を終わらせたことで、カイセリはオスマンの統治に入った。都市は、15世紀を通じてドゥルカディル侯国、ラマザン侯国、カラマン侯国の間で手が替わっていた。オスマンの統治によって、カイセリはカラマン・ベイレルベイ領のサンジャクの中心となった。", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["サモスが放棄された:ジェノヴァ(マオナ)の所有の終わり", "5bdc380c"], "d": ["TDVによれば、島は1475年以後に放棄された。1479年に征服王メフメト(ファーティフ)が島を征服して要塞を築かせた。", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["モルダヴィアのラコヴァ(ヴァスルイ)の敗北", "a1a74bf7"], "d": ["モルダヴィア公ステファン・チェル・マレは、ルメリア総督ハドゥム・スレイマン・パシャ率いるオスマン軍を沼沢地に誘い込んで大敗させた。ファーティフ時代で最も重い陸戦の敗北の一つであるこの敗北はヨーロッパで大きな反響を呼び、ステファンに十字軍世界での名声をもたらした。スルタンは翌年、報復のため自ら出征することになる。", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["アクデレ(ヴァレア・アルバ)の勝利 - モルダヴィア遠征", "45a66791"], "d": ["1年前のラコヴァの敗北の報復のため自ら出征したファーティフ・スルタン・メフメトは、オスマン軍とともにモルダヴィア軍をアクデレの地で大敗させ、侯国の中心スチャヴァに入った。しかし城は奪えず、食糧難、イェニチェリの間に広がった疫病、ハンガリーの準備のために軍は撤退を余儀なくされた。モルダヴィアの最終的な服属は、その後の年月と、1484年のキリアとアッケルマンの奪取によってようやく達成されることになる。", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["アクチャヒサル(クルヤ)の征服とアルバニアの完了", "559a79b4"], "d": ["スカンデルベグの死から10年後の1478年に、アクチャヒサル、ドリヴァスト、レジェ、ヤブヤクが占領されて、アルバニアの征服はおおむね完了した。長年オスマン軍に抵抗し、スカンデルベグの抵抗の象徴であったクルヤ城の陥落は、地域におけるヴェネツィア-アルバニア同盟の終わりを意味した。残るシュコドラは翌年に結ばれるイスタンブル条約でオスマンに譲渡されることになる。", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["タマン半島の編入", "4ef917b8"], "d": ["1475年のカッファ(ケフェ)とケルチの奪取の後、ファーティフ・メフメトがカフカス沿岸に送った艦隊は、アナパおよびコパとともに、タマン半島のジェノヴァ領マトレガ(タマタルハン)を占領した。これで海峡の両岸が掌握され、アゾフ海への入口が完全に管理下に入った。タマンは北カフカスへの門として、ケフェ・サンジャクに編入された。", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["サモスのオスマン統治への編入(ファーティフ)", "c877bc14"], "d": ["征服王メフメト(ファーティフ)はサモスを征服し、要塞を築かせ、検地を再編した。要塞は1483年にバヤジト2世によって政治的な理由で破壊させられた。", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["ロドス攻囲の失敗", "35a85c28"], "d": ["ファーティフ・スルタン・メフメトの命により、メスィフ・パシャ指揮下の160隻の艦隊が885年(1480年)の春にロドスを包囲し、島は3か月にわたり封鎖された。総長ピエール・ドービュッソン率いる聖ヨハネ騎士団は大きな損害にもかかわらず激しく抵抗した。885年ジュマーダー・アル=ウーラー月20日の最後の大攻撃も撃退されたため、艦隊は8月3日に撤退した。この失敗の後、都市の城壁は一から改築されてヨーロッパ最強の要塞となり、島はようやく1522年にカーヌーニーによって奪われることになる。", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["イカリア(Nikarya)が、ロドスの聖ヨハネ騎士団の統治に入った", "5cbc2669"], "d": ["サモスとキオスの間にあるイカリア(Nikarya)は、1481年から1521年までロドスの聖ヨハネ騎士団の統治下にあった。", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["イェニシェヒルの戦い - ジェム・スルタンの敗北", "c35abee2"], "d": ["ファーティフの死の後、王位を求めて動いた二人の兄弟はイェニシェヒル平原で対峙し、ジェム・スルタンは決定的な敗北を喫した。ブルサで18日間統治して自分の名で説教(フトバ)を読ませた王子は、敗北後、まずコンヤへ、次いでマムルーク朝領へ逃れざるを得なかった。イェニシェヒルはオスマン史上最も長引いた王家の危機を引き起こした。ジェム問題は14年間、オスマンの対ヨーロッパ外交を麻痺させることになる。", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["ヘルツェゴヴィナの併合", "bf247891"], "d": ["1463年のボスニアの征服の後も残っていたヘルツェゴヴィナ公国の領土は、段階的にオスマンの統治に移った。トレビニェとモスタルは1466年に奪われ、ヘルツェゴヴィナ・サンジャクは1470年に編成され、公国のアドリア海岸の最後の領土もヘルツェグ・ノヴィとともに1482年初めに征服されてサンジャクに加えられた。こうしてアドリア海の背後の山岳地帯はすべてオスマンのものとなり、ボスニアとヘルツェゴヴィナは一つの行政地理にまとまった。最後の公の子でオスマン宮廷に入り、のちに大宰相にまで昇ったのがヘルセクザーデ・アフメト・パシャである。", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["ザキントス(Zaklise)の年貢と引き換えでのヴェネツィアへの譲渡", "268a691a"], "d": ["征服王(ファーティフ)の時代の終わりにトッコ家から取られたイオニア諸島のうち、ザキントス(Zaklise)は、ジェム・スルタン問題に追われていた新しいスルタンが西方での平穏を求めて、ヴェネツィアに譲られた。島は、オスマンの君主権を認め、年500ドゥカートの年貢を払うヴェネツィアの統治に委ねられた。こうしてイオニア海におけるオスマンの直接統治はAyamavra(レフカダ)だけに残った。", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["ジェム・スルタンのロドスへの避難", "2228d6da"], "d": ["コンヤ包囲の試みも不調に終わったジェム・スルタンは、30人ほどの従者とともにアナトリアから逃れてロドスに着き、聖ヨハネ騎士団に儀礼をもって迎えられた。しかし客人としての待遇は間もなく虜囚に変わった。王子はまずフランスに、次いで教皇庁に引き渡され、ヨーロッパの政治の手中の切り札となった。バヤジト2世は兄弟の身柄の拘束の見返りに毎年の支払いを強いられ、オスマンの西方への軍事行動はジェムの死まで停止された。", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["オスマン-マムルーク戦争の開始(チュクロヴァ戦線)", "3fe3f0c7"], "d": ["ドゥルカディル家をめぐる影響力争いと、ジェム・スルタンがマムルーク朝領に避難したことが残した敵意により、1485年に二つのスンナ派大国の間で6年続く戦争が始まった。チュクロヴァのアダナとタルスス周辺で行われた戦闘で、両者は互いに優位に立てず、オスマン軍はいくつかの重い打撃を受けた。この戦争はオスマン-マムルーク関係における亀裂の最初の局面であり、30年後のヤヴズによるマルジュ・ダービクとリダニーヤの遠征で決着する過程の始まりである。", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["オスマン-マムルーク和平 - チュニスの仲介", "60dd6719"], "d": ["1485年に始まったオスマン-マムルーク戦争で両者は決定的な勝利を得られず、ハフス朝のチュニス君主ウスマーンの仲介により1491年に合意に達した。条約は国境をほぼ戦前の状態に戻し、二つのイスラーム国家の間の決着は一世代の間延期された。6年にわたる消耗戦は、バヤジト2世の慎重な外交政策と、東方への進出よりも内政の整備に重きを置いた主な理由の一つである。", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["スペインから追放されたセファルディムのユダヤ人のオスマンへの受け入れ", "5c2b5c24"], "d": ["グラナダの陥落の後、スペインで異端審問の迫害を逃れたユダヤ人の一部はオスマン領に避難し、さまざまな都市に入植させられた。オスマンの統治下でこのセファルディムの共同体は、望む場所に定住し、信仰を実践し、教育機関を開き、新しいシナゴーグを建てるという、それまで経験しなかった自由を得た。印刷、医学、財政の知識を携えてテッサロニキとイスタンブルの経済生活を変えたこの移住は、オスマンの寛容の秩序がヨーロッパで最も語られる例となった。", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["ジェム・スルタンの死 - 14年に及ぶ人質の終わり", "f6588b70"], "d": ["教皇庁からフランス王シャルル8世に引き渡されたジェム・スルタンは、1495年1月27日にローマを出発した後、カステル・カプアーナと呼ばれる地で死んだ。史料は教皇庁筋によって毒殺された可能性を記している。14年間、ヨーロッパ諸国の手にオスマンに対する脅しの切り札として置かれていた王子の死は、バヤジト2世の手をついに自由にした。実際スルタンはこれ以後ヴェネツィアに宣戦し、艦隊を最初の大きな勝利に導くことになる。", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["サピエンツァ(ゾンキオ)の海戦 - 地中海における最初の大規模な海軍の成功", "9754aaef"], "d": ["ジェム問題の終結で手が自由になったバヤジト2世は1499年にヴェネツィアに宣戦した。オスマン艦隊はサピエンツァ(ゾンキオ)沖でヴェネツィア艦隊を破り、地中海における最初の大きな海戦の勝利を収めた。この勝利により艦隊は、もはやヴェネツィアに海で対抗できることを宣言した。", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["ケファロニアとイタキの喪失", "60f0f687"], "d": ["モドンとコロンの占領で揺さぶられたヴェネツィアは、スペインと結んで反攻に出て、1479年からオスマンの手にあったケファロニアを包囲した。47日間の抵抗の後に要塞は陥落し、島はイタキとともにヴェネツィアに移り、300年にわたってオスマンの統治に戻らなかった。この喪失は、モレアで得たものをイオニアで返す均衡を生んだ。", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["ジョチ・ウルス(金帳汗国)の滅亡とクリムの台頭", "0d1dc515"], "d": ["最後の君主シェイフ・アフメト・ハン（1481-1502年）は、自国を陥った混乱から救うことができず、金帳汗国は1502年にクリム・ハンのメングリ・ギレイの一撃によって歴史から消えた。王位争いと分裂の結果、旧金帳汗国領にはクリム、カザン、ノガイ、アストラハン、シビルの諸ハン国が現れた。オスマンの保護下にあるクリムのこの勝利は黒海北方でのオスマンの影響を疑いないものにしたが、地域に生じた空白は次の世紀にモスクワが埋めることになる。", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["オスマン-ヴェネツィア戦争の終結と和平", "125b1526"], "d": ["1499年に始まり、サピエンツァ、レパント、モドン、コロンの喪失でヴェネツィアを揺るがした戦争は、1502年に和平で終わった。ヴェネツィアはモレアで最も重要な基地を失い、東地中海における通商特権を守る代わりにオスマンの優位を認めざるを得なかった。慎重とされたバヤジト2世の治世は、この戦争によってオスマンを地中海で初めて本格的な海軍国の地位に引き上げた。", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["シャーフクルの乱 - テケ地方からスィヴァスに及ぶキズルバシュの蜂起", "3beadca7"], "d": ["サファヴィー朝のプロパガンダのアナトリアへの影響で1510年に反乱を公然と起こしたシャーフクル・ババ・テケリは、1511年3月にアンタルヤの市場を襲い、4月にはキュタヒヤとその周辺でオスマン軍を破っていた。スィヴァス近郊で大宰相ハドゥム・アリ・パシャと交えた最後の戦闘で双方とも大きな損害を出し、大宰相も反乱の指導者も命を落とした。国家のアナトリアにおける権威を揺るがしたこの蜂起は、バヤジト2世の晩年の権力の空白をあらわにし、シェフザーデ・セリムの即位への進軍の最も強い根拠となった。", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["バヤジト2世の退位とヤヴズ・スルタン・セリムの即位", "c4cfab69"], "d": ["兄弟たちとの王位争いでイェニチェリの支持を背にしたシェフザーデ・セリムの圧力により、バヤジト2世は1512年4月24日に退位し、セリム1世が同日、9代目のオスマン君主として即位した。老スルタンは、生まれ故郷のディメトカへ向かう途中、チョルル近郊のアバラル村で918年ラビーウ・アル=アウワル月25日(1512年6月10日)に死去した。31年に及ぶ慎重で内向きの治世に代わって、8年で帝国の版図を倍にするヤヴズの時代が来た。", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["シニ(Sinj)要塞の征服", "83271ea5"], "d": ["ボスニア国境のオスマンの襲撃部隊は、ダルマチア内陸に延びるシニ（Sinj）要塞をハンガリー王国から奪った。これは、9年後にガーズィー・ヒュスレヴ・ベイによるクニンとその周辺の征服で広がるダルマチア国境線の初期の環であった。要塞は1686年にヴェネツィアに失われることになる。", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["イェニシェヒルの戦いとシェフザーデ・アフメトの排除", "e2ed15dd"], "d": ["ヤヴズ・スルタン・セリムは、王位の最強のライバルである兄シェフザーデ・アフメトを、ブルサ近郊のイェニシェヒル平原で破り、捕らえて排除した。これにより1511年から続いた兄弟の争いは終わり、アナトリアの内部分裂は終息した。セリムは背後を固め、サファヴィー問題に向かう自由を得た。", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["ヤヴズ・スルタン・セリムのタブリーズ入城", "dad2e227"], "d": ["チャルディランの勝利の後、オスマン軍はサファヴィー朝の首都タブリーズに入り、都市でスルタンの名でフトバが読まれた。セリムはここに1週間滞在し、タブリーズの芸術家とウラマーの一部をイスタンブルへ移住させた。この移住はオスマンの宮廷美術に深い影響を与えることになる。冬の接近とイェニチェリの不満により都市は放棄されたが、東方でのサファヴィーの優位は砕かれていた。地図上でこの日にオスマンに移った地が互いに隣接していないのは正しい:タブリーズは9日間の軍事占領である。エルズィンジャン平原は遠征中に無血で降伏し、その中央のケマフ城は1515年5月19日までサファヴィー側で抵抗した。スィイルトは、タブリーズでシャー・イスマーイールの獄から解放されたハサンケイフの領主ハリル・ベイがオスマンに服従してサファヴィー朝から取り戻した - その周辺のディヤルバクルは1515年まで、ハサンケイフは1517年までサファヴィーのままであった。", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["ムシュとビンギョル(チャパクチュル)がサファヴィー朝からオスマンの統治に移った", "b0a53b5a"], "d": ["チャルディラーンの後、東アナトリアがサファヴィー朝から取られたことで、ムシュはヒジュラ暦921年/1515年にオスマンの統治に入った。隣のチャパクチュル(ビンギョル)も同じ過程でオスマンに編入された。", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["ケマフ城のサファヴィー朝からの征服", "73fd8671"], "d": ["チャルディランからの帰途に冬をアマスヤで過ごしたヤヴズ・スルタン・セリムは、ユーフラテスの渡河点を押さえる堅固なケマフ城の征服をビユクル・メフメト・パシャに命じた。スルタンも自ら加わった包囲の末に城はサファヴィー朝の手から奪われ、東アナトリアの門が開かれた。この征服は、チャルディランの勝利を恒久的な領土の獲得に変える最初の具体的な一歩である。", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["トゥルナダー(Turnadağ)の勝利 - ドゥルカディル侯国、オスマンに服属", "fd879145"], "d": ["オスマン軍は、チャルディラン遠征の際に態度を曖昧にしたドゥルカディル侯アラーッデヴレ・ボズクルトを、ギョクスンとアンドゥルンの間のオルデクリの地で破り、アラーッデヴレはこの戦いで殺された。侯国はこの日には併合されなかった。アラーッデヴレの後、ドゥルカディル侯国の長にはヤヴズ・スルタン・セリムによってシェフスヴァルオウル・アリ・ベイが就けられ、マラシュ-エルビスタンを中心とする国はオスマンに服属する侯国として続いた。マムルーク朝との国境の緩衝地はこうしてオスマンの管理下に入り、2年後のエジプト遠征への道が開かれた。併合はアリ・ベイの殺害の後に行われることになる。", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["アーミド(ディヤルベクル)の征服とディヤルベクル総督領の設置", "a6867d5b"], "d": ["イドリース・ビトリースィーが地域のスンナ派クルド人ベイたちをオスマンの側につけた後、サファヴィー軍は長い包囲に耐えられず、アーミドの鍵はビユクル・メフメト・パシャに引き渡された。都市は新設のディヤルベクル総督領の中心とされた。こうして上メソポタミアの行政の核がオスマンの手に渡った。", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["ハルプトの征服 - ディヤルベクルへの道の開通", "564eb269"], "d": ["チャルディランの後に奪ったディヤルベクルをサファヴィーの包囲から救うため出発したカラマン総督ヒュスレヴ・パシャは、周辺を先にチェルケス・ヒュセイン・ベイが占領していたハルプト城を3日間の包囲の末に奪った。ユーフラテスの東でディヤルベクルへ至る道はこうして確保された。", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["コチヒサル(クズルテペ)の戦い - カラ・ハンの敗北", "9ea9e843"], "d": ["ビユクル・メフメト・パシャ率いるオスマン軍は、コチヒサル近くのデデ・ガルクン平原のコルク地で、サファヴィーの総督カラ・ハンを終日続いた野戦で破った。カラ・ハンの首は、スルタンの陣営に送られた。続いてオスマン軍はマルディン市に入ったが、数日で去った。サファヴィーの守備兵が守るマルディン城は1年後にようやく接収された。この勝利は、ヤヴズが南の国境を確保してエジプト遠征に向かうことを可能にした。同日に編入されたその他の地:パル、チェミシュゲゼク、シヴェレク。", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["ヤヴズ・スルタン・セリムのエジプト遠征のためのイスタンブル出発", "ac258b4b"], "d": ["ヤヴズ・スルタン・セリムは、表向きはサファヴィー朝に対する新たな東方遠征の準備として、イスタンブルを出発し、アクシェヒルを経て南に向かった。マムルーク朝のスルタン、カンスー・ガウリーがシャー・イスマーイールと接触してオスマンの東翼を脅かしたことが、目標をまもなく変えさせることになる。遠征は2年続き、オスマンを中東の帝国に変える大作戦の始まりである。", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["ザビードの奪取：オスマンの船乗りたちの紅海への最初の進出", "38740e0c"], "d": ["ポルトガルのインド洋での圧力に対し、マムルーク朝のスルタン、カンスー・ガウリーの要請で紅海に派遣されたオスマン出身の船乗りフサイン・ベイとサルマン・レイスは、艦隊でザビードを占領した。なおマムルーク朝の下で行われたこの作戦は、オスマン海軍の紅海-インド線における最初の事実上の存在である。1年後にエジプトがオスマンに移ると、この艦隊は直接イスタンブルに属することになる。", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["遠征の目標がマムルーク朝とアレッポであることの正式な宣言", "689e310d"], "d": ["ヤヴズ・スルタン・セリムは、カンスー・ガウリーがサファヴィー朝と協定して軍をアレッポに進めたことを受け、遠征の目標をマムルーク朝のスルタンとアレッポであると公然と宣言した。こうして二つのスンナ派国家の間で長年続いた隠れた競争は、公然たる戦争に変わった。この宣言は、マルジュ・ダービクへの4週間のカウントダウンを始めた。", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["アデン攻囲の失敗:ポルトガルに対する最初の紅海での試み", "8ffd46f2"], "d": ["サルマン・レイスとフサイン・ベイは、紅海のインド洋への門であるアデンを奪うため8日間にわたる攻囲を行ったが、都市の強力な防備の前に撤退せざるを得なかった。アデンを奪えなかったことは、ポルトガルに対する南方戦略を長年妨げることになる。この試みは、オスマンの海洋政策における最初の試練である。", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["ラマザン侯国のオスマンへの帰属", "cfaa3754"], "d": ["マルジュ・ダービクの勝利の後に行われた任命の際、アダナを中心とするラマザン侯国はマフムト・ベイに与えられ、オスマンの宗主権下に置かれた。マムルーク朝への臣従を離れた侯国は、廃止されるのではなく「オジャクルク」の地位で一族に委ねられた。ラマザン家はチュクロヴァの統治を、オスマンのサンジャク・ベイとして続けた。この特権的な制度は、ピール・マンスールが侯位を離れた1608年まで続いた。同日に編入されたその他の地:マラティヤ、タルスス、モスル、アンテプ。", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["アレッポ、ラッカ、デイルッゾールのオスマン支配への編入", "2088eb6a"], "d": ["マルジュ・ダービクの4日後、ヤヴズ・スルタン・セリムは抵抗を受けずにアレッポに入り、都市のモスクでは彼の名でフトバが読まれた。シリアの商業と行政の首都とされるアレッポがこれほど早く陥落したことは、地域でマムルーク朝の権威が崩れていたことを示す。都市の奪取により、ダマスクスへ、そしてそこからエジプトへ至る道が一気に開かれた。同日に編入されたその他の地:アンタキヤ、ラッカ、デイルッゾール。", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["アレッポのギョクメイダンでアッバース朝カリフ、ムタワッキル3世との会見", "22979f42"], "d": ["マルジュ・ダービクでマムルーク軍とともに捕虜となったカイロのアッバース朝カリフ、ムタワッキル3世は、アレッポのギョクメイダンでスルタンの御前に引き出され、ヤヴズ・スルタン・セリムは彼に大きな敬意を示した。1261年からマムルーク朝のスルタンの影で象徴的な地位にあったカイロのカリフ位は、この会見で事実上オスマンの保護下に移った。カリフはのちにスルタンとともにイスタンブルへ連れて行かれることになる。", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["トリポリ(トラブルスシャーム)とハマー、オスマンの統治下に入る", "a1e19a79"], "d": ["アレッポとハマーに続き、シリア沿岸のトリポリも抵抗せずにオスマンの統治に移った。東地中海で最も繁華な港の一つであった同市はダマスクスの海への門であり、絹と砂糖の交易の中心であった。その奪取により、ビラード・アッシャームの沿岸帯はすべて手を替えた。", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["ダマスクスのオスマン支配への編入", "2b844d91"], "d": ["アレッポの後、ハマーとホムスが降伏して前途が開けたヤヴズ・スルタン・セリムは、9月27日にダマスクスの前に達した。都市にはすぐに入らず外のマスタバの地に幕営を張り、到着の12日目に盛大な儀礼とともに入城した。ダマスクスに長く滞在してシリアの行政秩序を整え、ムヒッディーン・イブン・アラビーの墓廟を建てさせた。こうしてビラード・アッシャームの全域がマムルーク朝の統治を離れた。同日に編入されたその他の地:ベイルート。", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["トゥーマーンバーイ、カイロでマムルーク朝のスルタンとして宣言される", "6020d90d"], "d": ["マルジュ・ダービクで死んだカンスー・ガウリーの後、マムルークのエミールたちは、国家の最後のスルタンとなるトゥーマーンバーイを王位に就けた。チェルケス出身の新スルタンは、シリアを失い、国庫が尽き、火器を欠く国家を引き継いだ。それにもかかわらず、カイロの前に防衛線を築き、オスマンの進出に対する最後の抵抗を組織することになる。", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["ガザ(ハン・ユーヌス)の戦い:ジャーンビルディー・ガザーリーの敗北", "9f1eb8cb"], "d": ["ヤヴズ・スルタン・セリムは、4千人の先遣隊とともに大宰相ハドゥム・スィナン・パシャをガザに送った。トゥーマーンバーイによってダマスクス総督に任じられたジャーンビルディー・ガザーリーは、オスマンの先遣隊をガザ-ハン・ユーヌス線で止めようとしたが、大敗してエジプトに逃れた。パレスチナにおける最後のマムルーク朝の緩衝軍が解体したことで、シナイ砂漠への道は完全に開かれた。", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["ヨルダン川の東:アンマン、オスマンの統治下に入る", "9db62667"], "d": ["ガザの戦いの後、エジプト遠征の準備をしていたオスマン軍が南下するなか、ヨルダン川東方のアンマンもオスマンの統治下に入った。パレスチナの沿岸および内陸の都市(ヤッファ、ナーブルス、サイダ、アッカ、エルサレム)は、マルジュ・ダービクの後の1516年秋にすでに手を替えていた。これらの都市は4世紀にわたり、ダマスクス州のサンジャクとして統治された。", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["ヤヴズ・スルタン・セリムのエルサレム到着", "66d7bfad"], "d": ["マルジュ・ダービクの後に抵抗せずオスマンの統治に移っていたエルサレムに、ガザの戦いの後、ヤヴズ・スルタン・セリムが国の要人と軍とともに来た。スルタンは岩のドームとアクサー・モスクを訪れ、都市の聖なる地位を確認した。エルサレムはこの日から1917年12月まで、ちょうど4世紀にわたりオスマンの統治下に留まることになる。", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["ヤヴズ・スルタン・セリムのガザ入城とシナイ砂漠への進発", "2106bfc7"], "d": ["ハン・ユーヌスでジャーンビルディー・ガザーリーが敗れた（1516年12月21日）後、ガザは先遣隊の手にあった。スルタンは1517年1月2日にガザに入り、ここで先遣隊の長スィナン・パシャと合流し、軍はエジプト渡河の最後の準備をした。ガザからサーリヒーヤに至る水のないカティヤ（シナイ）砂漠では8行程を進み、水はラクダで運ばれることになった。この渡河は、遠征で最も危険で、兵站の面で最も困難な局面である。", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["スエズの奪取 - 紅海への門", "05f3324e"], "d": ["リダニーヤでの勝利の後、オスマン軍がカイロに入ると、紅海北端のスエズもオスマンの統治下に入った。マムルーク朝がインド洋へ艦隊を派遣した造船所兼港であるこの地は、ポルトガルに対する南方政策の拠点となった。スエズは、3世紀後に運河が開かれる線の北の口である。", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["オスマン軍のカイロへの最初の入城", "0a3f4f4d"], "d": ["リダニーヤの勝利の翌日、オスマン軍のカイロ入城が許可され、1月24日に部隊は都市に駐屯した。しかしこの入城は都市の完全な掌握を意味しなかった。トゥーマーンバーイは上エジプトに退き、マムルーク朝の抵抗はまだ折れていなかった。カイロの征服は一日ではなく、数週間にわたる血なまぐさい過程で完成することになる。", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["トゥーマーンバーイのカイロ急襲と3日間の市街戦", "b83b6ce6"], "d": ["上エジプトに退いていたトゥーマーンバーイは、7千人ほどの手勢とともに1月27-28日の夜に突然カイロに入って市内で抵抗を始め、オスマン軍を極めて苦しい状況に陥れた。3日間続いた激しい市街戦で、マムルーク軍は都市の大部分を一時的に手中に収めた。抵抗はオスマンの砲兵と増援部隊が投入されてようやく砕かれた。", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["ジャーンビルディー・ガザーリーのオスマン仕官", "a94ea459"], "d": ["リダニーヤの後にサーリヒーヤに退いた元マムルークのエミール、ジャーンビルディー・ガザーリーは、スルタンに申し出て助命を乞うた。ヤヴズ・スルタン・セリムは、エジプトとシリアの治安確立に役立つと考えて彼を召し抱えた。この選択は、オスマンがマムルークの人材を一掃する代わりに体制に取り込む政策の最初の大きな例である。", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["ヤヴズ・スルタン・セリムの盛大なカイロ入城とフトバの読誦", "6d98080c"], "d": ["市街戦の鎮圧後、スルタンは1517年2月15日に極めて華やかな式典とともにカイロに入り、モスクで彼の名でフトバが読まれた。カイロでオスマンのスルタンの名でフトバが読まれたことは、1250年から続いたマムルークの支配が法的に終わったことの宣言である。この日付は、エジプトの事実上の征服の象徴的な完成の瞬間とされる。", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["最後のマムルーク朝スルタン、トゥーマーンバーイのテッルージェでの捕縛", "7058e6ad"], "d": ["カイロを離れた後ナイル・デルタに潜んでいたトゥーマーンバーイは、彼をかくまったベドウィンに密告され、テッルージェ地方で捕らえられた。その捕縛はマムルークの抵抗の組織的な中心を消した。最後のスルタンは以後14日間、オスマンの手に留め置かれることになる。", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["トゥーマーンバーイのバーブ・ズウェイラでの処刑とマムルーク朝の終焉", "ad9820be"], "d": ["捕縛から14日後、トゥーマーンバーイはカイロの有名な門バーブ・ズウェイラで絞首され、遺体は後に叔父が建てさせたメドレセに葬られた。こうして1250年からエジプトとシリアを支配したマムルーク朝は正式に歴史から消えた。抵抗が砕かれたことで、上エジプト(サイード)のアスユートやアスワンなどの都市もオスマンの統治下に組み込まれた。", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["ポルトガル艦隊のジッダ襲撃とサルマン・レイスの防衛", "52322cf5"], "d": ["30隻ほどのガレー船とガレオン船からなるポルトガル艦隊がジッダを襲撃した。サルマン・レイスは都市の防衛を指揮して敵の上陸を阻み、ポルトガル船数隻を沈めた。この防衛は、メッカの港、ひいては巡礼路がキリスト教国の手に渡ることを防いだ。ジッダは数か月後、ヒジャーズの臣従によって正式にオスマンの統治に入ることになる。", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["アレクサンドリアの艦隊による接収 - エジプト征服の完了", "386878fe"], "d": ["リダニーヤからちょうど4か月、トゥーマーンバーイの処刑から36日後に、ジャーフェル・ベイ指揮下のオスマン艦隊が港に着くとアレクサンドリアはオスマンの統治に移り、ロゼッタやダミエッタといったデルタの港もこの過程で組み込まれた。エジプトの地中海への大きな港が、カイロの陥落から数か月後に、陸からではなく海から接収されたことは、征服が一度の戦いではなく地域ごとに完成されたことを如実に示している。アレクサンドリアはこれ以後、イスタンブルとカイロを結ぶ生命線の港となる。同日に編入されたその他の地:ロゼッタ(Reşîd)。", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["ヒジャーズの無血併合:メッカのシャリーフの子アブー・ヌマイイの忠誠", "c13b98c7"], "d": ["ヤヴズ・スルタン・セリムは当初、メッカとその周辺の占領のために軍を送ることを考えていたが、メッカのアミール、シャリーフ・バラカートが服従を表明したため、これを取りやめた。バラカートの12歳の息子アブー・ヌマイイは、父の贈り物とメッカの鍵を携えてカイロに来て、スルタンの御前に謁見した。こうしてヒジャーズは、リダーニーヤの戦いの自動的な結果としてではなく、5か月半後に、一発の弾も撃たれることなく、和平と忠誠の誓い(バイア)によってオスマンに併合された。同日に併合されたその他の地点:ターイフ。同日に手を離れたその他の集落:フルマ(ターイフ東方)、ラービグ、バドル。", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["「二聖都の奉仕者」称号の受諾とメディナでのフトバ", "63b32b59"], "d": ["メッカの使節団の二度目の謁見の後、ヤヴズ・スルタン・セリムは二聖都の保護を正式に引き受け、「ハーディム・アル=ハラマイン・アッシャリーファイン(二聖都の奉仕者)」の称号を用い始めた。シャリーフ・バラカートは送られた礼服を着てスルタンの名でフトバを読ませ、メディナの使節団もイスタンブルへ行くと、バラカートのエミール位は勅許状で承認された。スルタンは二聖都の人々に20万金貨と大量の食糧を送り、毎年繰り返されるスッレの慣習を始めさせた。同日に編入されたその他の地:ヤンブー、タブーク。", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["サルマン・レイスのオスマン仕官と紅海政策の引き継ぎ", "771da99a"], "d": ["ジッダをポルトガル人から守ったサルマン・レイスは、カイロに来てヤヴズ・スルタン・セリムの御前に出た。しばらく留め置かれたが、1519年にイスタンブルに召され、ポルトガルの脅威に対して30隻のガレー船と数隻のガリオット船を準備することを請け合った。この会見は、紅海とインド洋の政策がマムルークの遺産から引き継がれ、直接イスタンブルに結びつけられることの始まりである。オスマンはもはや地中海国家であるのみならず、大洋政策をも推進する勢力であった。", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["ヤヴズ・スルタン・セリムのカイロ出発とハイル・ベイの総督就任", "8cd4fb23"], "d": ["エジプトに約8か月滞在して行政・財政・軍事の秩序を整えたヤヴズ・スルタン・セリムはカイロを発った。マルジュ・ダービクで左翼を引き上げてマムルークの敗北を早めた元アレッポ総督ハイル・ベイは、エジプトの最初のオスマン総督として、カルアト・アル=ジャバルから統治を始めた。マムルーク出身の総督が選ばれたことは、新しい統治が地元の人々に異質に映らないようにするための意図的な移行政策であった。スルタンは帰路、最後のアッバース朝カリフ、ムタワッキル3世と、エジプトの卓越した芸術家や学者たちをイスタンブルへ連れて行った。", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["カイロのアッバース朝カリフ制の終焉 - 「移譲式」伝承", "1d357640"], "d": ["ヤヴズ・スルタン・セリムはエジプトを征服すると、マルジュ・ダービクで捕虜となった最後のカリフ、ムタワッキル3世・アラッラーをイスタンブルへ連れて来た。1261年からマムルーク朝のスルタンの影で権限なく存続してきたカイロのアッバース朝カリフ制はこうして終わった。これに対し、カリフ位がアヤソフィアで正式な式典によってヤヴズに譲られたという有名な伝承は、18世紀末のドーソンの著作に初めて現れ、ヤヴズ時代の史料にはまったく見られない。TDV『イスラーム百科事典』は式典を裏づける原史料がないことからこの伝承を作り話とみなすが、同時に、カリフ位の移転にシャリーア上そのような移譲式は必要なかったことも記している。", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["エルズルム、オスマンの統治に編入 - 東アナトリアでサファヴィーの影響力が砕かれる", "78d1be02"], "d": ["チャルディランの勝利(1514年)の後、地域でのオスマンの影響力は強まったが、エルズルムの完全な掌握はイランの影響力が砕かれるまで遅れた。都市はエジプト遠征の後の1518-19年にようやくオスマンの統治に編入された。エルズルムは1502年にシャー・イスマーイールがアク・コユンル侯国を滅ぼしたことでサファヴィーの支配に入っていた。16年に及ぶこの時期はこうして閉じた。1534年のイラクェイン遠征の際にエルズルム総督領が設置されることになる。1518-1519年の間にエルズルム地方とともにアシュカレもオスマンの統治に編入された(日付未確認)。", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["ジェラーリーの反乱の始まり:ボゾクのシェイフ・ジェラールの蜂起", "99bd8a99"], "d": ["ボゾク地方でシェイフ・ジェラールという人物がマフディーを名乗ってトカト周辺で蜂起した。反乱は鎮圧されたが、その名は1世紀にわたりアナトリアのあらゆる匪賊と蜂起運動の呼び名となった。ジェラーリー運動は、16世紀末にティマール制の崩壊と人口圧力が重なって、帝国で最も長く続いた国内治安問題に変わった。蜂起は、アナトリアで「大逃散(ビュユク・カチュグンルク)」と呼ばれる大規模な人口移動を引き起こした。", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["アルジェのオスマン国家への編入", "b8eba4c1"], "d": ["北アフリカでスペインの圧力に抵抗していたハイレッディン・レイスは、持ちこたえるためにイスタンブルに申し出てアルジェをスルタンに献上し、フトバはヤヴズ・スルタン・セリムの名で読まれた。こうしてアルジェは正式にオスマン領に編入され、ハイレッディンには総督の称号とともに兵と大砲が送られた。この編入は、オスマンの西地中海における数世紀続く海上支配の礎を築いた。同日に編入されたその他の地:コンスタンティーヌ、シェルシェル(Cherchell)、メデア(Titteri)、セティフ。", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["ヤヴズ・スルタン・セリムのチョルルでの死去", "9fe83744"], "d": ["8年で国土を2倍以上に広げたセリム1世は、1520年7月18日に新たな遠征のためイスタンブルを出たが、背中にできた大きな腫瘍のためチョルルから先へ進めなかった。医師たちの処置にもかかわらず病は重くなり、2か月続いた望みのない治療の後、926年シャウワール月8-9日(1520年9月21-22日)にこの地で没した。チャルディラン、マルジュ・ダービク、リダニーヤによってイランを食い止め、マムルーク朝を滅ぼし、カリフ位と二聖都の保護者の地位をオスマンにもたらした。残した男子は一人だけ:スレイマンである。", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["イカリア(Nikarya)島のオスマン統治への編入", "6afa972b"], "d": ["サモスとキオスの間にあるイカリア(Nikarya)は、1481年から1521年までロドスの聖ヨハネ騎士団の統治下にあった。島での最初のオスマン時代は1522年に始まり、1822年まで続いた。この時代には税の徴収と納付の責任はカイマカムが負い、他のエーゲ海の島々と同様に、地元の長老会議(デモゲロンティア)も存続し、時にオスマンの統治と衝突した。", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["ドゥルカディル侯国の併合 — マラシュを中心とするドゥルカディル州", "595c3c30"], "d": ["1515年のトゥルナダー敗北の後、オスマンに従属する侯国として続いていたドゥルカディルの国は、シェフスヴァルオウル・アリ・ベイがアルトゥコヴァで子供たちとともに殺されたことを受けて、直接オスマンの領土に編入され、マラシュを中心とする州とされた。侯国のボゾク地方は別個のサンジャクとしてオスマンの統治に結びつけられた。こうしてマラシュ、エルビスタン、ギョクスン、ギュルン、ザマントゥ、ダレンデの約2世紀にわたるドゥルカディル侯国の時代は閉じられ、マムルーク朝との国境にあった緩衝侯国は完全に消えた。", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["クニンの征服", "a46d3117"], "d": ["ボスニアのサンジャク・ベイ、ガーズィー・ヒュスレヴ・ベイのヒジュラ暦927から928年（1521年から1522年）の襲撃によって、クニン、スクラディン、オストロヴィツァをはじめとする一連のヴェネツィアの要塞がオスマンの統治に移り、国境は第二の山脈の向こうに押された。この征服の連鎖は、15年後のクリスの占領で完成するダルマチア・サンジャクの基礎を築いた。", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["騎士団の撤退:ボドルム、コス、ドデカネスの引き渡し", "ea01666e"], "d": ["ロドスの降伏条件により、聖ヨハネ騎士団は島の中心部だけでなく、200年間保持してきたすべての拠点を空けた。アナトリア海岸のボドルム（サン・ピエール）要塞と、コス島、カリムノス、レロスの島々は、こうして戦闘なしにオスマンの統治に移った。ロドスの陥落から2週間後に完了したこの引き渡しによって、エーゲ海の南東の隅におけるラテン人の存在は完全に終わった。", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["エジプトでの裏切り者アフメト・パシャの反乱", "b18bb805"], "d": ["大宰相の座を待ちながらエジプト総督に送られたアフメト・パシャは、カイロで自らを「アル=マリク・アル=マンスール・スルタン・アフメト」と宣言し、独立を表明した。反乱は短期間で鎮圧されてパシャは殺されたが、この事件は帝国で最も豊かな州における中央の統制の脆さを示した。これを受けてイブラヒム・パシャはエジプトに赴き、州の統治を再編する有名なエジプト法令集(カーヌーンナーメ)を作らせた。", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["北ボスニアの併合:ヤイツェとバニャ・ルカ", "8ec86cfa"], "d": ["モハーチの後、ハンガリーの防衛線が崩れると、ボスニアのサンジャク・ベイ、ガーズィー・ヒュスレヴ・ベイはヴルバス川流域に進軍し、ハンガリー王国の手に残る最後のボスニアの要塞を取った。ヤイツェとバニャ・ルカの陥落によって、ボスニア州は北でサヴァ川に達し、クロアチア戦線が生まれた。バニャ・ルカはまもなく州の第二の中心となった。", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["ブダの奪取とサポヤイへの引き渡し", "fba4f89b"], "d": ["ウィーン遠征の途上、オスマン軍はフェルディナントの手に渡っていたブダを包囲して奪い返し、都市をオスマンの保護下のハンガリー王ヤーノシュ・サポヤイに引き渡した。こうしてハンガリーをめぐるハプスブルク-オスマンの競合において、緩衝となる臣従王国のモデルが築かれた。この秩序は1541年まで続き、サポヤイの死後、ブダは直接オスマンの州とされることになる。", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["カーヌーニー、ドイツ遠征に出発 - カール5世への挑戦", "7c3d7055"], "d": ["ウィーン包囲が成果なく終わったことと、フェルディナントがブダを再び包囲したことの後、スルタンは今度は直接皇帝カール5世を野戦に引き出すため、イスタンブルから出発した。軍は8月に小さなギュンス城の抵抗に足止めされ、皇帝が出戦しなかったため、遠征は襲撃にとどまることになる。遠征は翌年のハプスブルクとの最初の和平の下地を整えた。", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["ドイツ遠征とギュンス(Kőszeg)の攻囲", "8aec937a"], "d": ["カーヌーニーはカール5世を野戦に追い込むため軍とともにオーストリアに進軍した。小さなギュンス城は25日間抵抗して軍の進出を遅らせた。皇帝が出戦しなかったため、騎兵(アクンジュ)がウィーン周辺を襲い、季節の進行により引き返した。遠征は領土の獲得をもたらさなかったが、ハプスブルクを交渉の席に着かせ、翌年の和平の下地を整えた。", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["イスタンブル条約 - ハプスブルクとの最初の和平", "b085767a"], "d": ["フェルディナントの使節コルネリウスを迎えたスルタンは休戦に同意し、オスマンとオーストリアの間で最初の公式な和平文書が成立した。条約によりフェルディナントは保持するハンガリー領に対し年貢を払うことを受け入れ、オーストリア大公は儀礼上、大宰相と同格とされた。この不平等な地位は、16世紀におけるオスマン外交の優越の主張をはっきり表すものであった。", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["カルスの占領と北東国境の開通", "742e3101"], "d": ["両イラク遠征(Irakeyn Seferi)の先鋒がエルズルムから東に向かうなか、ジョージアのアタベク国の手にあり、ティムール以来荒廃していたカルス要塞は、抵抗もなく受け取られた。都市は、アラス川の湾曲部とチルドゥルの間の通路を押さえるため、イランに開く北の門の鍵とされていた。この獲得は、30年後に設けられるカルス・ベイレルベイ領とコーカサス線の最初の環となった。", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["タブリーズへの最初の入城 — 両イラク遠征の開幕", "cf7ed4e3"], "d": ["大元帥(セルダール・イ・エクレム)の資格で先行したイブラヒム・パシャは、シャー・タフマースブが野戦を避けて内陸に退いたため、サファヴィー朝の首都タブリーズに抵抗なく入った。カーヌーニーも9月に都市に達したが、冬の到来と補給線が長くなりすぎたため、軍はバグダードの方向に向かい、タブリーズは長く保持できなかった。チャルディラーンの後、二度目に占領されたこの都市は、オスマンが東方で占領するのは易しく保持するのは難しいと学んだ場所となった。", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["バルバロスのチュニス征服", "d8754216"], "d": ["海軍総司令官バルバロス・ハイレッディン・パシャは、艦隊でイタリア沿岸を攻撃した後チュニスに向かい、ハフス朝の君主ムーレイ・ハサンを逃亡させて都市に入った。チュニスの奪取は、シチリア海峡を押さえる位置ゆえに、西地中海の力の均衡を一気にオスマン有利に変えた。しかしこの支配は長続きせず、カール5世が翌年、大艦隊で応じることになる。", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["チュニスのカール5世への喪失", "a691f0f8"], "d": ["カール5世は、ジェノヴァと教皇庁の艦隊に支援された大遠征でハルク・アル=ワード(ラ・グレット)を陥落させた後、チュニスを奪い、ムーレイ・ハサンをスペインの保護下に王位に復した。都市にはスペイン守備隊が置かれ、オスマンの中部地中海での進出は一時的に止められた。チュニスの最終的な征服は、40年後の1574年にようやく可能となる。", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["ガーズィー・ヒュスレヴ・ベイのサヴァ川沿いの作戦：ボスニア・ブロドとヤセノヴァツ", "3740ec83"], "d": ["1528年のヤイツェとバニャ・ルカの占領の後も、サヴァ川沿いの要塞はしばらくハプスブルク王冠に属するクロアチア・スラヴォニア国境に残った。1536年に三度目のボスニアのサンジャク・ベイとなったガーズィー・ヒュスレヴ・ベイは、同年にポジェガとその周辺を占領するとともに、サヴァ河岸のブロドとヤセノヴァツの要塞もオスマンの統治に加えた。こうしてボスニアの北の国境はサヴァに達した。地域は2年後のドゥビツァの占領で完成した。", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["マクブル・イブラヒム・パシャの処刑", "348aa7b8"], "d": ["13年間大宰相を務め、カーヌーニーの最も親しい友であり国家の事実上のナンバー2であったイブラヒム・パシャは、断食明けの食事(イフタール)に招かれた宮殿で、何の理由も示されないまま絞殺され処刑された。イラクェイン遠征での態度、「セラスケル・スルタン」の称号の使用、宮廷内の力関係が死に影響したとされる。この処刑は、オスマンの中央政府において大宰相に絶対の安全がないことを示す転機である。", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["クリス城の征服とダルマチア・サンジャクの設置", "6ffd4ebf"], "d": ["ガーズィー・ヒュスレヴ・ベイの家令(ケトヒュダー)で、クロアチア出身の改宗者ムラト・ベイは、スプリットのすぐ北にある戦略上の要衝クリス城をヴェネツィアから奪った。征服の直後、クリスは周辺を含む新しいサンジャクとカザーの中心とされ、このサンジャクの境界はオスマン領クロアチアの枠組みをおおむね描いた。クニンから15年後に来たこの征服は、ダルマチア内陸の行政の骨格を完成させた。", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["コルフ攻囲とヴェネツィアとの戦争", "11af95bd"], "d": ["プーリア(アプリア)遠征の後、オスマン軍はコルフに上陸し、島の堅固なヴェネツィアの城を包囲した。城の険しい構造、大きな損害、季節の条件のため、9月6日に封鎖を解いて撤退した。攻囲は成果なく終わったが、ヴェネツィアとの間に始まった戦争は、エーゲ海とアドリア海の多数の島のオスマンへの編入と、翌年のプレヴェザの勝利に終わった。", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["バルバロスのエーゲ遠征:ヴェネツィアが直接統治する島々の占領", "1b32ed96"], "d": ["コルフ島の包囲から戻った艦隊は、ヴェネツィアに戦争が宣言されていたことを利用して、エーゲ海で公国にではなく直接ヴェネツィアに属する島々を一つずつ受け取った。アイギナは激しい抵抗の後に占領され、クエリーニ家の手にあったアスティパレアとカルパトス、カソスは降伏し、修道院の統治下にあったパトモスもオスマンの保護を受け入れた。ナクソス公国は年貢を課されたうえでそのまま残された。その併合は1566年を待つことになる。", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["バルバロスの北エーゲ遠征:スキロスと北スポラデス諸島の占領", "20ab688e"], "d": ["プレヴェザへ向かう途上で、艦隊は、イスタンブル征服後にヴェネツィアに逃れていた北エーゲ海の島々を一つずつ受け取った。エヴィア島の北のスキロスと、テッサロニキ湾の口を押さえるスキアトス、スコペロス、アロニソスがこうしてオスマンの統治に入った。これらの島は、エヴィア島が1470年に占領されていたにもかかわらずさらに68年間ヴェネツィアの手に残っていた、北エーゲ海最後の空白を埋めた。", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["アデンの占領とイエメン海岸の併合", "e7d46d8f"], "d": ["インド遠征のためスエズから出た艦隊は、紅海の安全を確保せずに大洋に出ることはできないため、まずイエメン海岸に向かった。ハドゥム・スレイマン・パシャは1538年8月3日にアデン港に入った。ポルトガル人に傾いていたターヒル朝の君主アーミル・ブン・ダーウードは提督の旗艦に連れてこられて処刑され、都市には500人の守備隊が置かれた。同じ遠征の間に、モカと海峡を支配するカマラン島とファラサン島も引き渡され、イエメン・ベイレルベイ領の礎が築かれた。こうしてオスマン帝国は初めてバブ・エル・マンデブ海峡の北岸全体を掌握した。サナアと内陸部はさらに9年待たねばならなかった。", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["モルダヴィア遠征とブジャク(ベンデル)地方の併合", "90a88a56"], "d": ["オスマンへの義務を果たさなかったモルダヴィア公ペトル・ラレシュに対する遠征でスチャヴァが占領され、ヤシの町はクリム・ハンのサーヒブ・ギレイによって略奪された。スルタンはチェキルゲ・ステファンを公位に就け、ベンデルとともにブジャク(南ベッサラビア)地方を直接オスマン領に編入した。この併合は、黒海北西岸をオスマンの内海に変える環の一つとなった。モルダヴィアはすでにオスマンに服属する公国であった。この遠征は土地を外国の国家から取ったのではなく、ベンデルとブジャクの内政を公から取ってスルタンに直接結びつけただけであり、公国の残りは服属の地位を保った。同じ構造は1484年のキリアとアッケルマン、1713年のホティンでも繰り返されることになる:国境の城塞は直接、内陸は服属。", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["ナフプリオ(Anabolu)の協定による引き継ぎ", "104d0937"], "d": ["プレヴェザの後、3年続いたヴェネツィアとの戦争は、共和国がモレアに残る最後の二つの要塞を手放すことに同意して終わった。包囲では奪えなかったナフプリオ(Anabolu)とモネンヴァシア(Benefşe)は、30万ドゥカートの戦争賠償に加えて、交渉の席でオスマン帝国に譲渡された。モレア半島はこうして、ヴェネツィアの足跡が一つも残らない形でまとまった。", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["セゲドのオスマン統治への編入とセゲド・リヴァーの編成", "019aa000"], "d": ["ブダにおけるオスマンの統治が1541年に完全に確立された後、セゲドの有力者たちはフェルディナント1世の支配を受け入れ、武装防衛の準備をした。ブダのベイレルベイ、キュチュク・バーリー・パシャは1543年の初めに都市の指導者たちを呼び寄せて反逆を理由に処刑させ、続いて都市を占領するために部隊を送った。このときセゲド・リヴァー（サンジャク）が編成され、最初のサンジャク・ベイにはバーリー・パシャの息子デルヴィシュ・ベイが任命された。リヴァーは当初ドナウ川とティサ川の間に広がっていた。", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["ヴァルポ、シクローシュ、ペーチの征服", "2ca030a3"], "d": ["ブダの併合の2年後に出陣したハンガリー遠征の最初の目標は、新しい州のドラヴァ川とドナウ川の間の南側面を確保することであった。ヴァルポ要塞とシクローシュ要塞が占領された後、バラニャ地方の中心ペーチが降伏した。都市はオスマン・ハンガリーで最も人口が多く最も整備された中心地となり、歴史家イブラヒム・ペチュイ（ペーチ出身のイブラヒム）の名もここに由来することになる。", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["エステルゴムとセーケシュフェヘールヴァールの征服", "efca9e05"], "d": ["カーヌーニーが自ら出たハンガリー遠征で、2週間半の包囲の後、ハンガリー王国の宗教的中心で大司教座の都市エステルゴムがオスマンの統治に入った。続いてハンガリー王たちの戴冠の都市セーケシュフェヘールヴァール（イストルニ・ベオグラード）も奪われ、ブダ州の防衛帯が完成した。エステルゴムは1595年までドナウ線の要衝の城としてオスマンの手に残ることになる。", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["ブダの北と西の防衛帯：ヴァーツ、ハトヴァン、シモントルニャ", "733ee5ce"], "d": ["エステルゴムとセーケシュフェヘールヴァールが取られた後、ブダのベイレルベイは、首都を取り巻く要塞の環を完成させるため、スルタンの遠征なしに行動を起こした。ドナウの湾曲部にあるヴァーツ、アルフェルドの門であるハトヴァン、シオ川線のシモントルニャが一つずつ引き渡された。この静かな年の獲得は、ブダを辺境の都市から、140年持ちこたえる州の中心へと変えた。", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["バスラの併合とペルシア湾への進出", "02f87c11"], "d": ["バグダード征服（1534年）の際にバスラの君主ラーシド・ブン・マガーミスはカーヌーニーへの服従を表明し、1538年には都市の鍵を送っていた。後を継いだシェイフ・ヤフヤーがオスマンに敵対すると、バグダードのベイレルベイ、アヤス・パシャが陸から、モスルのサンジャク・ベイが120隻の船でユーフラテスから進軍した。アヤス・パシャは1545年12月26日にバスラに入り、都市はベイレルベイ領の中心となった。シャットゥルアラブの河口にあるこの港は、ポルトガルがホルムズから支配していたペルシア湾にオスマンが開いた門であり、1555年のアマスヤ条約でイランもこの状況を承認した。", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["サナアとイエメン内陸の征服", "d31ded85"], "d": ["ターイズに続いてサナアも取られ、国の全体がベイレルベイ領に結びつけられた。しかし険しい地形と宗派の違いのため、この支配は決して安楽なものにはならなかった。イエメンは、オスマンにとって絶えず兵を飲み込む戦線となった。", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["ターイズの征服", "d4509df9"], "d": ["9年前には海岸の帯状地帯だけで満足していたイエメンで、ザイド派のイマームたちが山がちの内陸部で次第に力を強めたため、オズデミル・パシャの軍は高地に上ってターイズを占領した。", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["イスタンブル条約 - ハプスブルクとの5年間の和平", "41f81773"], "d": ["オスマンとハプスブルクの間で5年期限の和平が結ばれ、フェルディナントは保持するハンガリー領に対し年3万ドゥカートを支払うことを受け入れた。条約は、ハンガリーが三分されている事実上の状態を法的に追認した。西部戦線がこれで安全になったことで、カーヌーニーにイランへの新たな遠征を組織する余地が生まれた。", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["第二次イラン遠征とタブリーズの再占領", "e82365df"], "d": ["シャー・タフマースブに反旗を翻してイスタンブルに逃れていた弟のアルカース・ミールザーの勧めで出陣した遠征で、軍は二度目にタブリーズに入った。サファヴィー朝は再び野戦に入らず、土地を焼いて退いたため、都市には数週間しかとどまれなかった。遠征は、タブリーズが保持できないことを決定づけ、オスマンの戦略を恒久的な国境線を築くこと、すなわちヴァンの要塞化へと向かわせた。", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["ヴァンの征服と東部国境の固定", "fc8f930b"], "d": ["タブリーズからの帰途に包囲されたヴァン要塞は、湖の東岸の岩の上にそびえる立地によって、地域の疑いなき鍵であり、短い包囲の後に降伏した。都市はただちにベイレルベイ領の中心とされ、エルジシュ、アディルジェヴァズ、ハッキャーリのサンジャクがここに結びつけられた。タブリーズと違って、ヴァンは保持され、400年にわたってオスマンの東方における最も進んだ恒久的な陣地として残った。", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["ハサーとカティーフの併合 — ペルシア湾のアラビア側の海岸", "f6701e60"], "d": ["バスラの占領の後、湾の西岸でポルトガルの前進拠点となっていたカティーフが占領され、内陸のハサーのオアシス群とともに新たなベイレルベイ領が設けられた。バーレーンとホルムズに向けた作戦の出発点はここであった。オスマン帝国はこうして、アラビア半島の紅海とペルシア湾の両方の海岸で同時に発言権を持つことになった。", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["シャフラズールの喪失 — アルダラーンの君主ソフラーブがサファヴィー朝に傾いた", "5600efc9"], "d": ["両イラク遠征の際（1535年）にオスマンの統治を承認していたシャフラズール地方は、ザルム要塞に拠るアルダラーンの首長ビゲ・ベイの統治下にあった。ビゲ・ベイが1550年に死ぬと、ザルム要塞を奪って侯国を支配した弟のソフラーブは、サファヴィー朝に向かってオスマンへの服従から離れ、シャフラズール地方はこうしてオスマンの影響を出た。地域は、ナヒチェヴァン遠征のさなかの1554年にザルム要塞が包囲・占領されることで、ようやく取り戻された。", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["アルダハンとチルドゥル盆地の占領", "14c9eb76"], "d": ["エルズルムのベイレルベイは、サファヴィー朝との戦争のさなか、ジョージアのアタベクたちのクル川湾曲部の領地に向かい、アルダハンとチルドゥル周辺をオスマンの統治に結びつけた。カルス・アルダハン線はこうして一体となり、北東でジョージアに開く高原が統制下に置かれた。地域の最終的な行政体制は、27年後に設けられるチルドゥル州で完成することになる。", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["ソコルル・メフメト・パシャのドナウ渡河 — トランシルヴァニア戦争の開始", "38fde931"], "d": ["トランシルヴァニア王の幼いヤーノシュ・ジグモンドの後見人である修道士マルティヌッツィが引き起こした混乱と、トランシルヴァニアがバナトの要塞をフェルディナントに譲ったことを受けて、新たな遠征が必要と判断され、指揮はルメリアのベイレルベイ、ソコルル・メフメト・パシャに委ねられた。軍はマルティヌッツィの引き延ばしの努力にもかかわらずドナウを渡り、ベチェ、ベチュケレク、チャナード、リポヴァを占領したが、ティミショアラの包囲は11月16日に寒さのため解かれた。こうしてハンガリーで新たなオスマン・ハプスブルク戦争が始まった。", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["リポヴァ(Lippa)の町がカスタルドのオーストリア軍の手に渡った — 要塞は12月5日に降伏", "a0e1ff0d"], "d": ["ソコルル・メフメト・パシャが1551年10月に取ったリポヴァを、カスタルド将軍の軍が11月4日に包囲した。2日後に町はオーストリア人の手に渡った。ウラマ・パシャは5000人の守備隊とともに要塞をさらに9日間守り、1551年12月5日に合意のうえで出た。ティミショアラが1552年に陥落するまで、リポヴァはハプスブルクの手に残った。", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["ティミショアラから派遣された部隊による南バナトの小城塞の掌握 — ヴルシャツ、ハラム、ケヴェ", "edca0921"], "d": ["ティミショアラがオスマン軍に降伏した後、包囲軍から分かれた部隊はバナトの小さな城塞（パランカ）に向かった。バーンラキ（Bánlaky）の叙述によれば、ヴルシャツ、ファチェト、メハディア、チャーコーヴァール、ハラムヴァール、ケヴェの各パランカがこれらの部隊に掌握された。こうしてドナウ河岸のハラムもオスマン帝国の手に入った。", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["ソルノクの征服とエゲル包囲の失敗", "a7156e8f"], "d": ["ティミショアラの占領後に合流した二つのオスマン軍は、ティサ川沿いのソルノクを、傭兵守備隊が要塞を放棄したためほとんど戦闘なしに占領した。続いて包囲されたエゲル要塞は、ドボー・イシュトヴァーン率いる2000人の守備隊の38日間の抵抗の前に落とせず、軍は冬が迫ると退いた。同じ遠征で一つの要塞が容易に落ち、もう一つが持ちこたえたことは、ハンガリーで国境がもはやオスマンに有利に自ずと進まないことを示す最初の明白な徴候であった。", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["オスマン-フランス同盟 - フランス艦隊のオスマン指揮下への編入", "a8e01b22"], "d": ["1553年2月1日付の条約により、フランス艦隊はオスマン艦隊の指揮下に置かれ、スペインに対して西地中海での共同作戦が想定された。条約の後、トゥルグト・レイスは1553年6月15日に45隻のガレー船でフランスを支援するため出征した。これは、1536年のカピチュレーションの通商の土台を軍事協力に移した最初の公式な同盟条約であった。", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["シェフザーデ・ムスタファのコンヤ・エレーリスィでの処刑", "dec36858"], "d": ["ナフチヴァン遠征のために集まった軍に加わろうと父の幕舎に入ったシェフザーデ・ムスタファは、御前に出ようとしたところで死刑執行人と出会い、絞殺された。軍内で深く愛されていた世継ぎ候補の殺害はイェニチェリの間に深い怒りを生み、リュステム・パシャは大宰相の職を解かれた。この事件は、オスマンの王子をめぐる政治の最も議論を呼ぶ断絶の一つとして、文学と民衆の記憶に残った。", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["イブリムとヌビアの国境の南への移動", "c57d5d77"], "d": ["エジプト・ベイレルベイ領の南の国境は、ナイル川上の岩の岬の上にそびえるイブリム要塞がオズデミル・ベイの手で要塞化され、下ヌビアがオスマン・エジプトに完全に編入されたことで、第二急流の向こうへと移された。（イブリムのオスマン行政組織はエジプト征服の直後に設けられていた。地図ではイブリムは1517年からオスマン領として表示される。この年は近似であり、史料は年を示さない。）要塞はヌビアからの襲撃に対する防壁であると同時に、センナールに通じる金と奴隷の道の管制点でもあった。ここに置かれたボスニア人の守備隊は非常に長く続き、その子孫は300年後にもまだ要塞にいた。史料はイブリムがオスマンの統治に入った時期について二つの異なる叙述を与える。TDVのスーダンの項は下ヌビアのオスマン・エジプトへの編入を16世紀半ばのオズデミル・パシャの作戦に結びつけるが、ヌビアの項はワーディー・ハルファまでの地域とイブリムの行政組織が1517年の征服の直後に設けられたと記す。イブリム・サンジャクは1573年7月26日にハベシュ州に結びつけられた。", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["ベジャイア(Bicâye、ブージー)のスペインからの奪取", "49691cda"], "d": ["43年間スペインの手にあり、アルジェとコンスタンティーヌの間の海岸を二つに分けていたベジャイアは、陸と海から包囲された後に降伏した。要塞の陥落によってアルジェ・オジャクの海岸はオランまで途切れなく続くことになった。スペインではこの喪失が非常に大きな憤激を呼び、要塞を引き渡した司令官アロンソ・デ・ペラルタは故郷で処刑された。", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["ゼイラのハベシュ州への編入", "7bbf369a"], "d": ["ハベシュ州の南端、アデン湾のアフリカ側海岸にあるゼイラ港がオスマンの統治に結びつけられた。アダル・スルタン国の海に開く門であるこの都市は、バブ・エル・マンデブの外へ出る船にとって最後の補給地点であった。ゼイラの編入によって、オスマン帝国のアフリカにおける国境は最南端に達した。", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["コンヤ王子たちの戦い", "1c8de387"], "d": ["王位争いに入ったシェフザーデ・バヤジトは約3万の兵でコンヤの前に来たが、2日続いた戦闘で弟のシェフザーデ・セリムに敗れた。敗走したバヤジトはアマスヤ経由でイランへ、シャー・タフマースブのもとへ逃れた。この戦いは、カーヌーニーの晩年における王位継承の危機を対外政策の問題に変えた。", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["ジェルバ海戦の勝利", "c7b905c1"], "d": ["ピヤーレ・パシャ指揮下のオスマン艦隊は、トリポリを奪い返すために集まったスペイン-ジェノヴァ-マルタの連合艦隊を、ジェルバ沖で二つに分ける機動で壊滅させた。連合軍は艦隊の大部分を失い、島の城もまもなく陥落した。ジェルバは、プレヴェザに次いでオスマンの地中海での優位を決定づけた二つ目の大海戦の勝利とされる。", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["シェフザーデ・バヤジトのカズヴィーンでの処刑", "a759de14"], "d": ["イランに逃れたシェフザーデ・バヤジトは、長い交渉の末にシャー・タフマースブからオスマンの使節団に引き渡され、4人の子とともに絞殺された。引き渡しの見返りにサファヴィー朝は重要な物質的譲歩と国境の保証を得た。この処刑により、セリム2世の即位を妨げる最後の障害が除かれ、アマスヤ条約の和平秩序が守られた。", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["キオスのジェノヴァ人からの奪取", "a4559b96"], "d": ["200年にわたりジェノヴァのジュスティニアーニ家に属する交易植民地として統治され、オスマンに年貢を払っていたキオスは、年貢を滞らせたことと敵の船に港を提供したことを理由に、ピヤーレ・パシャによって一発の弾も撃たれずに受け取られた。キオスとプサラとともに、エーゲ海東岸における最後のジェノヴァの存在も清算された。キオスの人々のマスティックの生産と特権は保たれたまま、島は地中海諸島州（ジェザーイリ・バフリ・セフィード）に結びつけられた。", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["ナクソス公国の併合 — キクラデス諸島の全域", "68f0ec0b"], "d": ["1207年から続き、1537年からオスマンに年貢を払っていたラテン系のナクソス公国は、最後の公ジャコモ・クリスポが民を虐げたとして寄せられた訴えを根拠に廃止された。ナクソス、パロス、ミロス、アンドロス、シロス、ミコノス、イオス、アモルゴスと、その周辺のキクラデス諸島のすべてが一つの決定で直接オスマンの統治に置かれた。カーヌーニーは島々の統治をしばらくヨセフ・ナシに与えた。3世紀半に及んだラテン人の支配は、こうしてエーゲ海の中央で終わった。", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["イエメンの反乱とコジャ・スィナン・パシャのイエメン遠征", "c8218d8e"], "d": ["ザイド派イマームのムタッハルは、強制的に税が取り立てられたことを理由に蜂起し、オスマンの統治をイエメンの大部分から一掃した。イスタンブルから送られたコジャ・スィナン・パシャは、1568-1570年に行った作戦で、長い包囲の末にカウカバーンを奪い、地域のオスマン支配を再建した。遠征は、紅海の南の門とインド洋交易路の管理を保つうえで死活的に重要であった。", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["アチェ・スルタン国との防衛同盟とインド洋への援助", "8e835f24"], "d": ["ポルトガルの攻撃に対してカーヌーニーの援助を求めたアチェの使節たちは、スルタンのシゲトヴァールでの死去を受けて忠誠をセリム2世に捧げ、彼との間に防衛条約が結ばれた。スルタンはアレクサンドリアから大砲、銃、弾薬、職人を送るよう命じ、インド洋へ派遣される17隻の軍艦が準備された。イエメンの反乱の拡大が艦隊の出発を妨げたが、アチェに届いたオスマンの砲兵と職人は地域に永続的な痕跡を残した。", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["キプロス上陸:リマソルの占領", "9074ccc9"], "d": ["島に上陸したオスマン軍は、大きな抵抗に遭わずにリマソルを占領し、翌日ラルナカに向かった。地元の住民がヴェネツィアの統治に不満を持ち、オスマン軍に協力したため、ラルナカでも本格的な抵抗には遭わなかった。ラルナカの港（トゥズラ）は兵と装備の上陸基地とされた。ヴェネツィアは防衛をニコシアとファマグスタに集中させていた。パフォスの総督は、ニコシアが陥落した後にようやく総司令官への服従を表明した。", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["ニコシアの征服", "413d866b"], "d": ["1570年7月25日に始まり45日続いた包囲の後、キプロスのヴェネツィア統治下の首都ニコシアはオスマン軍に降伏した。島の中心の陥落は、ヴェネツィアの抵抗をファマグスタ城に押し込めた。征服は西欧で大きな反響を呼び、教皇の主導による神聖同盟艦隊の結成へ至る過程を加速させた。", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["キレニアの降伏 — キプロスの北岸", "39fdeea5"], "d": ["ニコシアが9月9日に虐殺を伴って陥落したことで、キプロス北部の抵抗は砕かれた。五本指山脈の向こうのキレニア要塞は、首都の運命を知ると8日後に条件付きで降伏し、守備隊は島から出ることを許されて送り出された。島でヴェネツィアの旗はファマグスタにだけ残り、それもさらに11か月持ちこたえることになる。", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["レパント後の艦隊の再建", "db51fe44"], "d": ["レパントの惨敗の後、海軍総司令官に任じられたクルチ・アリ・パシャの最初の仕事は、大きな損害を受けた艦隊の再建であり、造船所は1571-1572年の冬を通して休みなく稼働した。1572年6月、約250隻のガレー船と300隻の志願のレイスのガレー船からなる新しい艦隊が地中海に出た。この迅速な立ち直りは、レパントがオスマンの海軍力を恒久的に砕くことはなかったことを示した。", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["ヴェネツィアとのイスタンブル条約 - キプロスの承認", "4d08ef50"], "d": ["神聖同盟の解体により孤立したヴェネツィアは、オスマンと単独で和平を結び、キプロスがオスマンに属することを正式に認め、戦争賠償金を払うことを受け入れた。条約は、レパントの勝利がキリスト教世界に政治的な利益をもたらさなかったことを明白にした。ヴェネツィアはこれ以後70年間、オスマンと直接戦争することを避けることになる。", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["セリム2世の死去", "c289f5ee"], "d": ["セリム2世は転倒の後、2か月ほど御前会議に出られず、死去した。その死は、マニサにいた長子ムラトがイスタンブルに来るまで12日間、宮殿で秘匿された。死去の日については史料が分かれる:セラーニキーは12月15日とし、ゲルラハ、メフメト・ブン・メフメト、ジェナービーは12月13日とする。", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["セリム2世の死の公表とムラト3世の即位", "84334d70"], "d": ["セリム2世の死と、マニサから呼び寄せられたムラト3世の即位は、1574年12月22日に正式に公表された。新しいスルタンは21年間王位に留まり、その治世は東方での長いイラン戦争、西方での長期戦争の前夜、そして内政での貨幣の品位低下(アクチェの悪鋳)で記憶されることになる。ソコルル・メフメト・パシャの1579年の死まで、国家の運営では旧来の秩序が続いた。", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["ワーディー・アッサイル(カスル・アル=カビール)の戦い - オスマンの支援を受けたアブド・アルマリクがポルトガル軍を壊滅させる", "21280dac"], "d": ["オスマンの支援でモロッコの王位に就いたアブド・アルマリクは、ポルトガル王セバスティアンの大軍をワーディー・アッサイルで壊滅させた。戦いで三人の君主が同時に死んだため、西欧の史料では「三王の戦い」と呼ばれる。ポルトガルの軍事力は崩壊し、国はまもなくスペインの手に渡った。アブド・アルマリクも戦いで死に、後を継いだ弟アフマド・アル=マンスールは勝利を使節団でイスタンブルに伝えた。両国の関係は貢納や臣従ではなく、使節と贈り物の交換の水準にとどまり、まもなく贈り物の問題で緊張した。", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["デルベントの人々のララ・ムスタファ・パシャへの服従の表明 — 鉄門（デルベント）のオスマン統治", "9c55aeff"], "d": ["シルヴァン遠征の間、デルベントの人々から7人の使節団が、エレシュにいた総司令官ララ・ムスタファ・パシャのもとに赴いて服従を表明した。コーカサスの壁とカスピ海の間の狭い通路を塞ぐデルベント（鉄門）は、北からの陸路の必須の通路として、シルヴァンの保持において鍵となる役割を果たした。オスマンの支配はここで1607年まで続いた。", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["シルヴァンの征服:シェマハの占領", "9afae4c1"], "d": ["チルドゥルの勝利の後にコーカサスに開いた軍は、サファヴィー朝のカスピ海沿岸で最も豊かな州であるシルヴァンに入り、中心都市シェマハを占領した。オズデミロウル・オスマン・パシャがここのベイレルベイに任命され、シルクロードの北の支線はオスマンの統制下に入った。シルヴァンは、12年続くことになる東方戦争で最も多く手が替わり、最も高くついた戦線となる。", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["バクーの占領 — カスピ海岸への到達", "eb5adab8"], "d": ["シルヴァン作戦の最後の環として、カスピ海の西岸にあるバクー港が占領された。都市の周辺の石油の井戸は、当時すでに知られた収入源であり、港はカスピ海を経由して来るイラン絹の積み出し地点であった。オスマン帝国はこうして歴史上初めて、そして唯一、カスピ海に面する沿岸の所有者となった。", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["エレヴァン(Revan、Erivan)の征服と要塞の建設", "7f623b7b"], "d": ["カルスでエレヴァンに行ってそこに要塞を築くよう命じられたフェルハド・パシャはエレヴァンに進軍し、都市はヒジュラ暦991年ラマダーン月の初め（1583年9月中旬）にオスマンの統制下に入った。アラス川流域の北の門を押さえるエレヴァンには新しく大きな要塞が築かれ、都市はベイレルベイ領の中心とされた。カルスとタブリーズの間の軍道の中央に立つエレヴァンは、東部戦線の兵站の背骨であった。要塞は非常に堅固に造られ、その後200年のあいだ、オスマン・イラン戦争の不動の目標となった。", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["カラバフとギャンジャの併合", "29abaead"], "d": ["10年に及ぶ東方戦争の最後の獲得として、フェルハド・パシャは1588年にギャンジャに進軍し、9月1日に都市に入った。クル川とアラス川の間のカラバフ地方とその中心ギャンジャがオスマンの統治に置かれた。こうしてシルヴァン、エレヴァン、カラバフが結びついて、コーカサスに途切れのないオスマンの線ができた。1590年に署名されたフェルハド・パシャ条約がこの国境を確認することになるが、獲得はわずか20年しか保持できなかった。", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["ビハチの征服", "651a7275"], "d": ["ボスニア総督テッリ・ハサン・パシャは、1591年11月にビハチの前衛の城リパチを奪った後、1592年に都市と城自体も占領した。10日間の包囲の後、司令官ラムベルクは降伏した。この征服はボスニア国境をウナ川沿いに押し進め、1年後にテッリ・ハサン・パシャがクルパ(Kulpa)の前で殉死して勃発する長期戦争の前夜における、オスマン最後の大きな獲得となった。", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["オスマン-オーストリア「長期戦争」の開始", "bd22c392"], "d": ["ボスニア総督テッリ・ハサン・パシャがクルパ(シサク)の前で敗れて殉死したことを受け、オスマン国家はオーストリアに宣戦し、13年続く長期戦争が始まった。火器を持つ歩兵が決定的となったこの戦争は、オスマンの軍制でセクバン(銃兵)と火縄銃兵の雇用を加速させ、ティマール制のスィパーヒーの衰退を深めた。戦争は1606年のジトヴァトロク条約で終わることになる。", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["コジャ・スィナン・パシャ、オーストリア遠征に出発 - 長期戦争の最初の遠征", "d4a2f46d"], "d": ["ボスニア総督ハサン・パシャがシサク(Sisak)の前で敗れて殉死した後、大宰相コジャ・スィナン・パシャは、巧みな言葉と約束でスルタンを戦争に同意させ、1万2千人のイェニチェリとその他の部隊とともに出発した。こうして13年続くオスマン-オーストリア戦争の最初の遠征が開かれた。", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["ジェール(Győr、ヤヌクカレ)の征服", "14b75207"], "d": ["大宰相コジャ・スィナン・パシャは、1か月を超える包囲の後、ウィーンへの道の鍵とされるヤヌクカレ(ジェール)を接収した。城の陥落はヨーロッパに大きなパニックを引き起こし、長期戦争におけるオスマンの最も輝かしい獲得となった。しかし城は4年間しか保持できないことになる。", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["ムラト3世の死去", "1b62e886"], "d": ["21年の治世の後、ムラト3世は、ワラキア軍がブライラを焼いてシリストラにまで達していた日々に死去し、アヤソフィアの墓域に葬られた。マニサから呼び寄せられた子メフメト3世は10日後にイスタンブルに着いて即位した(1595年1月27日)。", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["エステルゴムのオーストリアへの喪失", "f420d333"], "d": ["カール・フォン・マンスフェルトが率いた包囲で十分な援助を得られなかったエステルゴムの守備兵は、城をマティアス大公に引き渡した。52年のオスマン支配が終わったことで、ドナウ線の防衛の連鎖が断ち切られ、ブダが直接の脅威にさらされた。城は10年後の1605年になってようやく取り戻されることになる。", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["エゲル城の征服", "3e511629"], "d": ["3週間続いた戦いの後、オスマンがそれまでどうしても奪えなかった堅固なエゲル城が、守備兵の降伏により陥落した。スルタン自らが臨んだこの征服は、失われたエステルゴムが生んだ士気をいくらか回復させ、エゲル州が設置された。2週間後に得たハチョヴァの勝利とともに、1596年は長期戦争でオスマンが最も成功した年となった。", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["ジェール(Győr、ヤヌクカレ)の喪失", "b4ccc679"], "d": ["ミクローシュ・パールフィとアドルフ・フォン・シュヴァルツェンベルク指揮下の部隊は、奇襲で城門を爆破してヤヌクカレを取り戻した。4年前にコジャ・スィナン・パシャが多大な労力で得た城の喪失は、オスマンのハンガリーにおける前線を崩壊させた。同年ブダを包囲した敵軍は撃退されたが、戦争の均衡はしだいに消耗戦に変わっていった。", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["カラヤズィジュ・アブデュルハリムの蜂起", "30493b0d"], "d": ["長期戦争で軍から逃れたセクバンとレヴェンドを集めたカラヤズィジュ・アブデュルハリムは、中央アナトリアの広い地域を支配下に収め、ウルファ城を奪い(1599年11月)、「ハリム・シャー」の称号でスルタン位を宣言して自らのトゥグラを帯びた勅令を送った。大ジェラーリー波の最初の指導者とされるカラヤズィジュは1602年に死に、運動は弟のデリ・ハサンが続けた。蜂起は、アナトリアの農民が大挙して土地を去る「大逃散」の時代の始まりである。", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["ティリヤキ・ハサン・パシャのカニジェ防衛", "d56a5e6a"], "d": ["1年前に征服されたカニジェを取り戻そうとしたフェルディナント大公とその同盟者たちは、城を2か月以上包囲した。ティリヤキ・ハサン・パシャは9千の兵で抵抗した。外からの援助を得られないにもかかわらず総攻撃を撃退し、出撃作戦で敵に大きな損害を与えて撤退に追い込んだ。この防衛はオスマンの歴史叙述で叙事詩となり、「カニジェ攻囲記」はそれ自体が一つの文学ジャンルとなった。", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["メフメト3世の死去とアフメト1世の即位", "da735fde"], "d": ["メフメト3世の12月20日の死により、14歳の子アフメト1世が王位に就いた。幼い年齢で、サンジャク(地方総督)の経験を経ずに王位に就いた最初のスルタンであることは、王子たちを地方で育てる慣行が事実上終わったことを示す。アフメト1世の治世には、兄弟殺しが放棄され、「エクベリイェト」(最年長の男子成員が王位を継ぐ)の原則に移ることになる。", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["エステルゴムの奪還", "7330f273"], "d": ["大宰相ララ・メフメト・パシャは、10年前に失われたエステルゴムを包囲して再びオスマンの統治に加えた。同じ遠征のうちにペシュトとヴァーツも取り戻され、オスマンはハンガリーの戦線を立て直した。この成功は、翌年のジトヴァトロクで比較的強い立場で交渉の席に着くことを可能にした。エステルゴムは1683年までオスマンの手に残ることになる。", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["オルチュ平原の勝利とジャンボラトオウルの反乱の鎮圧", "30f93532"], "d": ["アレッポで独立した侯国を築いてトスカーナとの同盟を探ったジャンボラトオウル・アリ・パシャは、大宰相クユジュ・ムラト・パシャによってオルチュ平原で大敗した。シリアで中央の権威が再建されたことで、ジェラーリー波の最も危険な一派は砕かれた。クユジュ・ムラト・パシャの2年続いた容赦ない粛清は、一時的ではあれアナトリアの治安を回復させた。", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["アラチャユルの勝利とカレンデルオウルの反乱の鎮圧", "55db0485"], "d": ["マニサとブルサ周辺から貢納を取り立てていたジェラーリーの指導者カレンデルオウルは、クユジュ・ムラト・パシャによってアラチャユルで大敗し、イランへ逃れざるを得なかった。この勝利で、アナトリアの大ジェラーリー軍の最後のものが解散させられた。クユジュ・ムラト・パシャが、殺させた反乱者たちを掘らせた井戸に詰めたと伝えられる厳しい粛清は、短期的には秩序をもたらしたが、アナトリアの人口と生産の損失を埋め合わせることはできなかった。", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["オランダへの最初のアフドナーメ(通商特許状)の付与", "5d9d117e"], "d": ["ネーデルラント連邦共和国の使節コルネリス・ハーガは、アフメト1世から、フランスとイギリスに与えられたものと同じ範囲のアフドナーメを得ることに成功した。オランダはこうして、イスタンブルに大使館を、オスマンの港に領事館を開く権利と、自国の旗で交易する権利を得た。このアフドナーメは、地中海交易でヴェネツィアに取って代わった北方の海洋国家がオスマン市場に入ったことを象徴する。", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["アフメト1世の死とムスタファ1世の即位 - エクベリイェトの慣行", "9901c09e"], "d": ["51日間続いた胃の病の後、28歳のアフメト1世が死去し、王位には息子の代わりに弟のムスタファ1世が就けられた。こうして父から子へ継ぐ継承の慣行は放棄され、王家で最年長の男子成員が王位を継ぐ「エクベリイェト」制に事実上移った。96日間続いたこの最初の治世は、王子たちが「カフェス(鳥籠)」で育てられる時代の始まりでもある。", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["ムスタファ1世の廃位とゲンチ・オスマン(オスマン2世)の即位", "e0f552f2"], "d": ["精神状態が正常でないことを理由に、ムスタファ1世は96日後に王位を降ろされ、アフメト1世の14歳の子オスマン2世がスルタンとなった。ハサンベイザーデに基づく伝承によれば、この廃位の決定には宦官長（キズラル・アー）ムスタファ・アーが影響した。ゲンチ・オスマンは、イェニチェリ軍団を廃して新しい軍を築く構想をもったことから、オスマンの改革論議における最初の急進的な人物とされる。この構想は4年後に自身の命を奪うことになる。", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["サラーヴ条約 - イランとの和平の更新", "e778aca8"], "d": ["プリ・シケステの敗北の後にイランと結ばれたサラーヴ条約は、1612年のナスーフ・パシャ条約の条件をおおむね確認した。サファヴィー朝が送る年間の絹の量は200荷から100荷に減らされた。こうして1603年から続いた東方戦争の第二局面は閉じた。和平は長続きせず、バグダードが1623年に失われると戦争は再燃することになる。", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["ホティン遠征とホティン条約", "bc4c823c"], "d": ["オスマン2世が自ら指揮した大軍に対し、ホトキェヴィチがホティンの前に築いた要塞化した陣営は突破できず、数か月続いた攻撃からも成果は得られなかった。10月9日に結ばれた条約でドニエストル川が国境とされ、ポーランド人はコサックの襲撃を防ぐことを約束した。勝利として発表されたにもかかわらず成果を出せなかった遠征は、若いスルタンのイェニチェリへの不信と、軍団を粛清する意図を強めた。", "7d812c58"]}
});
